-- Waypath+ arcade (hidden): the XP you earn while levelling pays out coins, and coins buy
-- packs of five collectible cards: iconic items, NPCs and places from the world. Every card can
-- come as a common, a rare, a holo or a full-art print. Nothing here is announced; /wp arcade
-- opens it. Coins and cards are saved for the whole account (WaypathDB.arcade).
-- The card list is ArcadeCards.lua (generated by tools/arcade/gen.py).
local _, RG = ...

local KIND = { "Item", "NPC", "Place", "Raider" }
local TIER = {  -- how rare the subject itself is: draw weight, name colour
  -- (dw: the weight in a dungeon pack, where a dungeon's top boss and its purple drops are the rare pulls)
  { "Mundane", 44, { 0.78, 0.78, 0.8 }, dw = 40 }, { "Uncommon", 26, { 0.3, 0.85, 0.3 }, dw = 34 }, { "Renowned", 14, { 0.3, 0.55, 1 }, dw = 20 },
  { "Epic", 12, { 0.7, 0.35, 0.95 }, dw = 6 }, { "Legendary", 4, { 1, 0.6, 0.1 }, dw = 2 },
  { "Artifact", 3, { 1, 0.2, 0.35 } },   -- the Raiders
  -- the six chase cards (ArcadeMythic.lua): never rolled with the others, see openOne. rate: the chance that a pack's
  -- last card is a Mythic (a jumbo counts as more than one pack); ring: ... that it is The 1 Ring (once per account)
  { "Mythic", 0, { 1, 0.9, 0.55 }, rate = 1 / 150, ring = 1 / 5000 },   -- 1 in 400 until 1.36: too rare to ever see
}
local FINISH = {  -- finish names, draw weights, power bonus, sell price
  { "Common", 70, 0, 1 }, { "Rare", 22, 6, 3 }, { "Holo", 6, 16, 5 }, { "Full art", 2, 30, 15 },
