-- WoW Forever launch: November 4 2026, 3 p.m. PST (23:00 UTC)
local LAUNCH = 1793833200
-- beta: every pack of every kind is free; from the launch on, packs cost coins (the balance below)
local FREE_PACKS = (time and time() or LAUNCH) < LAUNCH
-- RELEASE BALANCE (checked with tools/arcade/economy.py): a player who levels 1-60 earns about 10,000 coins
-- (XP, level-ups, quests, kills, skill-ups, goals, duels, set rewards, and the bonuses in ArcadeRewards.lua)
-- plus about 190 packs' worth of free cards (daily packs, a reward Jumbo every 7th day, milestone, dungeon,
-- quest-line and gear packs, and the level 60 gift). Spent on packs at about 10 coins a card, with extras sold
-- back, that gives a median of about 76% of the Master Set (every card, in any finish) at level 60: about 68%
-- for a light player and about 90% for a heavy one. COLLECTOR_LUCK and the pack prices tune it.
-- three kinds of pack, and every card in the game can come out of any of them
local PACKS = {
  normal = { name = "Pack", size = 5, price = 52, rares = 1, weight = 1, col = { 0.956, 0.853, 0.649 } },
  jumbo = { name = "Jumbo Pack", size = 8, price = 84, rares = 2, weight = 2, col = { 1, 0.8, 0.4 } },
  super = { name = "Super Jumbo Pack", size = 12, price = 120, rares = 3, weight = 3, col = { 1, 0.45, 0.52 } },
  -- a dungeon's own pack: only that dungeon's cards. Free for clearing it; once cleared, also for coins
  dungeon = { name = "Dungeon Pack", size = 5, price = 70, rares = 1, weight = 1, col = { 0.55, 0.8, 1 } },
}
local PACK_ORDER = { "normal", "jumbo", "super" }
local PACK_MAX = 12
-- packs you earn (milestones, dungeons, quest chains, gear, the level 60 gift) wait here until you open them
local function tok(a) a.tok = a.tok or { normal = 0, jumbo = 0, super = 0 }; return a.tok end
local function tokenCount(a, kind)
  local t = tok(a)
  if kind == "normal" then return (a.free or 0) + (t.normal or 0)
  elseif kind == "jumbo" then return (a.bonus or 0) + (t.jumbo or 0) end
  return t.super or 0
end
local function packPrice(kind) return FREE_PACKS and 0 or PACKS[kind or "normal"].price end
local PACK_PRICE, PACK_SIZE = packPrice("normal"), 5
-- How coins are earned, before the x1.2 EARN_RATE (about 6,500 coins over a 1-60 climb, see RELEASE BALANCE above):
--   XP: 1 coin per 4% of a level          level-up: 5 + level/5 (+25 at every 10th level)
--   quest turn-in: 3 + level/20           mob kills (that give XP): 1 coin per 4
--   profession skill-ups: 1 coin per 2    duel win: 4
-- There is no daily limit (there was one up to 1.11.0); quests, kills and skill-ups are still counted per day for the Today tab.
local EARN_RATE = 1.2         -- every coin earned from play counts 20% more (launch feedback: packs came too slowly)
local COLLECTOR_LUCK = 0.10   -- each card has this chance to be one you do not own yet (a small mercy, so the last cards do not take forever)
local MASTER_GOAL = 0.75

local CARDS = {}
for i, d in ipairs(RG.ARCADE_DATA or {}) do
  CARDS[i] = { id = i, kind = d[1], name = d[2], tier = d[3], ref = d[4], text = d[5], dun = d[6], field = d[7], bound = d[8], key = d[9] }
  local my = d[3] == 7 and RG.ARCADE_MYTHIC and RG.ARCADE_MYTHIC[d[2]]
  if my then CARDS[i].mythic = my; if my.icon then CARDS[i].icon = "Interface\\Icons\\" .. my.icon end end
end
RG.ARCADE_CARDS = CARDS
-- Raiders: super rare cards of characters you have met (you, your group, anyone who chats near you),
-- shown as their race in the best raid armour of their class. Saved with the collection, so the set
-- grows as you play. Holo or full art only.
local RACE_DIR = { Human = "Human", Dwarf = "Dwarf", NightElf = "NightElf", Gnome = "Gnome", Orc = "Orc", Scourge = "Scourge", Undead = "Scourge", Tauren = "Tauren", Troll = "Troll", BloodElf = "BloodElf", Draenei = "Draenei" }
local MAX_RAIDERS = 400
local byKey = {}
for _, c in ipairs(CARDS) do byKey[c.key or c.name] = c end   -- (a dungeon's Mythic shares its boss's name: its own key)
local function addRaider(name, class, race, sex)
  if not name or not class or byKey["@" .. name] then return end
  if #CARDS >= #(RG.ARCADE_DATA or {}) + MAX_RAIDERS then return end
  local cname = class:sub(1, 1) .. class:sub(2):lower()
  local c = { id = #CARDS + 1, kind = 4, key = "@" .. name, name = name, tier = 6, ref = 0, class = class, race = race, sex = sex,
              text = (race or "") .. " " .. cname .. " in raid gear", icon = "Interface\\Icons\\ClassIcon_" .. cname }
  CARDS[#CARDS + 1] = c; byKey[c.key] = c
  RG.ArcadePoolsDirty = true
  return true
end

RG.ArcadeAddRaider = addRaider
local raidersLoaded
local function store()
  if not WaypathDB then return nil end
  local a = WaypathDB.arcade
  if not a then a = { coins = 0, cards = {}, acc = 0, packs = 0, wins = 0, losses = 0, v = 3 }; WaypathDB.arcade = a end
  if (a.v or 0) < 2 then   -- the first, creature-only set: swap each card for coins
    local n = 0
    for _, c in pairs(a.cards or {}) do if type(c) == "number" and c > 0 then n = n + 10 end end
    a.cards = {}; a.coins = (a.coins or 0) + n; a.v = 2
  end
  if a.v == 2 then   -- cards were saved by list position; keep them by name so the list can grow
    local moved = {}
    for id, slot in pairs(a.cards) do if type(id) == "number" and CARDS[id] then moved[CARDS[id].name] = slot end end
    a.cards = moved; a.v = 3
  end
  a.raiders = a.raiders or {}
  if not raidersLoaded then
    raidersLoaded = true
    for name, r in pairs(a.raiders) do addRaider(name, r[1], r[2], r[3]) end
  end
  a.cards = a.cards or {}
  -- an Arena card update: changed cards sell back for their full crafting value for two weeks
  local P = RG.ARCADE_PATCH
  -- Only the copies you owned when the update came are refundable: they are counted then (a.refundOwned), so cards
  -- pulled later sell at the normal price
  local function snapshot()
    local own, n = {}, 0
    for k in pairs(P.changed or {}) do
      local slot = a.cards[k]
      if type(slot) == "table" then
        local t
        for f = 1, 4 do if (slot[f] or 0) > 0 then t = t or {}; t[f] = slot[f]; n = n + slot[f] end end
        own[k] = t
      end
    end
    a.refundOwned = own
    return n
  end
  if P and a.refundPatch ~= P.id then
    a.refundPatch, a.refundUntil = P.id, time() + 14 * 86400
    local n = snapshot()
    if n > 0 and RG.Print then
      RG.Print("Arena card update: " .. (P.note or "some cards changed") .. ". " .. n .. " of your cards changed. Until " .. date("%b %d", a.refundUntil)
        .. ", those copies sell back for their full crafting value: press Refund on a changed card, or Sell extras. Copies you get later sell at the normal price.")
    end
  elseif P and a.refundPatch == P.id and not a.refundOwned then
    snapshot()   -- (a window that opened before refunds were counted: the copies you hold now count)
  end
  return a
end
local function owned(a, id) local c = a.cards[CARDS[id].key or CARDS[id].name]; return c and ((c[1] or 0) + (c[2] or 0) + (c[3] or 0) + (c[4] or 0)) or 0 end
local function bestFinish(a, id) local c = a.cards[CARDS[id].key or CARDS[id].name]; if not c then return nil end; for f = 4, 1, -1 do if (c[f] or 0) > 0 then return f end end end

-- ---------------------------------------------------------------------------
-- Coins from XP: 1 coin for every 2% of a level you gain
-- ---------------------------------------------------------------------------
local lastXP, lastMax
-- pay out: kind is "xp", "level", "quest", "kill", "skill" or "duel"; amount is in coins (fractions are carried over)
local function give(kind, amount, capped)
  local a = store(); if not a then return end
  a.acc = type(a.acc) == "table" and a.acc or {}
  a.stats = a.stats or {}
  amount = amount * EARN_RATE
  if capped then
    local today = date and date("%Y-%m-%d") or "today"
    if a.day ~= today then a.day, a.dayCoins = today, 0 end
    a.dayCoins = a.dayCoins or 0
  end
  a.acc[kind] = (a.acc[kind] or 0) + amount
  local coins = math.floor(a.acc[kind])
  if coins > 0 then
    a.acc[kind] = a.acc[kind] - coins
    a.coins = (a.coins or 0) + coins
    a.stats[kind] = (a.stats[kind] or 0) + coins
    if capped then a.dayCoins = (a.dayCoins or 0) + coins end
  end
  -- once a day, after you have opened the cards window at least once, say when a pack is affordable
  local d = date and date("%Y-%m-%d") or "today"
  if a.seen and PACK_PRICE > 0 and (a.coins or 0) >= PACK_PRICE and a.hintDay ~= d then
    a.hintDay = d
    if RG.Print then RG.Print("You have enough coins for a card pack. /wp cards") end
  end
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
end
RG.ArcadeGive = give
local function earn(gainPct) give("xp", gainPct / 4) end
local ev = CreateFrame("Frame")
ev:RegisterEvent("PLAYER_LOGIN"); ev:RegisterEvent("PLAYER_XP_UPDATE"); ev:RegisterEvent("PLAYER_LEVEL_UP"); ev:RegisterEvent("GROUP_ROSTER_UPDATE"); ev:RegisterEvent("UPDATE_MOUSEOVER_UNIT"); ev:RegisterEvent("QUEST_TURNED_IN")
for _, e in ipairs({ "CHAT_MSG_SKILL", "CHAT_MSG_COMBAT_XP_GAIN" }) do pcall(ev.RegisterEvent, ev, e) end
for _, e in ipairs({ "SAY", "YELL", "PARTY", "PARTY_LEADER", "RAID", "RAID_LEADER", "GUILD", "WHISPER", "CHANNEL" }) do pcall(ev.RegisterEvent, ev, "CHAT_MSG_" .. e) end

local function meet(name, class, race, sex)
  -- (names the game hides from add-ons, "secret" values, can't be compared or kept)
  if RG.IsSecret and (RG.IsSecret(name) or RG.IsSecret(class) or RG.IsSecret(race) or RG.IsSecret(sex)) then return end
  if type(name) ~= "string" then return end
  local a = store(); if not a or name == "" then return end
  name = name:match("^([^-]+)") or name
  if a.raiders[name] then return end
  local n = 0; for _ in pairs(a.raiders) do n = n + 1 end
  if n >= MAX_RAIDERS then return end
  a.raiders[name] = { class, race, sex }
  addRaider(name, class, race, sex)
end
ev:SetScript("OnEvent", function(_, event, text, author, _, _, _, _, _, _, _, _, _, guid)
  if event == "PLAYER_LEVEL_UP" then
    local lvl = tonumber(text) or (UnitLevel and UnitLevel("player")) or 1
    give("level", 5 + math.floor(lvl / 5) + (lvl % 10 == 0 and 25 or 0))
  elseif event == "QUEST_TURNED_IN" then
    give("quest", 3 + math.floor(((UnitLevel and UnitLevel("player")) or 1) / 20), true)
    return
  elseif event == "CHAT_MSG_SKILL" then
    if type(text) == "string" and not (RG.IsSecret and RG.IsSecret(text)) and text:find("%d+") then give("skill", 0.5, true) end
    return
  elseif event == "CHAT_MSG_COMBAT_XP_GAIN" then
    if type(text) == "string" and not (RG.IsSecret and RG.IsSecret(text)) and text:find("dies", 1, true) then give("kill", 0.25, true) end
    return
  end
  if event:find("^CHAT_MSG_") then
    if author and guid and GetPlayerInfoByGUID and not (RG.IsSecret and (RG.IsSecret(author) or RG.IsSecret(guid))) then
      local ok, _, class, _, race, sex, name = pcall(GetPlayerInfoByGUID, guid)
      if ok and class and name then meet(name, class, race, sex) end
    end
    return
  end
  if event == "UPDATE_MOUSEOVER_UNIT" then
    -- (any of these can come back "secret" on this client: SafeCall turns those into nil)
    if RG.SafeCall(UnitExists, "mouseover") and RG.SafeCall(UnitIsPlayer, "mouseover") and not RG.SafeCall(UnitIsUnit, "mouseover", "player") then
      local class = select(2, pcall(function() return select(2, UnitClass("mouseover")) end)); local race = select(2, pcall(function() return select(2, UnitRace("mouseover")) end))
      meet(RG.SafeCall(UnitName, "mouseover"), RG.Safe(class), RG.Safe(race), RG.SafeCall(UnitSex, "mouseover"))
    end
    return
  end
  if event == "GROUP_ROSTER_UPDATE" then
    for i = 1, 4 do
      local u = "party" .. i
      if RG.SafeCall(UnitExists, u) and RG.SafeCall(UnitIsPlayer, u) then
        local class = select(2, pcall(function() return select(2, UnitClass(u)) end)); local race = select(2, pcall(function() return select(2, UnitRace(u)) end))
        meet(RG.SafeCall(UnitName, u), RG.Safe(class), RG.Safe(race), RG.SafeCall(UnitSex, u))
      end
    end
    return
  end
  if event == "PLAYER_LOGIN" and UnitName then
    local _, class = UnitClass("player"); local _, race = UnitRace("player")
    meet(UnitName("player"), class, race, UnitSex and UnitSex("player"))
  end
  if not (UnitXP and UnitXPMax) then return end
  local xp, max = UnitXP("player"), UnitXPMax("player")
  if not xp or not max or max <= 0 or (RG.IsSecret and (RG.IsSecret(xp) or RG.IsSecret(max))) then return end
  if event == "PLAYER_LOGIN" then lastXP, lastMax = xp, max; return end
  if event == "PLAYER_LEVEL_UP" then return end -- the XP update that follows carries the numbers
  if lastXP then
    local gain
    if xp >= lastXP then gain = xp - lastXP else gain = (lastMax or max) - lastXP + xp end
    if gain > 0 and gain < (lastMax or max) * 3 then earn(gain / max * 100) end
  end
  lastXP, lastMax = xp, max
end)

-- ---------------------------------------------------------------------------
-- Rolling cards
-- ---------------------------------------------------------------------------
local byTier, tierWeight
local function buildPools()   -- (the Raiders pool only counts once there is one)
  byTier, tierWeight = {}, 0
  for _, c in ipairs(CARDS) do if not c.dun then byTier[c.tier] = byTier[c.tier] or {}; table.insert(byTier[c.tier], c) end end
  for t = 1, #TIER do if byTier[t] then tierWeight = tierWeight + TIER[t][2] end end
  -- dungeon packs: { [dungeon] = { list, byTier, weight } } from ArcadeDungeons.lua (cards found by name)
  RG.ArcadeDunPools = {}
  for _, d in ipairs(RG.ARCADE_DUNGEONS or {}) do
    local p = { list = {}, byTier = {}, weight = 0, name = d[1], iid = d[2], lo = d[3], hi = d[4] }
    for _, n in ipairs(d[5]) do
      local c = byKey[n]
      if c and c.tier < 6 and not c.field then p.list[#p.list + 1] = c; p.byTier[c.tier] = p.byTier[c.tier] or {}; table.insert(p.byTier[c.tier], c) end
    end
    for t = 1, 5 do if p.byTier[t] then p.weight = p.weight + (TIER[t].dw or 0) end end
    if #p.list > 0 then RG.ArcadeDunPools[d[1]] = p end
  end
end
local function rollCard(a, dn)
  if not byTier or RG.ArcadePoolsDirty then buildPools(); RG.ArcadePoolsDirty = nil end
  -- a dungeon pack: that dungeon's cards only (the same small mercy for ones you don't have)
  local dp = dn and RG.ArcadeDunPools[dn]
  if dp then
    if a and math.random() < COLLECTOR_LUCK then
      local missing = {}
      for _, c in ipairs(dp.list) do if owned(a, c.id) == 0 then missing[#missing + 1] = c end end
      if #missing > 0 then return missing[math.random(#missing)] end
    end
    local x, tier = math.random() * dp.weight, nil
    for t = 1, 5 do if dp.byTier[t] then x = x - (TIER[t].dw or 0); if x <= 0 then tier = t; break end end end
    local pool = dp.byTier[tier] or dp.list
    return pool[math.random(#pool)]
  end
  if a and math.random() < COLLECTOR_LUCK then
    local missing = {}
    for _, c in ipairs(CARDS) do if c.kind ~= 4 and c.tier ~= 7 and not c.dun and owned(a, c.id) == 0 then missing[#missing + 1] = c end end
    if #missing > 0 then return missing[math.random(#missing)] end
  end
  local x = math.random() * tierWeight
  local tier = 1
  for t = 1, #TIER do
    if byTier[t] and TIER[t][2] > 0 then x = x - TIER[t][2]; if x <= 0 then tier = t; break end end
  end
  local pool = byTier[tier] or byTier[1]
  return pool[math.random(#pool)]
end
local function rollFinish(atLeast)
  local total = 0
  for f = atLeast or 1, #FINISH do total = total + FINISH[f][2] end
  local x = math.random() * total
  for f = atLeast or 1, #FINISH do x = x - FINISH[f][2]; if x <= 0 then return f end end
  return atLeast or 1
end

-- ---------------------------------------------------------------------------
-- Sets, daily goals, free pack
-- ---------------------------------------------------------------------------
local function setOf(c)
  if c.dun then return c.dun end   -- a dungeon's own card: that dungeon's set
  if c.tier == 7 then return "Mythic"
  elseif c.kind == 3 then
    local z = c.text:match("^Found in (.+)$")
    return z and ("Places in " .. z) or "All zones"
  elseif c.kind == 2 then
    local rank, ty = c.text:match("^(.-), level %d+ (%a+)$")
    if rank then return ty:sub(1, 1):upper() .. ty:sub(2) .. " " .. (rank == "Boss" and "bosses" or "rares") end
    return "Other NPCs"
  elseif c.kind == 1 then
    if c.text:find("^Legendary") then return "Legendary items" end
    local il = tonumber(c.text:match("item level (%d+)")) or 0
    return "Epic items, item level " .. math.floor(il / 10) * 10 .. "s"
  end
  return "Raiders: " .. (c.class and (c.class:sub(1, 1) .. c.class:sub(2):lower()) or "?")
end
local setCache, setCount
local function getSets()
  if setCache and setCount == #CARDS then return setCache end
  local by, list = {}, {}
  for _, c in ipairs(CARDS) do
    local n = setOf(c)
    if not by[n] then by[n] = { name = n, cards = {}, isDun = c.dun and true or nil }; list[#list + 1] = by[n] end
    table.insert(by[n].cards, c)
  end
  local out = {}
  for _, s in ipairs(list) do if #s.cards >= 3 and not by[s.name].isDun then s.reward = math.min(100, 10 + 2 * #s.cards); out[#out + 1] = s end end
  table.sort(out, function(x, y) return x.name < y.name end)
  -- each dungeon is a set of every card in its pack (easiest dungeon first, before the others)
  local duns = {}
  for _, d in ipairs(RG.ARCADE_DUNGEONS or {}) do
    local cs = {}
    for _, n in ipairs(d[5]) do if byKey[n] then cs[#cs + 1] = byKey[n] end end
    if #cs >= 3 then duns[#duns + 1] = { name = d[1], cards = cs, dungeon = true, raid = d.raid, holiday = d.holiday, lo = d[3], hi = d[4], mythic = RG.ARCADE_SET_MYTHIC and byKey[RG.ARCADE_SET_MYTHIC[d[1]] or ""], reward = math.min(d.raid and 150 or 100, (d.raid and 30 or 10) + 2 * #cs) } end
  end
  -- WoW Forever dungeons the game data has no bosses or loot for yet: shown, empty, as coming soon (no rewards)
  for _, dn in ipairs(RG.ARCADE_DUNGEONS_SOON or {}) do duns[#duns + 1] = { name = dn, cards = {}, dungeon = true, soon = true, reward = 0 } end
  -- the Field Guide: a page per zone of its rares, then the world bosses (ArcadeField.lua)
  for _, p in ipairs(RG.ARCADE_FIELD_PAGES or {}) do
    local cs = {}
    for _, n in ipairs(p[3]) do if byKey[n] then cs[#cs + 1] = byKey[n] end end
    if #cs >= 1 then duns[#duns + 1] = { name = p[1], zone = p[2], cards = cs, field = true, reward = math.min(100, 10 + 3 * #cs) } end
  end
  for i = #duns, 1, -1 do table.insert(out, 1, duns[i]) end
  setCache, setCount = out, #CARDS
  return out
end
local function setProgress(a, s, stage)
  local n, need = 0, (stage or 1)
  for _, c in ipairs(s.cards) do
    local f = bestFinish(a, c.id)
    if f and f >= need then n = n + 1 end
  end
  return n
end
-- the three stages of a set: every card (bronze), every card rare or better (silver), every card holo or better
-- (gold). Rewards: coins, plus a jumbo for silver and a super jumbo for gold; a dungeon's bronze adds two of its packs.
RG.ARCADE_STAGES = {
  { "Bronze", "every card", { 0.8, 0.55, 0.32 } },
  { "Silver", "every card rare or better", { 0.78, 0.82, 0.9 } },
  { "Gold", "every card holo or full art", { 1, 0.82, 0.3 } },
}
function RG.ArcadeStageReward(s, stage)
  local coins = stage == 1 and s.reward or (stage == 2 and math.floor(s.reward * 1.5) or s.reward * 3)
  local packs = stage == 2 and { jumbo = 1 } or (stage == 3 and { super = 1 } or nil)
  local dpk = (stage == 1 and s.dungeon and not s.holiday) and 2 or nil
  if s.field and stage == 1 then packs = { jumbo = 1 } end   -- (a Field Guide page: its Explorer badge and a jumbo pack)
  return coins, packs, dpk
end
function RG.ArcadeStageText(s, stage)
  local coins, packs, dpk = RG.ArcadeStageReward(s, stage)
  local t = "+" .. coins .. " coins"
  if packs and packs.jumbo then t = t .. ", a jumbo pack" end
  if packs and packs.super then t = t .. ", a super jumbo pack" end
  if dpk then t = t .. ", " .. dpk .. " " .. s.name:gsub("^The ", "") .. " packs" end
  if s.field and stage == 1 then t = t .. " and an Explorer badge" end
  return t
end
-- pay out every finished set once; returns the names
local function claimSets(a)
  a.setsDone = a.setsDone or {}    -- bronze (the first stage: what sets paid before stages)
  a.setStage = a.setStage or {}    -- [set] = highest stage paid
  local done, won = {}, {}   -- (won: for the celebration when the pack is open)
  for _, s in ipairs(getSets()) do
    local paid = a.setStage[s.name] or (a.setsDone[s.name] and 1 or 0)
    for stage = paid + 1, (#s.cards > 0 and 3 or 0) do
      if setProgress(a, s, stage) < #s.cards then break end
      local coins, packs, dpk = RG.ArcadeStageReward(s, stage)
      a.setStage[s.name] = stage
      if stage == 1 then a.setsDone[s.name] = true end
      a.coins = (a.coins or 0) + coins
      a.stats = a.stats or {}; a.stats.sets = (a.stats.sets or 0) + coins
      local t = tok(a)
      for k, n in pairs(packs or {}) do t[k] = (t[k] or 0) + n end
      if dpk then a.dpk = a.dpk or {}; a.dpk[s.name] = (a.dpk[s.name] or 0) + dpk end
      done[#done + 1] = s.name .. " " .. RG.ARCADE_STAGES[stage][1]:lower() .. " (" .. RG.ArcadeStageText(s, stage) .. ")"
      won[#won + 1] = { name = s.name, stage = stage, text = RG.ArcadeStageText(s, stage) }
    end
  end
  return done, won
end

local GOALS = {
  { "packs2", "Open 2 packs", 2, 5 }, { "packs3", "Open 3 packs", 3, 8 }, { "duel2", "Win 2 duels", 2, 5 },
  { "shiny", "Pull a holo or full art", 1, 8 }, { "new5", "Find 5 new cards", 5, 6 }, { "sell", "Sell your extras", 1, 3 },
  { "win3", "Win 3 arena duels", 3, 9 }, { "archm", "Beat the Archmage", 1, 10 },
}
local function today() return date and date("%Y-%m-%d") or "today" end
local function todaysGoals(a)
  if a.goals and a.goals.day == today() then return a.goals end
  local seed = tonumber(date and date("%j") or "1") + (tonumber(date and date("%Y") or "2026") or 0)
  local pick, used = {}, {}
  local k = 0
  while #pick < 3 do
    local i = (seed + k * 2) % #GOALS + 1; k = k + 1
    if not used[i] then used[i] = true; pick[#pick + 1] = GOALS[i][1] end
  end
  a.goals = { day = today(), pick = pick, prog = {}, done = {} }
  return a.goals
end
local function goalProgress(a, id, n)
  local g = todaysGoals(a)
  local def
  for _, d in ipairs(GOALS) do if d[1] == id then def = d end end
  local on = false
  for _, p in ipairs(g.pick) do if p == id then on = true end end
  if not def or not on or g.done[id] then return end
  g.prog[id] = (g.prog[id] or 0) + (n or 1)
  if g.prog[id] >= def[3] then
    g.done[id] = true
    a.coins = (a.coins or 0) + def[4]
    a.stats = a.stats or {}; a.stats.goal = (a.stats.goal or 0) + def[4]
    return def[2] .. " done (+" .. def[4] .. ")"
  end
end
-- one free pack a day (up to 3 saved)
local function dailyCheck()
  local a = store(); if not a then return end
  -- launch week (WoW Forever opens November 4 2026, 3 p.m. PST): two free packs a day instead of one, and a gift once
  local now = time and time() or 0
  local launchWeek = now >= LAUNCH and now < LAUNCH + 7 * 86400
  if a.freeDay ~= today() then a.freeDay = today(); a.free = math.min(launchWeek and 5 or 3, (a.free or 0) + (launchWeek and 2 or 1)) end
  if now >= LAUNCH and now < LAUNCH + 14 * 86400 and not a.launchGift and RG.ArcadeGrant then
    a.launchGift = true
    RG.ArcadeGrant("Welcome to WoW Forever! Launch gift", 100, { jumbo = 1 })
  end
  todaysGoals(a)
  local sz = RG.Rank and RG.Rank.checkSeason and RG.Rank.checkSeason(a)
  if sz and RG.ArcadeGrant then
    RG.ArcadeGrant("Season over: you reached " .. sz.peak.label .. ". New season, your rank is now " .. RG.Rank.info(sz.rating).label, sz.coins, sz.packs > 0 and { normal = sz.packs } or nil)
  end
end
RG.ArcadeDaily = dailyCheck

-- ---------------------------------------------------------------------------
-- Packs, selling, duels
-- ---------------------------------------------------------------------------
local PITY = 7   -- a pack after this many without a holo or full art always has one
local STREAK_BONUS = 7         -- a reward seal for every 7th day in a row you break a seal
local MANY_MAX = 10            -- most seals "Break all" opens at once

-- about how many cards you open for one specific card at one print (for the "1 in N" line)
local function cardOdds(c, f)
  if not byTier then buildPools(); RG.ArcadePoolsDirty = nil end
  local pool = byTier[c.tier]; if not pool or #pool == 0 or tierWeight <= 0 then return nil end
  local least = c.tier == 6 and 3 or 1
  local total = 0
  for k = least, #FINISH do total = total + FINISH[k][2] end
  local p = (TIER[c.tier][2] / tierWeight) / #pool * (FINISH[f][2] / total)
  if p <= 0 then return nil end
  return math.max(1, math.floor(1 / p + 0.5))
end
RG.ArcadeCardOdds = cardOdds
local function groupDigits(n)
  local t = tostring(n)
  while true do
    local r, k = t:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
    t = r; if k == 0 then break end
  end
  return t
end

RG.ArcadeFeatured = function() return nil end   -- (packs are no longer themed: every card can come out of every pack)
local function yesterdayStr() return date and time and date("%Y-%m-%d", time() - 86400) or "yesterday" end

-- a pack's odds, worked out from the same numbers openOne rolls with (shown on the pack screen)
function RG.ArcadePackOdds(kind)
  local def = PACKS[kind or "normal"] or PACKS.normal
  local function share(from, f0)   -- chance a card rolled "at least from" comes out at finish f0 or better
    local all, hit = 0, 0
    for f = from, #FINISH do all = all + FINISH[f][2]; if f >= f0 then hit = hit + FINISH[f][2] end end
    return hit / all
  end
  local plain, rare = def.size - def.rares, def.rares   -- the last cards are rare or better
  -- a Raider (once you have met some) always comes holo or better
  if not byTier or RG.ArcadePoolsDirty then buildPools(); RG.ArcadePoolsDirty = nil end
  local raider = (byTier[6] and #byTier[6] > 0 and tierWeight > 0) and (TIER[6][2] / tierWeight) * (1 - COLLECTOR_LUCK) or 0
  local function card(from, f0) return raider * share(3, f0) + (1 - raider) * share(from, f0) end
  local function anyOf(f0) return 1 - (1 - card(1, f0)) ^ plain * (1 - card(2, f0)) ^ rare end
  return { mythic = math.floor(1 / (TIER[7].rate * (def.weight or 1)) + 0.5), holo = anyOf(3), full = anyOf(4), size = def.size, rares = def.rares, pity = PITY }
end
-- one seal: pays for it, rolls the five cards, returns got, notes, meta
local function openOne(a, kind, dn)
  kind = PACKS[kind or "normal"] and (kind or "normal") or "normal"
  if kind == "dungeon" and not (dn and RG.ArcadeDunPools and RG.ArcadeDunPools[dn]) then
    if not byTier then buildPools() end
    if not (dn and RG.ArcadeDunPools[dn]) then return nil, "No cards for that dungeon." end
  end
  if kind ~= "dungeon" then dn = nil end
  local def = PACKS[kind]
  local bonus, free = false, false
  if kind == "dungeon" then
    -- a dungeon pack: one you earned there, else coins once you've cleared it
    a.dpk = a.dpk or {}
    if (a.dpk[dn] or 0) > 0 then free = true; a.dpk[dn] = a.dpk[dn] - 1
    elseif not ((a.dunClear and a.dunClear[dn]) or (a.dun and a.dun[dn])) then return nil, (RG.ArcadeIsRaid and RG.ArcadeIsRaid(dn)) and ("Defeat one of " .. dn .. "'s bosses to buy its packs.") or ("Clear " .. dn .. " once (three of its bosses) to buy its packs.")
    elseif (a.coins or 0) < packPrice(kind) then return nil, "A " .. dn .. " pack costs " .. packPrice(kind) .. " coins."
    else a.coins = a.coins - packPrice(kind) end
  elseif kind == "jumbo" and (a.bonus or 0) > 0 then bonus = true; a.bonus = a.bonus - 1   -- a reward pack is a jumbo
  elseif kind == "normal" and (a.free or 0) > 0 then free = true; a.free = a.free - 1
  elseif (tok(a)[kind] or 0) > 0 then free = true; tok(a)[kind] = tok(a)[kind] - 1
  elseif (a.coins or 0) < packPrice(kind) then return nil, "A " .. def.name:lower() .. " costs " .. packPrice(kind) .. " coins."
  else a.coins = a.coins - packPrice(kind) end
  local meta = { bonus = bonus, free = free, pityBefore = a.pity or 0, kind = kind, size = def.size, dungeon = dn }
  -- first seal of the day: the day's streak
  if a.packDay ~= today() then
    local n = (a.packDay == yesterdayStr()) and ((a.packStreak or 0) + 1) or 1
    a.packStreak, a.packDay = n, today()
    meta.daily, meta.streak = true, n
    if n % STREAK_BONUS == 0 then a.bonus = (a.bonus or 0) + 1; meta.streakReward = true end
  end
  meta.streak = meta.streak or a.packStreak or 1
  a.packs = (a.packs or 0) + 1
  local got, shiny, newCount = {}, false, 0
  local size = def.size
  -- a Mythic takes the last card's place: The 1 Ring (once per account, engraved with who opened it), or one of the others
  local mythic
  if not byTier or RG.ArcadePoolsDirty then buildPools(); RG.ArcadePoolsDirty = nil end
  local mroll, mw = math.random(), (def.weight or 1)
  if not a.ring and byKey["The 1 Ring"] and mroll < TIER[7].ring * mw then
    mythic = byKey["The 1 Ring"]
    a.ring = { by = (UnitName and UnitName("player")) or "?", date = today() }
  elseif mroll < TIER[7].rate * mw and dn and RG.ARCADE_SET_MYTHIC and byKey[RG.ARCADE_SET_MYTHIC[dn] or ""] then
    mythic = byKey[RG.ARCADE_SET_MYTHIC[dn]]   -- a dungeon's pack: that dungeon's own Mythic (ArcadeSetMythics.lua)
  elseif mroll < TIER[7].rate * mw and byTier[7] then
    local pool = {}
    for _, c in ipairs(byTier[7]) do if not (c.mythic and c.mythic.one) then pool[#pool + 1] = c end end
    if #pool > 0 then mythic = pool[math.random(#pool)] end
  end
  for i = 1, size do
    local c = rollCard(a, dn)
    if i == size and mythic then c = mythic end
    local least = c.tier == 6 and 3 or (c.tier == 7 and 4 or 1)
    if i > size - def.rares then least = math.max(least, 2) end   -- the last cards: rare or better (one in a pack, two in a jumbo, three in a super jumbo)
    if i == size then least = math.max(least, ((a.pity or 0) >= PITY or bonus) and 3 or 2) end   -- the last card: holo after a long dry spell or from a reward pack
    local f = rollFinish(least)
    local isNew = owned(a, c.id) == 0
    local slot = a.cards[c.key or c.name] or {}
    local newPrint = (not isNew) and (slot[f] or 0) == 0
    slot[f] = (slot[f] or 0) + 1
    a.cards[c.key or c.name] = slot
    got[#got + 1] = { card = c, finish = f, new = isNew, newPrint = newPrint, value = FINISH[f][4], odds = cardOdds(c, f), copies = owned(a, c.id) }
    if c.tier == 7 then got[#got].odds = math.floor(size / ((c.mythic and c.mythic.one) and TIER[7].ring or (c.dun and TIER[7].rate or (TIER[7].rate / 5))) + 0.5); meta.mythic = c.name end
    if f >= 3 then shiny = true end
    if isNew then newCount = newCount + 1 end
    local r = a.rarest
    if not r or (f * 10 + c.tier) > (r.finish * 10 + r.tier) then
      if r then got[#got].record = true end
      a.rarest = { name = c.name, finish = f, tier = c.tier }
    end
  end
  a.pity = shiny and 0 or ((a.pity or 0) + def.weight)   -- a bigger pack counts for more dry packs
  local notes = {}
  local function note(x) if x then notes[#notes + 1] = x end end
  note(goalProgress(a, "packs2", 1)); note(goalProgress(a, "packs3", 1))
  if shiny then note(goalProgress(a, "shiny", 1)) end
  if newCount > 0 then note(goalProgress(a, "new5", newCount)) end
  local doneSets, won = claimSets(a)
  for _, s in ipairs(doneSets) do notes[#notes + 1] = "Set reward: " .. s end
  if #won > 0 then meta.stagesWon = won end
  if meta.streakReward then notes[#notes + 1] = STREAK_BONUS .. " days in a row: a reward pack is waiting" end
  -- set progress for the sets these cards belong to
  local touched, order = {}, {}
  for _, g in ipairs(got) do
    local sn = (dn and g.card.tier ~= 7) and dn or setOf(g.card)
    if not touched[sn] then touched[sn] = { gained = 0 }; order[#order + 1] = sn end
    if g.new then touched[sn].gained = touched[sn].gained + 1 end
  end
  meta.sets = {}
  for _, sn in ipairs(order) do
    for _, s in ipairs(getSets()) do
      if s.name == sn then meta.sets[#meta.sets + 1] = { name = sn, have = setProgress(a, s), total = #s.cards, gained = touched[sn].gained } end
    end
  end
  table.sort(meta.sets, function(x, y) if x.gained ~= y.gained then return x.gained > y.gained end return x.name < y.name end)
  return got, notes, meta
end

local function pullScore(g) return g.finish * 10 + g.card.tier + (g.new and 0.5 or 0) end

function RG.ArcadeOpenPack(kind, dn)
  local a = store(); if not a or #CARDS == 0 then return nil, "No cards loaded." end
  dailyCheck()
  local got, notes, meta = openOne(a, kind, dn)
  if not got then return nil, notes end
  -- the best card comes last, as it does when you turn them one by one
  table.sort(got, function(x, y) return pullScore(x) < pullScore(y) end)
  return got, meta.free, notes, meta
end

-- packs waiting to be opened (earned, free or bought): the badge on Cards in the main window
function RG.ArcadePacksWaiting()
  local a = store(); if not a then return 0 end
  pcall(dailyCheck)
  return tokenCount(a, "normal") + tokenCount(a, "jumbo") + tokenCount(a, "super")
end
-- how many seals could "Break all" open right now
function RG.ArcadeSealsReady()
  local a = store(); if not a then return 0 end
  dailyCheck()
  local n = tokenCount(a, "normal") + tokenCount(a, "jumbo") + tokenCount(a, "super")
  if PACK_PRICE == 0 then n = math.max(n, 1) end
  return math.min(MANY_MAX, n)
end

-- open several seals in one go; the five best cards are shown, the rest are counted
function RG.ArcadeOpenMany()
  local a = store(); if not a or #CARDS == 0 then return nil, "No cards loaded." end
  dailyCheck()
  local n = RG.ArcadeSealsReady()
  if n < 2 then return RG.ArcadeOpenPack() end
  local all, notes, many = {}, {}, { count = 0, new = 0, newPrint = 0, value = 0, bonus = 0 }
  local last
  for _ = 1, n do
    local got, nt, meta = openOne(a, tokenCount(a, "super") > 0 and "super" or (tokenCount(a, "jumbo") > 0 and "jumbo" or "normal"))
    if not got then break end
    last = meta
    many.count = many.count + 1
    if meta.bonus then many.bonus = many.bonus + 1 end
    for _, g in ipairs(got) do
      all[#all + 1] = g
      if g.new then many.new = many.new + 1 elseif g.newPrint then many.newPrint = many.newPrint + 1 else many.value = many.value + g.value end
    end
    for _, x in ipairs(nt) do notes[#notes + 1] = x end
  end
  if many.count == 0 then return nil, "No packs to break." end
  many.total = #all
  table.sort(all, function(x, y) return pullScore(x) > pullScore(y) end)
  local show = {}
  for i = 1, math.min(5, #all) do show[i] = all[i] end
  table.sort(show, function(x, y) return pullScore(x) < pullScore(y) end)
  local meta = { many = many, size = #show, kind = "normal", streak = last and last.streak, daily = last and last.daily, sets = {}, free = true }
  local seen = {}
  for _, g in ipairs(all) do
    local sn = setOf(g.card)
    if not seen[sn] then
      seen[sn] = true
      for _, s in ipairs(getSets()) do if s.name == sn then meta.sets[#meta.sets + 1] = { name = sn, have = setProgress(a, s), total = #s.cards, gained = 0 } end end
    end
  end
  for _, g in ipairs(all) do if g.new then for _, m in ipairs(meta.sets) do if m.name == setOf(g.card) then m.gained = m.gained + 1 end end end end
  table.sort(meta.sets, function(x, y) if x.gained ~= y.gained then return x.gained > y.gained end return x.name < y.name end)
  return show, true, notes, meta
end

-- a bonus: coins and packs from a milestone, a dungeon, a quest line, a gear upgrade...
function RG.ArcadeGrant(label, coins, packs)
  local a = store(); if not a then return end
  coins = coins or 0
  a.coins = (a.coins or 0) + coins
  a.stats = a.stats or {}; a.stats.bonus = (a.stats.bonus or 0) + coins
  local t, bits = tok(a), {}
  if coins > 0 then bits[#bits + 1] = "+" .. coins .. " coins" end
  for _, k in ipairs(PACK_ORDER) do
    local n = packs and packs[k] or 0
    if n > 0 then t[k] = (t[k] or 0) + n; bits[#bits + 1] = n .. " " .. (k == "normal" and "pack" or (k == "jumbo" and "jumbo pack" or "super jumbo pack")) .. (n > 1 and "s" or "") end
  end
  local msg = "|cffffd36bWaypath Cards:|r " .. label .. "  (" .. table.concat(bits, ", ") .. ")"
  if RG.Notify then RG.Notify(msg) elseif RG.Print then RG.Print(msg) end
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end   -- (redraws only when the window is open)
  return msg
end

-- a dungeon's name on its pack: without "The", in capitals, on two lines when long
-- (and the font size that keeps it inside the pack's name banner: one line while it fits, smaller, then two)
function RG.ArcadePackLabel(dn)
  local t = dn:gsub("^The ", ""):upper()
  if #t <= 12 then return t, 14 end
  if #t <= 16 then return t, 11 end
  local cut = t:find(" ", math.floor(#t / 2) - 2) or t:find(" ")
  if cut then t = t:sub(1, cut - 1) .. "\n" .. t:sub(cut + 1) end
  return t, 10
end
-- a dungeon's packs (from clearing it, or a set reward); clearing it also lets you buy them
function RG.ArcadeGrantDungeon(dn, n, label)
  local a = store(); if not a or not dn then return end
  a.dpk = a.dpk or {}; a.dunClear = a.dunClear or {}
  a.dunClear[dn] = true
  if (n or 0) > 0 then a.dpk[dn] = (a.dpk[dn] or 0) + n end
  if label and (n or 0) > 0 then
    local msg = "|cffffd36bWaypath Cards:|r " .. label .. "  (" .. n .. " " .. dn:gsub("^The ", "") .. " pack" .. (n > 1 and "s" or "") .. ": open " .. (n > 1 and "them" or "it") .. " from the Album)"
    if RG.Notify then RG.Notify(msg) elseif RG.Print then RG.Print(msg) end
  end
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
end
function RG.ArcadeDungeonPacks(dn)
  local a = store(); if not a then return 0, false end
  return (a.dpk and a.dpk[dn]) or 0, ((a.dunClear and a.dunClear[dn]) or (a.dun and a.dun[dn])) and true or false   -- (a.dun: clears from before dungeon packs)
end
-- the level 60 present: three cards rated 105 or higher (new ones first) and five packs of every size
function RG.ArcadeGiftCards()
  local a = store(); if not a or #CARDS == 0 then return nil end
  local fresh, any = {}, {}
  for _, c in ipairs(CARDS) do
    if c.kind ~= 4 and c.tier ~= 7 and not c.dun then
      for f = 1, #FINISH do
        if (c.tier == 6 and 5.5 or c.tier) * 18 + FINISH[f][3] + (c.id % 7) >= 105 then
          local e = { c, f }
          any[#any + 1] = e
          if ((a.cards[c.key or c.name] or {})[f] or 0) == 0 then fresh[#fresh + 1] = e end
        end
      end
    end
  end
  local got, used = {}, {}
  for _ = 1, 3 do
    local pool = (#fresh > 0) and fresh or any
    local e
    for _ = 1, 40 do e = pool[math.random(#pool)]; if not used[e[1].id] then break end end
    used[e[1].id] = true
    local c, f = e[1], e[2]
    local isNew = owned(a, c.id) == 0
    local slot = a.cards[c.key or c.name] or {}
    local newPrint = (not isNew) and (slot[f] or 0) == 0
    slot[f] = (slot[f] or 0) + 1; a.cards[c.key or c.name] = slot
    got[#got + 1] = { card = c, finish = f, new = isNew, newPrint = newPrint, value = FINISH[f][4], odds = cardOdds(c, f), copies = owned(a, c.id) }
    local r = a.rarest
    if not r or (f * 10 + c.tier) > (r.finish * 10 + r.tier) then a.rarest = { name = c.name, finish = f, tier = c.tier } end
    for i = #fresh, 1, -1 do if fresh[i][1].id == c.id then table.remove(fresh, i) end end
  end
  table.sort(got, function(x, y) return pullScore(x) < pullScore(y) end)
  return got
end

-- reward seals: a guaranteed rare, and a holo or better to finish
function RG.ArcadeGrantBonus(n)
  local a = store(); if not a then return end
  a.bonus = (a.bonus or 0) + (n or 1)
  return a.bonus
end

-- Crafting: pick a card you are missing (or a finish you do not have) and pay coins for it. The price follows how rare
-- the subject is and how fancy the finish is; Raiders (your own characters) cannot be crafted.
local CRAFT_BASE = { 40, 80, 160, 320, 640 }
local CRAFT_FINISH = { 1, 2, 5, 12 }
function RG.ArcadeCraftCost(c, f)
  if not c or c.kind == 4 or c.field or c.bound or (c.tier or 6) > 5 then return nil end   -- (Field Guide and holiday cards come only from the world)
  return (CRAFT_BASE[c.tier] or 640) * (CRAFT_FINISH[f or 1] or 1)
end
function RG.ArcadeCraft(c, f)
  local a = store(); if not a then return false, "Nothing to craft with yet." end
  local cost = RG.ArcadeCraftCost(c, f)
  if not cost then return false, "That card cannot be crafted." end
  if (a.coins or 0) < cost then return false, "Crafting " .. c.name .. " (" .. FINISH[f][1] .. ") costs " .. cost .. " coins. You have " .. (a.coins or 0) .. "." end
  local key = c.key or c.name
  a.coins = a.coins - cost
  local slot = a.cards[key] or {}
  slot[f] = (slot[f] or 0) + 1
  a.cards[key] = slot
  a.stats = a.stats or {}; a.stats.crafted = (a.stats.crafted or 0) + cost
  a.crafted = (a.crafted or 0) + 1
  return true, "Crafted " .. c.name .. " (" .. FINISH[f][1] .. ") for " .. cost .. " coins."
end

-- after an Arena card update, a changed card sells back for its full crafting value for two weeks
function RG.ArcadeRefundOpen(a, key)
  local P = RG.ARCADE_PATCH
  return P and P.changed and P.changed[key] and a and a.refundPatch == P.id and (a.refundUntil or 0) > time() and true or false
end
-- how many copies of a print still sell back at full value: ones owned when the update came, not yet refunded or sold
function RG.ArcadeRefundable(a, key, f)
  if not RG.ArcadeRefundOpen(a, key) then return 0 end
  local t = a.refundOwned and a.refundOwned[key]
  local slot = a.cards and a.cards[key]
  return math.min(t and t[f] or 0, slot and slot[f] or 0)
end
function RG.ArcadeUseRefund(a, key, f, n)
  local t = a.refundOwned and a.refundOwned[key]
  if t and t[f] then t[f] = math.max(0, t[f] - n) end
end
function RG.ArcadeRefund(c, f)
  local a = store(); if not (a and c) then return false, "Nothing to refund." end
  local key = c.key or c.name
  if not RG.ArcadeRefundOpen(a, key) then return false, "This card can't be refunded." end
  local slot = a.cards[key]
  if not (slot and (slot[f] or 0) > 0) then return false, "You have no copy of that print." end
  if RG.ArcadeRefundable(a, key, f) < 1 then return false, "Only copies you owned when the card changed can be refunded." end
  local v = RG.ArcadeCraftCost(c, f) or 0
  slot[f] = slot[f] - 1
  RG.ArcadeUseRefund(a, key, f, 1)
  a.coins = (a.coins or 0) + v
  return true, "Refunded " .. c.name .. " (" .. FINISH[f][1] .. ") for " .. v .. " coins."
end

-- keep one of each print, sell the rest
function RG.ArcadeSellExtras()
  local a = store(); if not a then return 0, 0 end
  local coins, cnt, rn, rc = 0, 0, 0, 0
  for key, slot in pairs(a.cards) do
    local c = RG.ArcadeRefundOpen(a, key) and byKey[key]
    for f = 1, 4 do
      local n = slot[f] or 0
      if n > 1 then
        -- copies owned when the card changed sell at full value (the one you keep counts as one of them); the rest at
        -- the normal price
        local full = c and math.min(n - 1, math.max(0, RG.ArcadeRefundable(a, key, f) - 1)) or 0
        local fv = full > 0 and RG.ArcadeCraftCost(c, f) or nil
        if not fv then full = 0 end
        if full > 0 then rn = rn + full; rc = rc + full * fv; RG.ArcadeUseRefund(a, key, f, full) end
        coins = coins + (n - 1 - full) * FINISH[f][4]
        cnt = cnt + n - 1; slot[f] = 1
      end
    end
  end
  a.coins = (a.coins or 0) + coins + rc
  local g = cnt > 0 and goalProgress(a, "sell", 1)
  return cnt, coins + rc, g, rn, rc
end

local function power(c, f) return (c.tier == 6 and 5.5 or (c.tier == 7 and 6.5 or c.tier)) * 18 + FINISH[f or 1][3] + (c.id % 7) end
local function best(a)
  local b, bf, bp
  for _, c in ipairs(CARDS) do
    local f = bestFinish(a, c.id)
    if f then local p = power(c, f); if not bp or p > bp then b, bf, bp = c, f, p end end
  end
  return b, bf, bp
end
local lastDuel = 0
local DUEL_WAIT = 30
function RG.ArcadeDuel()
  local a = store(); if not a then return end
  local mine, mf
  if a.duelCard and byKey[a.duelCard] and bestFinish(a, byKey[a.duelCard].id) then
    mine = byKey[a.duelCard]; mf = bestFinish(a, mine.id)
  else mine, mf = best(a) end
  if not mine then return nil, "Open a pack first." end
  local now = GetTime and GetTime() or 0
  if lastDuel > 0 and now - lastDuel < DUEL_WAIT then return nil, "Your card is resting. Try again in " .. math.ceil(DUEL_WAIT - (now - lastDuel)) .. " seconds." end
  lastDuel = now
  local foe, ff = rollCard(), rollFinish()
  local BEATS = { [2] = 1, [1] = 3, [3] = 2, [4] = 2 }   -- NPC beats item, item beats place, place beats NPC
  local function score(c, f, o) local s = power(c, f) + math.random(0, 25); if BEATS[c.kind] == o.kind then s = s + 20 end; return s end
  local win = score(mine, mf, foe) >= score(foe, ff, mine)
  local prize, goal = 0, nil
  if win then
    prize = math.floor((4 + math.min(a.streak or 0, 4)) * EARN_RATE + 0.5)   -- +1 for each win in a row, up to +4 (then the +20%)
    a.coins = a.coins + prize; a.wins = (a.wins or 0) + 1; a.streak = (a.streak or 0) + 1
    a.stats = a.stats or {}; a.stats.duel = (a.stats.duel or 0) + prize
    goal = goalProgress(a, "duel2", 1)
  else a.losses = (a.losses or 0) + 1; a.streak = 0 end
  return win, mine, foe, mf, ff, prize, goal
end

function RG.ArcadeStats()
  local a = store() or { coins = 0, cards = {} }
  local own, prints = 0, 0
  for _, c in ipairs(CARDS) do
    if bestFinish(a, c.id) then own = own + 1 end
    for k = 1, 4 do if ((a.cards[c.key or c.name] or {})[k] or 0) > 0 then prints = prints + 1 end end
  end
  return a, own, #CARDS, prints
end
-- the Master Set: every card (not counting Raiders), in any finish
function RG.ArcadeMaster()
  local a = store(); if not a then return 0, 0 end
  local have, total = 0, 0
  for _, c in ipairs(CARDS) do
    if c.kind ~= 4 and not c.dun then total = total + 1; if owned(a, c.id) > 0 then have = have + 1 end end   -- (dungeon cards have their own sets)
  end
  return have, total
end

-- showcase: up to nine favourites
function RG.ArcadePin(card)
  local a = store(); if not a then return end
  a.showcase = a.showcase or {}
  local key = card.key or card.name
  for i, k in ipairs(a.showcase) do if k == key then table.remove(a.showcase, i) return false end end
  if #a.showcase >= 9 then table.remove(a.showcase, 1) end
  table.insert(a.showcase, key)
  return true
end

-- ---------------------------------------------------------------------------
-- Trading with your party (one card for one card; any card you own except Raiders, your last copy included)
-- ---------------------------------------------------------------------------
local PREFIX = "WPCARD"
local trade = { out = nil, incoming = nil }
RG.ArcadeTrade = trade
local function countOf(a, c, f) local s = a.cards[c.key or c.name]; return s and (s[f] or 0) or 0 end
local function extraOf(a, c, f) return countOf(a, c, f) >= 2 end
local function ownsOf(a, c, f) return countOf(a, c, f) >= 1 end
local function tradable(c) return c and c.kind ~= 4 and c.tier ~= 7 and not c.field and not c.bound end   -- (Raiders, Mythics, Field Guide and holiday cards stay with whoever earned them)
local function sendAddon(msg, channel, target)
  if C_ChatInfo and C_ChatInfo.SendAddonMessage then pcall(C_ChatInfo.SendAddonMessage, PREFIX, msg, channel, target) end
end
function RG.ArcadeOffer(c, f)
  local a = store(); if not a or not c then return false, "Pick a card first." end
  if not tradable(c) then return false, "Raider cards can't be traded." end
  if not ownsOf(a, c, f) then return false, "You don't have that card in that print." end
  if not (IsInGroup and IsInGroup()) then return false, "Join a party to trade." end
  trade.out = { key = c.key or c.name, finish = f }
  sendAddon("O|" .. (c.key or c.name) .. "|" .. f, IsInRaid and IsInRaid() and "RAID" or "PARTY")
  return true, "Offered " .. c.name .. " (" .. FINISH[f][1] .. ") to your group. Waiting for someone to answer." .. (extraOf(a, c, f) and "" or "  (It's your only copy of that print: it leaves your collection if the trade goes through.)")
end
function RG.ArcadeAcceptOffer(c, f)
  local a = store(); local o = trade.incoming
  if not (a and o) then return false, "No offer to answer." end
  if not tradable(c) or not ownsOf(a, c, f) then return false, "Pick one of your cards to give back." end
  sendAddon("A|" .. o.key .. "|" .. o.finish .. "|" .. (c.key or c.name) .. "|" .. f, "WHISPER", o.from)
  trade.pending = { give = { key = c.key or c.name, finish = f }, get = { key = o.key, finish = o.finish }, from = o.from }
  trade.incoming = nil
  return true, "Answer sent. Waiting for " .. o.from .. " to confirm."
end
local function addCard(a, key, f, n)
  local c = byKey[key]; if not c then return end
  local slot = a.cards[key] or {}
  slot[f] = math.max(0, (slot[f] or 0) + n)
  a.cards[key] = slot
  -- a card traded away completely leaves the showcase too
  if n < 0 and (slot[1] or 0) + (slot[2] or 0) + (slot[3] or 0) + (slot[4] or 0) == 0 and a.showcase then
    for i = #a.showcase, 1, -1 do if a.showcase[i] == key then table.remove(a.showcase, i) end end
  end
end
-- a trade agreed with a friend (ArcadeSocial.lua): you give one card and get one, if you still have yours
function RG.ArcadeApplyTrade(giveKey, giveF, getKey, getF)
  local a = store(); if not a then return false end
  local gc, tc = byKey[giveKey], byKey[getKey]
  if not (gc and tc and tradable(gc) and tradable(tc) and FINISH[giveF] and FINISH[getF]) then return false end
  if not ownsOf(a, gc, giveF) then return false end
  addCard(a, giveKey, giveF, -1); addCard(a, getKey, getF, 1)
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
  return true
end
-- a card earned in the world (the Field Guide): one copy in that print
function RG.ArcadeGiveCard(key, f)
  local a = store(); local c = byKey[key]
  if not (a and c and FINISH[f]) then return false end
  addCard(a, key, f, 1)
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
  return true
end
-- a card given away (a holiday gift to a friend): one copy of that print, if you have it
function RG.ArcadeTakeCard(key, f)
  local a = store(); local c = byKey[key]
  if not (a and c and FINISH[f] and ownsOf(a, c, f)) then return false end
  addCard(a, key, f, -1)
  if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
  return true
end
function RG.ArcadeOwnsPrint(key, f) local a = store(); local c = byKey[key]; return (a and c and ownsOf(a, c, f)) and true or false end
function RG.ArcadeTradable(key) return tradable(byKey[key]) end
local function onAddon(prefix, text, channel, sender)
  if prefix ~= PREFIX or type(text) ~= "string" then return end
  local a = store(); if not a then return end
  local me = UnitName and UnitName("player")
  if sender and me and (sender == me or sender:match("^([^-]+)") == me) then return end
  local op, p1, p2, p3, p4 = strsplit("|", text)
  if op == "O" and byKey[p1] and FINISH[tonumber(p2) or 0] then
    trade.incoming = { key = p1, finish = tonumber(p2), from = sender }
    if RG.ArcadeRefresh then RG.ArcadeRefresh(); RG.ArcadeMsg((sender or "Someone") .. " offers " .. p1 .. " (" .. FINISH[tonumber(p2)][1] .. "). Open the Trade tab to answer.") end
  elseif op == "A" and trade.out and trade.out.key == p1 and trade.out.finish == tonumber(p2) and byKey[p3] and FINISH[tonumber(p4) or 0] then
    local c = byKey[p1]
    if ownsOf(a, c, tonumber(p2)) and tradable(byKey[p3]) then
      addCard(a, p1, tonumber(p2), -1); addCard(a, p3, tonumber(p4), 1)
      sendAddon("C|" .. p3 .. "|" .. p4 .. "|" .. p1 .. "|" .. p2, "WHISPER", sender)
      trade.out = nil
      if RG.ArcadeMsg then RG.ArcadeMsg("Traded " .. p1 .. " for " .. p3 .. ".") end
      if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
    end
  elseif op == "C" and trade.pending and trade.pending.give.key == p1 and trade.pending.get.key == p3 then
    addCard(a, p1, tonumber(p2), -1); addCard(a, p3, tonumber(p4), 1)
    trade.pending = nil
    if RG.ArcadeMsg then RG.ArcadeMsg("Traded " .. p1 .. " for " .. p3 .. ".") end
    if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
  end
end
do
  if C_ChatInfo and C_ChatInfo.RegisterAddonMessagePrefix then pcall(C_ChatInfo.RegisterAddonMessagePrefix, PREFIX) end
  local tf = CreateFrame("Frame")
  tf:RegisterEvent("CHAT_MSG_ADDON")
  tf:SetScript("OnEvent", function(_, _, ...) onAddon(...) end)
end

-- ---------------------------------------------------------------------------
-- Card widgets
-- ---------------------------------------------------------------------------
local function iconFor(c)
  if c.icon then return c.icon end
  if c.kind == 1 then
    -- (ArcadeArtFix.lua: an icon the game keeps on the item's appearance, or a like item's for one this client lacks)
    local fix = RG.ARCADE_ITEM_ICON and RG.ARCADE_ITEM_ICON[c.ref]
    if fix then return fix end
    local ic
    if C_Item and C_Item.GetItemIconByID then ic = C_Item.GetItemIconByID(c.ref) end
    if not ic and GetItemIcon then ic = GetItemIcon(c.ref) end
    return ic or "Interface\\Icons\\INV_Misc_QuestionMark"
  end
  -- NPCs and places: the game's own icon, picked from the name first (a troll gets a troll head, a spider a spider),
  -- then from the creature type
  local n = (c.name or ""):lower()
  for _, e in ipairs(NAME_ICON) do
    if (" " .. n):find(" " .. e[1], 1, true) then return "Interface\\Icons\\" .. e[2] end   -- (at the start of a word: "howler" is not an owl)
  end
  if c.kind == 2 then return "Interface\\Icons\\" .. (CREATURE_ICON[c.ref] or "INV_Misc_Head_Human_01") end
  return "Interface\\Icons\\" .. (c.text == "Zone" and "INV_Misc_Map_01" or "INV_Misc_Map02")
end


local MEDIA = "Interface\\AddOns\\Waypath\\Media\\Arcade\\"
-- ---------------------------------------------------------------------------
-- Scenery: every place and every NPC gets its own little landscape, worked out from its name, so no two
-- cards share a picture (sky colour, sun or moon, two ridge lines, a landmark).
-- ---------------------------------------------------------------------------
local function seedOf(str)
  local h = 7
  for i = 1, #str do h = (h * 31 + str:byte(i)) % 2147483647 end
  if h == 0 then h = 1 end
  return h
end
local function rngOf(seed)
  local x = seed
  return function() x = (x * 16807) % 2147483647; return x / 2147483647 end
end
local function hsv(h, s, v)
  h = (h % 1) * 6
  local i = math.floor(h); local f = h - i
  local p, q, t = v * (1 - s), v * (1 - s * f), v * (1 - s * (1 - f))
  i = i % 6
  if i == 0 then return v, t, p elseif i == 1 then return q, v, p elseif i == 2 then return p, v, t
  elseif i == 3 then return p, q, v elseif i == 4 then return t, p, v else return v, p, q end
end
-- the equipment slot of an item card picks its emblem on the 4x4 Slots sheet (0-based cell)
local SLOT_CELL = { INVTYPE_HEAD = 0, INVTYPE_SHOULDER = 1, INVTYPE_CHEST = 2, INVTYPE_ROBE = 2, INVTYPE_HAND = 3, INVTYPE_FEET = 4, INVTYPE_WAIST = 5,
  INVTYPE_LEGS = 6, INVTYPE_WRIST = 7, INVTYPE_FINGER = 8, INVTYPE_NECK = 9, INVTYPE_CLOAK = 10, INVTYPE_WEAPON = 11, INVTYPE_WEAPONMAINHAND = 11,
  INVTYPE_WEAPONOFFHAND = 11, INVTYPE_2HWEAPON = 12, INVTYPE_RANGED = 13, INVTYPE_RANGEDRIGHT = 13, INVTYPE_THROWN = 13, INVTYPE_SHIELD = 14,
  INVTYPE_HOLDABLE = 15, INVTYPE_TRINKET = 15 }
local SLOT_WORDS = { { "helm", 0 }, { "crown", 0 }, { "circlet", 0 }, { "mask", 0 }, { "coif", 0 }, { "pauldron", 1 }, { "spaulder", 1 }, { "shoulder", 1 },
  { "epaulet", 1 }, { "mantle", 1 }, { "breastplate", 2 }, { "chestguard", 2 }, { "robe", 2 }, { "hauberk", 2 }, { "tunic", 2 }, { "vest", 2 }, { "gauntlet", 3 },
  { "glove", 3 }, { "handguard", 3 }, { "fists", 3 }, { "boot", 4 }, { "greave", 4 }, { "treads", 4 }, { "sabaton", 4 }, { "footwraps", 4 }, { "belt", 5 },
  { "girdle", 5 }, { "waistband", 5 }, { "cord", 5 }, { "legguard", 6 }, { "leggings", 6 }, { "pants", 6 }, { "breeches", 6 }, { "legplates", 6 },
  { "bracer", 7 }, { "wristguard", 7 }, { "wristwrap", 7 }, { "ring", 8 }, { "band", 8 }, { "signet", 8 }, { "seal", 8 }, { "choker", 9 }, { "amulet", 9 },
  { "necklace", 9 }, { "pendant", 9 }, { "talisman", 9 }, { "cloak", 10 }, { "cape", 10 }, { "shroud", 10 }, { "staff", 12 }, { "greatstaff", 12 },
  { "bow", 13 }, { "gun", 13 }, { "crossbow", 13 }, { "wand", 13 }, { "shield", 14 }, { "bulwark", 14 }, { "aegis", 14 }, { "orb", 15 }, { "idol", 15 },
  { "trinket", 15 }, { "blade", 11 }, { "sword", 11 }, { "axe", 11 }, { "mace", 11 }, { "hammer", 11 }, { "dagger", 11 }, { "scythe", 12 } }
local function slotOf(card)
  local loc
  if GetItemInfoInstant and card.ref then
    local ok, _, _, _, el = pcall(GetItemInfoInstant, card.ref)
    if ok and type(el) == "string" then loc = el end
  end
  if loc and SLOT_CELL[loc] then return SLOT_CELL[loc] end
  local n = (card.name or ""):lower()
  for _, w in ipairs(SLOT_WORDS) do if n:find(w[1], 1, true) then return w[2] end end
  return 15
end
local function usesScene(card) return card and (card.kind == 2 or card.kind == 3) end

-- builds the textures once on an art holder frame (frame) of size aw x ah; returns the scene object
local function newScene(frame, aw, ah, anchor)
  anchor = anchor or frame
  local sc = { aw = aw, ah = ah }
  local function tex(sub, file) local t = frame:CreateTexture(nil, "ARTWORK", nil, sub); t:SetTexture(MEDIA .. file); t:Hide(); return t end
  sc.sky, sc.stars, sc.sun, sc.r1, sc.mist, sc.r2, sc.mo, sc.fore, sc.cr = tex(-6, "Sky"), tex(-5, "Stars"), tex(-4, "Glow"), tex(-3, "Ridge1"), tex(-2, "Mist"),
    tex(-1, "Ridge1"), tex(0, "Motifs"), tex(1, "Fore"), tex(2, "Creatures")
  sc.sun:SetBlendMode("ADD"); sc.stars:SetBlendMode("ADD")
  sc.stars:SetAllPoints(anchor); sc.mist:SetAllPoints(anchor)
  sc.sky:SetAllPoints(anchor)
  sc.frame = anchor
  return sc
end
local function hideScene(sc) if sc then sc.sky:Hide(); sc.stars:Hide(); sc.sun:Hide(); sc.r1:Hide(); sc.mist:Hide(); sc.r2:Hide(); sc.mo:Hide(); sc.fore:Hide(); sc.cr:Hide() end end
-- NPC silhouettes: creature type (1 beast, 2 dragonkin, 3 demon, 4 elemental, 5 giant, 6 undead, 7 humanoid, 9 mechanical,
-- 10 other) -> cells of the 4x4 Creatures sheet (0-based, row by row)
local CREATURE_CELLS = { [1] = { 0, 1 }, [2] = { 2, 3 }, [3] = { 4, 5 }, [4] = { 6, 7 }, [5] = { 8, 9 }, [6] = { 10, 11 }, [7] = { 12, 13 }, [8] = { 0, 1 }, [9] = { 14 }, [10] = { 15, 3 } }
local function setScene(sc, card, dim)
  local aw, ah = sc.aw, sc.ah
  local rnd = rngOf(seedOf((card.name or "?") .. "|" .. tostring(card.id or card.ref or 0)))
  for _ = 1, 3 do rnd() end
  local hue = rnd()
  local sat = 0.30 + rnd() * 0.40
  local val = 0.55 + rnd() * 0.40
  if card.hue then hue = card.hue end
  if card.val then val = card.val end
  local k = dim and 0.16 or 1
  local r, g, b = hsv(hue, sat, val)
  sc.sky:SetTexture(MEDIA .. "Sky"); sc.sky:SetVertexColor(r * k, g * k, b * k, 1); sc.sky:Show()
  -- stars show through darker skies
  sc.stars:SetTexture(MEDIA .. "Stars"); sc.stars:SetVertexColor(1, 1, 1, math.max(0, math.min(0.9, (0.8 - val) * 2.2)) * k); sc.stars:Show()
  -- sun or moon
  local sx, sy = 0.15 + rnd() * 0.7, 0.45 + rnd() * 0.4
  local sr, sg, sb = hsv(hue + 0.08 + rnd() * 0.1, 0.25 + rnd() * 0.4, 1)
  local ss = (0.28 + rnd() * 0.3) * ah
  sc.sun:ClearAllPoints(); sc.sun:SetPoint("CENTER", sc.frame, "BOTTOMLEFT", sx * aw, sy * ah); sc.sun:SetSize(ss, ss)
  sc.sun:SetVertexColor(sr * k, sg * k, sb * k, 0.95); sc.sun:Show()
  -- two ridge lines (far, near), each one of four shapes, scrolled and mirrored differently
  local function ridge(t, kind, hgt, shade, hueShift)
    t:SetTexture(MEDIA .. "Ridge" .. kind)
    local u0 = rnd() * 0.5
    if rnd() < 0.5 then t:SetTexCoord(u0 + 0.5, u0, 0, 1) else t:SetTexCoord(u0, u0 + 0.5, 0, 1) end
    t:ClearAllPoints(); t:SetPoint("BOTTOMLEFT", sc.frame, "BOTTOMLEFT", 0, 0); t:SetPoint("BOTTOMRIGHT", sc.frame, "BOTTOMRIGHT", 0, 0); t:SetHeight(hgt * ah)
    local rr, rg, rb = hsv(hue + hueShift, math.min(1, sat + 0.1), val * shade)
    t:SetVertexColor(rr * k, rg * k, rb * k, 1); t:Show()
  end
  local k1 = 1 + math.floor(rnd() * 4)
  local k2 = 1 + math.floor(rnd() * 4)
  if k2 == k1 then k2 = k1 % 4 + 1 end
  ridge(sc.r1, k1, 0.40 + rnd() * 0.15, 0.55, 0.04)
  -- haze between the two ridges gives the picture depth
  local mr2, mg2, mb2 = hsv(hue, 0.15, math.min(1, val + 0.2))
  sc.mist:SetTexture(MEDIA .. "Mist"); sc.mist:SetVertexColor(mr2 * k, mg2 * k, mb2 * k, 0.55); sc.mist:Show()
  ridge(sc.r2, k2, 0.22 + rnd() * 0.12, 0.28, -0.03)
  -- a landmark standing on the near ridge
  local m = math.floor(rnd() * 16)
  local mx = 0.18 + rnd() * 0.64
  local ms = (0.34 + rnd() * 0.16) * ah
  local flip = rnd() < 0.5
  local isNpc = card.kind == 2
  if isNpc then
    -- a creature of the NPC's own kind stands in front of the scenery, bigger for bosses
    local cells = CREATURE_CELLS[card.ref] or CREATURE_CELLS[10]
    m = cells[1 + math.floor(rnd() * #cells)]
    mx = 0.34 + rnd() * 0.32
    local txt = card.text or ""
    ms = ((txt:find("Boss") and 0.92) or (txt:find("elite") and 0.82) or 0.72) * ah
  end
  local col, row = m % 4, math.floor(m / 4)
  local mr, mg, mb = hsv(hue - 0.02, 0.35, 0.12 + rnd() * 0.1)
  local pic = isNpc and sc.cr or sc.mo
  if isNpc then sc.mo:Hide() else sc.cr:Hide() end
  if flip then pic:SetTexCoord((col + 1) * 0.25, col * 0.25, row * 0.25, row * 0.25 + 0.25)
  else pic:SetTexCoord(col * 0.25, (col + 1) * 0.25, row * 0.25, row * 0.25 + 0.25) end
  pic:ClearAllPoints(); pic:SetPoint("BOTTOM", sc.frame, "BOTTOMLEFT", mx * aw, (isNpc and 0.02 or 0.07) * ah); pic:SetSize(ms, ms)
  pic:SetVertexColor(mr * k, mg * k, mb * k, 1); pic:Show()
  -- a dark grassy foreground
  local fr, fg, fb = hsv(hue, 0.3, 0.06)
  sc.fore:SetTexture(MEDIA .. "Fore"); sc.fore:ClearAllPoints(); sc.fore:SetPoint("BOTTOMLEFT", sc.frame, "BOTTOMLEFT", 0, 0); sc.fore:SetPoint("BOTTOMRIGHT", sc.frame, "BOTTOMRIGHT", 0, 0)
  sc.fore:SetHeight(0.2 * ah); sc.fore:SetVertexColor(fr * k, fg * k, fb * k, 1); sc.fore:Show()
end

local function ensureModel(w)
  local have = rawget(w, "model")
  if have ~= nil then return have end
  local ok, m = pcall(CreateFrame, "DressUpModel", nil, w)
  if not ok or not m then w.model = false return false end
  w.model = m
  m:SetScript("OnModelLoaded", function(self)
    pcall(function()
      if self.creature then
        if self.SetPortraitZoom and self.zoom then self:SetPortraitZoom(self.zoom) end
        if RG.ArcadeApplyCam then RG.ArcadeApplyCam(self) end
        if self.SetFacing then self:SetFacing(self.face or 0.5) end
        return
      end
      if self.Undress then self:Undress() end
      for _, id in ipairs((RG.ARCADE_GEAR or {})[self.cls or ""] or {}) do if self.TryOn then self:TryOn("item:" .. id) end end
      if self.SetFacing then self:SetFacing(0.4) end
    end)
  end)
  return m
end
