}
for i = 1, 4 do FX[i].finish = i end
FX[5] = { aura = 0.85, foil = 0.85, rune = 0, sparks = true, prism = true, finish = 4 }   -- a Mythic

local function makeCard(parent, w)
  local h = math.floor(w * 358 / 256 + 0.5)
  local u = w / 256
  local f = CreateFrame("Frame", nil, parent)
  f:SetSize(w, h); f:EnableMouse(true)
  f.cw, f.ch, f.u, f.phase = w, h, u, math.random()
  local base = lv(f)
  local function box(fr, b, into)
    fr:SetPoint("TOPLEFT", into or f, "TOPLEFT", b[1] * u, -b[2] * u); fr:SetPoint("BOTTOMRIGHT", into or f, "TOPLEFT", b[3] * u, -b[4] * u)
  end
  -- under everything: the aura, the card body, the empty slot
  f.aura = f:CreateTexture(nil, "BACKGROUND", nil, -8); f.aura:SetTexture(MEDIA .. "Glow"); f.aura:SetBlendMode("ADD")
  f.aura:SetPoint("TOPLEFT", f, "TOPLEFT", -0.24 * w, 0.17 * h); f.aura:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", 0.24 * w, -0.17 * h); f.aura:Hide()
  f.body = f:CreateTexture(nil, "BACKGROUND", nil, 0); f.body:SetTexture(MEDIA .. "Body"); f.body:SetTexCoord(0, 1, 0, CARD_V); f.body:SetAllPoints(f)
  f.slot = f:CreateTexture(nil, "BACKGROUND", nil, 1); f.slot:SetTexture(MEDIA .. "Slot"); f.slot:SetTexCoord(0, 1, 0, CARD_V); f.slot:SetAllPoints(f); f.slot:Hide()
  -- the art window
  f.artClip = CreateFrame("Frame", nil, f); box(f.artClip, U.art); f.artClip:SetFrameLevel(base + 1)
  if f.artClip.SetClipsChildren then f.artClip:SetClipsChildren(true) end
  local aw, ah = (U.art[3] - U.art[1]) * u, (U.art[4] - U.art[2]) * u
  f.aw, f.ah = aw, ah
  f.glow = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 1); f.glow:SetTexture(MEDIA .. "Glow"); f.glow:SetBlendMode("ADD"); f.glow:SetAllPoints(f.artClip)
  -- items: a spotlight in the rarity's colour behind the icon, so the picture is not a small icon on a dark window
  f.spot = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 2); f.spot:SetTexture(MEDIA .. "Glow"); f.spot:SetBlendMode("ADD"); f.spot:Hide()
  f.emb = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 3); f.emb:SetTexture(MEDIA .. "Slots"); f.emb:SetBlendMode("ADD"); f.emb:Hide()
  f.rays = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 2); f.rays:SetTexture(MEDIA .. "Rays"); f.rays:SetBlendMode("ADD")
  f.rays:SetSize(aw * 1.5, aw * 1.5); f.rays:SetPoint("CENTER", f.artClip, "CENTER", 0, 0); f.rays:Hide()
  f.rune = f.artClip:CreateTexture(nil, "BACKGROUND", nil, 3); f.rune:SetTexture(MEDIA .. "Rune"); f.rune:SetBlendMode("ADD")
  f.rune:SetSize(ah * 1.08, ah * 1.08); f.rune:SetPoint("CENTER", f.artClip, "CENTER", 0, 0)
  f.iconBack = f.artClip:CreateTexture(nil, "ARTWORK", nil, 0); f.iconBack:SetColorTexture(0.08, 0.06, 0.1, 0.9)
  f.iconEdge = f.artClip:CreateTexture(nil, "ARTWORK", nil, 1); f.iconEdge:SetColorTexture(GOLDC[1], GOLDC[2], GOLDC[3], 0.95)
  f.art = f.artClip:CreateTexture(nil, "ARTWORK", nil, 2); f.art:SetTexCoord(0.07, 0.93, 0.07, 0.93)
  -- foil sweeps across the whole card, above the model
  f.fx = CreateFrame("Frame", nil, f); f.fx:SetAllPoints(f); f.fx:SetFrameLevel(base + 3)
  if f.fx.SetClipsChildren then f.fx:SetClipsChildren(true) end
  f.foil = f.fx:CreateTexture(nil, "OVERLAY"); f.foil:SetTexture(MEDIA .. "Foil"); f.foil:SetBlendMode("ADD"); f.foil:SetSize(w * 2.2, h * 1.02); f.foil:Hide()
  f.foil:SetPoint("LEFT", f.fx, "LEFT", -w, 0)
  -- frame, text, gem
  f.top = CreateFrame("Frame", nil, f); f.top:SetAllPoints(f); f.top:SetFrameLevel(base + 4)
  -- every card shares one frame: the art window's border, the outer edge (its look is the print's finish), the engraved
  -- name plate (tinted by the card's own rarity), then the type line, the rules and the card's number
  f.frameTex = f.top:CreateTexture(nil, "ARTWORK", nil, 0); f.frameTex:SetTexture(MEDIA .. "Frame"); f.frameTex:SetTexCoord(0, 1, 0, CARD_V); f.frameTex:SetAllPoints(f)
  f.edge = f.top:CreateTexture(nil, "ARTWORK", nil, 1); f.edge:SetTexture(MEDIA .. "Edge1"); f.edge:SetTexCoord(0, 1, 0, CARD_V); f.edge:SetAllPoints(f)
  f.plate = f.top:CreateTexture(nil, "ARTWORK", nil, 2); f.plate:SetTexture(MEDIA .. "NamePlate")
  f.pill = f.top:CreateTexture(nil, "ARTWORK", nil, 2); f.pill:SetTexture(MEDIA .. "Pill"); box(f.pill, { 184, 6, 246, 22 }); f.pill:Hide()
  -- Full art prints: the picture runs to the card's edge and fades into the card under the name plate
  f.fade = f.fx:CreateTexture(nil, "ARTWORK"); f.fade:SetTexture(MEDIA .. "Fade"); box(f.fade, { 4, 146, 252, 214 }); f.fade:Hide()
  f.name = fs(f.top, "title", 16 * u); f.name:SetShadowColor(0, 0, 0, 0); box(f.name, { 20, 209, 236, 237 })
  f.name:SetJustifyH("CENTER"); f.name:SetJustifyV("MIDDLE"); f.name:SetWordWrap(false); f.name:SetTextColor(0.07, 0.06, 0.1)
  f.type = fs(f.top, "head", 9 * u); box(f.type, { 14, 242, 242, 257 })
  f.type:SetJustifyH("CENTER"); f.type:SetJustifyV("MIDDLE"); f.type:SetWordWrap(false); f.type:SetTextColor(0.85, 0.8, 0.7)
  f.text = fs(f.top, "body", 12 * u)
  f.text:SetPoint("TOPLEFT", f, "TOPLEFT", 24 * u, -260 * u); f.text:SetPoint("BOTTOMRIGHT", f, "TOPLEFT", 232 * u, -322 * u)
  f.text:SetJustifyH("CENTER"); f.text:SetJustifyV("TOP"); f.text:SetTextColor(0.96, 0.94, 0.89)
  f.nameB = fs(f.top, "head", 10.5); f.nameB:SetShadowColor(0, 0, 0, 0); f.nameB:SetTextColor(0.07, 0.06, 0.1)
  f.nameB:SetJustifyH("CENTER"); f.nameB:SetJustifyV("MIDDLE"); f.nameB:Hide()
  -- (the quick-duel power is in the tooltip now: the card shows what it costs and its attack and health, as in the Arena)
  f.pow = fs(f.top, "title", 17 * u); f.pow:SetPoint("CENTER", f, "TOPLEFT", 128 * u, -327 * u); f.pow:Hide()
  f.powLabel = fs(f.top, "head", 6.5 * u); f.powLabel:SetPoint("CENTER", f, "TOPLEFT", 128 * u, -314 * u); f.powLabel:Hide()
  f.num = fs(f.top, "head", 8 * u); f.num:SetPoint("CENTER", f, "TOPLEFT", 128 * u, -343 * u); f.num:SetTextColor(0.66, 0.68, 0.74)
  f.fin = fs(f.top, "title", 7 * u); f.fin:SetPoint("CENTER", f.pill, "CENTER", 0, 0); f.fin:SetTextColor(0.9, 0.93, 0.97)
  f.count = fs(f.top, "title", 13 * u, "OVERLAY", "OUTLINE"); f.count:SetPoint("TOPRIGHT", f, "TOPLEFT", 238 * u, -28 * u); f.count:SetTextColor(1, 0.95, 0.7)
  f.pin = f.top:CreateTexture(nil, "OVERLAY"); f.pin:SetTexture("Interface\\Cooldown\\star4"); f.pin:SetBlendMode("ADD"); f.pin:SetSize(20 * u, 20 * u)
  f.pin:SetPoint("TOPLEFT", f, "TOPLEFT", 20 * u, -48 * u); f.pin:SetVertexColor(1, 0.85, 0.3); f.pin:Hide()
  f.sparks = {}
  local pos = { { 62, 80 }, { 196, 110 }, { 120, 60 } }
  for i, p in ipairs(pos) do
    local sp = f.top:CreateTexture(nil, "OVERLAY", nil, 3); sp:SetTexture("Interface\\Cooldown\\star4"); sp:SetBlendMode("ADD")
    sp:SetSize((14 + i * 3) * u, (14 + i * 3) * u); sp:SetPoint("CENTER", f, "TOPLEFT", p[1] * u, -p[2] * u); sp:Hide(); f.sparks[i] = sp
  end
  f.hl = f.top:CreateTexture(nil, "OVERLAY", nil, 5); f.hl:SetColorTexture(1, 1, 1, 0); f.hl:SetBlendMode("ADD"); f.hl:SetPoint("TOPLEFT", f, "TOPLEFT", 4 * u, -4 * u); f.hl:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -4 * u, 4 * u)
  f:SetScript("OnMouseUp", function(self, btn) if self.onCard and self.card then self.onCard(self, btn) end end)
  f:SetScript("OnEnter", function(self)
    if self.hover ~= false then self.hl:SetAlpha(0.09) end
    local c = self.card
    if not c or self.noTip then return end
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    if not self.known then GameTooltip:AddLine("Not found yet", 0.6, 0.6, 0.6)
    else
      local t = TIER[c.tier][3]
      GameTooltip:AddLine(c.name, t[1], t[2], t[3])
      GameTooltip:AddLine(KIND[c.kind] .. "  ·  " .. TIER[c.tier][1] .. "  ·  " .. FINISH[self.finish][1], 1, 1, 1)
      GameTooltip:AddLine(c.text, 0.75, 0.75, 0.75, true)
      if c.mythic and RG.Battle and RG.Battle.MYTHIC and RG.Battle.MYTHIC[c.name] then GameTooltip:AddLine(RG.Battle.MYTHIC[c.name][2], 1, 0.91, 0.66, true) end
      if c.mythic then GameTooltip:AddLine(c.mythic.one and "The rarest card: about 1 pack in 5,000, one per account. It can't be crafted, traded or sold." or "A Mythic: about 1 pack in " .. math.floor(1 / TIER[7].rate + 0.5) .. ". It can't be crafted or traded.", 0.8, 0.8, 0.8, true) end
      GameTooltip:AddLine("Duel power " .. power(c, self.finish) .. "  (quick card duels; the Arena uses the card's own mana, attack and health)", 0.7, 0.9, 0.7, true)
      if self.copies and self.copies > 1 then GameTooltip:AddLine("You own " .. self.copies, 0.7, 0.7, 0.7) end
    end
    GameTooltip:Show()
  end)
  f:SetScript("OnLeave", function(self) self.hl:SetAlpha(0); GameTooltip:Hide() end)
  return f
end

-- an NPC card shows that creature's own model; a place card a piece of its zone's own world map
local function hasArt(c)
  if c.kind == 2 then
    if RG.ARCADE_NPC and RG.ARCADE_NPC[c.name] then return true end
    local cid = RG.ARCADE_DUNGEON_CREATURE and RG.ARCADE_DUNGEON_CREATURE[c.name]
    local nd = WaypathDB and WaypathDB.arcade and WaypathDB.arcade.npcDisp
    return (cid and nd and nd[cid] == -1) and true or false
  end
  if c.kind == 3 then return ((RG.ARCADE_PLACE and RG.ARCADE_PLACE[c.name]) or (RG.ARCADE_PLACE_FILE and RG.ARCADE_PLACE_FILE[c.name])) and true or false end
  return false
end
-- how close the camera sits: upright creatures are framed head and chest, long low ones whole, so each is centred
local ZOOM = { [7] = 0.6, [1] = 0.05, [2] = 0.1, [3] = 0.4, [4] = 0.3, [5] = 0.3, [6] = 0.5, [8] = 0.0, [9] = 0.25 }
function RG.ArcadeModelZoom(c) return ZOOM[c and c.ref or 7] or 0.4 end
-- how far the camera sits back (1 = the game's own framing): dragons, giants and bosses are far bigger than the frame
local CAM = { [1] = 1.3, [2] = 2.0, [3] = 1.4, [4] = 1.4, [5] = 1.8, [6] = 1.1, [7] = 1.0, [8] = 1.0, [9] = 1.3 }
function RG.ArcadeCamScale(c)
  local k = CAM[c and c.ref or 7] or 1
  if c and (c.tier or 0) >= 4 then k = k * 1.3 end     -- Legendary NPCs are the raid bosses
  return k * ((RG.db and tonumber(RG.db.cardCam)) or 1)
end
function RG.ArcadeApplyCam(m, c)
  if not m then return end
  if c then m.cam = RG.ArcadeCamScale(c) end
  if not m.cam then return end
  if m.SetCamDistanceScale then pcall(m.SetCamDistanceScale, m, m.cam)
  elseif m.SetModelScale then pcall(m.SetModelScale, m, 1 / m.cam) end   -- no camera control on this client: shrink the creature instead
end
-- two cards can share one creature model (Firemaw and Flamegor, a boss and its spirit): those stand on scenery of their own
-- and face the other way, so no two cards look the same
local sharedCount
local function sharedModel(c)
  if not sharedCount then
    sharedCount = {}
    for _, id in pairs(RG.ARCADE_NPC or {}) do sharedCount[id] = (sharedCount[id] or 0) + 1 end
  end
  local id = c and RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
  return id and (sharedCount[id] or 0) > 1 or false
end
RG.ArcadeSharedModel = sharedModel
local function dressCreature(w, c)
  local id = RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
  -- (a creature the game draws by its id but won't give a display id for: RG.ArcadeResolveCreatures)
  local cid = not id and RG.ARCADE_DUNGEON_CREATURE and RG.ARCADE_DUNGEON_CREATURE[c.name]
  local npcDisp = WaypathDB and WaypathDB.arcade and WaypathDB.arcade.npcDisp
  if cid and not (npcDisp and npcDisp[cid] == -1) then cid = nil end
  if not id and not cid then return false end
  local mem = WaypathDB and WaypathDB.arcade and WaypathDB.arcade.badModel
  if mem and mem[id] then return false end     -- the art check found that this client cannot draw it: scenery instead
  local m = ensureModel(w)
  if not m then return false end
  m.creature = true
  m:ClearAllPoints(); m:SetPoint("TOPLEFT", w.artClip, "TOPLEFT", 2, -2); m:SetPoint("BOTTOMRIGHT", w.artClip, "BOTTOMRIGHT", -2, 2)
  m:SetFrameLevel(lv(w) + 2)
  local ok
  if id then ok = m.SetDisplayInfo and pcall(m.SetDisplayInfo, m, id)
  else ok = m.SetCreature and pcall(m.SetCreature, m, cid) end
  if not ok then m:Hide() return false end
  m.zoom = RG.ArcadeModelZoom(c)
  if m.SetPortraitZoom then pcall(m.SetPortraitZoom, m, m.zoom) end
  RG.ArcadeApplyCam(m, c)
  if m.SetPosition then pcall(m.SetPosition, m, 0, 0, 0) end
  m.face = (sharedModel(c) and seedOf(c.name) % 2 == 1) and -0.5 or 0.5
  if m.SetFacing then pcall(m.SetFacing, m, m.face) end
  m:Show()
  return true
end
-- a place card shows its own painting (Media/Arcade/PlacesN.tga, drawn by tools/arcade/art_places.py) in a gold frame
local function placeArt(w, c, full)
  local e = RG.ARCADE_PLACE and RG.ARCADE_PLACE[c.name]
  local scr = not e and RG.ARCADE_PLACE_FILE and RG.ARCADE_PLACE_FILE[c.name]
  if not e and not scr then return false end
  local u = w.u
  if e then
    local col, row = e[2] % 8, math.floor(e[2] / 8)
    w.art:SetTexture(MEDIA .. "Places" .. e[1])
    w.art:SetTexCoord(col * 120 / 1024, (col + 1) * 120 / 1024, row * 84 / 1024, (row + 1) * 84 / 1024)
  else
    -- a dungeon or raid: its own loading screen from the game's files, cut to the painting's shape
    w.art:SetTexture(scr[1])
    if scr[2] == 1 then w.art:SetTexCoord(0.125, 0.875, 0, 1) else w.art:SetTexCoord(0, 1, 0.035, 0.965) end
  end
  local pw = (full and 248 or 186) * u; local ph = pw * 84 / 120   -- (Full art: the painting runs to the card's edge)
  w.art:ClearAllPoints(); w.art:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.art:SetSize(pw, ph)
  w.iconBack:ClearAllPoints(); w.iconBack:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconBack:SetSize(pw + 7 * u, ph + 7 * u)
  w.iconEdge:ClearAllPoints(); w.iconEdge:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconEdge:SetSize(pw + 3 * u, ph + 3 * u)
  return true
end

-- A Raider is shown as one of the game's own textured people of their class (a Scarlet judge, a dwarven pyromancer, a
-- dragonmaw battlemaster...), picked from the name so the same Raider always gets the same one. (A bare player-race
-- model has no skin when it is not a unit, so it came out all white.)
local RAIDER_FACE = {
  WARRIOR = { 4912, 10344, 4937, 10346, 10431 }, PALADIN = { 10355, 10342, 10431, 5072, 16154 },
  PRIEST = { 12169, 10342, 5072, 10482, 10920 }, MAGE = { 2240, 8762, 16024, 10432, 9472 },
  WARLOCK = { 10432, 6669, 11578, 9472, 10343 }, ROGUE = { 10343, 10875, 4003, 10344, 10346 },
  HUNTER = { 10375, 4731, 10875, 4033, 10346 }, DRUID = { 2168, 1542, 12169, 15421, 10375 },
  SHAMAN = { 6102, 10911, 10443, 10357, 4527 },
}
local RAIDER_ANY = { 10344, 10355, 10343, 2240, 8762, 10375, 4912, 12169 }
local function dressModel(w, c, finish)
  local m = ensureModel(w)
  if not m or not m.SetDisplayInfo then return false end
  local list = RAIDER_FACE[(c.class or ""):upper()] or RAIDER_ANY
  local id = list[seedOf(c.name or "?") % #list + 1]
  m.cls = c.class; m.creature = true
  m:ClearAllPoints(); m:SetPoint("TOPLEFT", w.artClip, "TOPLEFT", 2, -2); m:SetPoint("BOTTOMRIGHT", w.artClip, "BOTTOMRIGHT", -2, 2)
  m:SetFrameLevel(lv(w) + 2)
  if not pcall(m.SetDisplayInfo, m, id) then m:Hide() return false end
  m.zoom = 0.3   -- (the whole figure, head included)
  if m.SetPortraitZoom then pcall(m.SetPortraitZoom, m, m.zoom) end
  if m.SetPosition then pcall(m.SetPosition, m, 0, 0, 0) end
  if m.SetFacing then pcall(m.SetFacing, m, 0.5) end
  m:Show()
  return true
end

-- small cards: the name goes on the parchment in a size you can read (two lines if it needs them),
-- with the effect or tier line beneath it. The tiny name plate on top stays empty.
local FINCOL = { { 0.836, 0.747, 0.567 }, { 0.5, 0.74, 1 }, { 0.86, 0.62, 1 }, { 1, 0.86, 0.42 } }   -- header label colour by finish
local function layoutText(w, big, name, text)
  local u = w.u
  local pb = big and U.plate or U.plateS
  w.plate:ClearAllPoints()
  w.plate:SetPoint("TOPLEFT", w, "TOPLEFT", pb[1] * u, -pb[2] * u); w.plate:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", pb[3] * u, -(pb[4] + 3) * u)   -- (+3: the plate's shadow)
  w.text:ClearAllPoints(); w.text:SetJustifyH("CENTER"); w.text:SetJustifyV("TOP")
  if big then
    w.nameB:Hide(); w.type:Show()
    w.type:ClearAllPoints(); w.type:SetPoint("TOPLEFT", w, "TOPLEFT", 14 * u, -242 * u); w.type:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 242 * u, -257 * u)
    w.text:SetPoint("TOPLEFT", w, "TOPLEFT", 24 * u, -260 * u); w.text:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 232 * u, -322 * u)
    if w.text.SetMaxLines then w.text:SetMaxLines(0) end
    return
  end
  -- small cards: the name fills the plate in a size you can read (two lines if it needs them)
  w.name:SetText("")
  local bw = (pb[3] - pb[1] - 10) * u
  local sz = w.cw >= 110 and 10 or 9
  w.nameB:ClearAllPoints()
  w.nameB:SetPoint("TOPLEFT", w, "TOPLEFT", (pb[1] + 5) * u, -(pb[2] + 1) * u); w.nameB:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", (pb[3] - 5) * u, -(pb[4] - 1) * u)
  w.nameB:SetWordWrap(false); setfont(w.nameB, "head", sz); w.nameB:SetText(name or "")
  local wd = w.nameB.GetUnboundedStringWidth and w.nameB:GetUnboundedStringWidth() or w.nameB:GetStringWidth()
  if type(wd) == "number" and wd > bw then
    -- first a little smaller on one line, then two lines
    while sz > 8 and wd > bw do sz = sz - 0.5; setfont(w.nameB, "head", sz); w.nameB:SetText(name or ""); wd = w.nameB.GetUnboundedStringWidth and w.nameB:GetUnboundedStringWidth() or w.nameB:GetStringWidth() end
    if type(wd) == "number" and wd > bw then
      sz = math.min(sz, math.max(7, ((pb[4] - pb[2] - 4) * u) / 2 - 1))
      setfont(w.nameB, "head", sz); w.nameB:SetText(name or "")
      w.nameB:SetWordWrap(true)
      if w.nameB.SetMaxLines then w.nameB:SetMaxLines(2) end
    end
  elseif w.nameB.SetMaxLines then w.nameB:SetMaxLines(1) end
  w.nameB:Show()
  local showType = w.cw >= 120
  w.type:SetShown(showType)
  if showType then
    w.type:ClearAllPoints(); w.type:SetPoint("TOPLEFT", w, "TOPLEFT", 14 * u, -252 * u); w.type:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 242 * u, -264 * u)
  end
  local top = showType and 266 or 254
  local tsz = 9
  local tl = math.floor(((314 - top) * u) / (tsz + 2))
  setfont(w.text, "body", tsz)
  if text and text ~= "" and tl >= 1 then
    -- the rules sit between the name plate and the attack and health gems
    w.text:SetPoint("TOPLEFT", w, "TOPLEFT", 14 * u, -top * u); w.text:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 242 * u, -316 * u)
    if w.text.SetMaxLines then w.text:SetMaxLines(tl) end
    w.text:SetText(text)
  else w.text:SetText("") end
end

-- A Mythic: its own painted card (name plate, type line and badge are part of the picture) inside a slowly turning
-- prismatic edge, with the rules text on top. The 1 Ring shows the item's own icon and who opened it.
function RG.ArcadePaintMythic(w, card, copies, a)
  local u, my = w.u, card.mythic
  if not rawget(w, "mart") then
    local base = lv(w)
    w.pclip = CreateFrame("Frame", nil, w); w.pclip:SetAllPoints(w); w.pclip:SetFrameLevel(base + 1)
    if w.pclip.SetClipsChildren then w.pclip:SetClipsChildren(true) end
    w.prism = w.pclip:CreateTexture(nil, "BACKGROUND"); w.prism:SetPoint("CENTER", w, "CENTER", 0, 0); w.prism:SetSize(w.ch * 1.3, w.ch * 1.3)
    -- the card's rounded shape (where the client has masks; otherwise the edge has square corners)
    if w.pclip.CreateMaskTexture then
      pcall(function()
        local mk = w.pclip:CreateMaskTexture()
        mk:SetPoint("TOPLEFT", w, "TOPLEFT", 0, 0); mk:SetSize(w.cw, w.ch / CARD_V)
        mk:SetTexture(MEDIA .. "CardMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
        w.prism:AddMaskTexture(mk)
      end)
    end
    w.mframe = CreateFrame("Frame", nil, w); w.mframe:SetAllPoints(w); w.mframe:SetFrameLevel(base + 2)
    w.mart = w.mframe:CreateTexture(nil, "BACKGROUND"); w.mart:SetTexCoord(0, 1, 0, CARD_V)
    w.mart:SetPoint("TOPLEFT", w, "TOPLEFT", 3 * u, -3 * u); w.mart:SetPoint("BOTTOMRIGHT", w, "BOTTOMRIGHT", -3 * u, 3 * u)
    w.micon = w.mframe:CreateTexture(nil, "ARTWORK"); w.micon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
    w.micon:SetPoint("CENTER", w, "TOPLEFT", 128 * u, -118 * u); w.micon:SetSize(66 * u, 66 * u); w.micon:Hide()
    w.mtext = fs(w.top, "body", 10.5 * u); w.mtext:SetJustifyH("CENTER"); w.mtext:SetJustifyV("MIDDLE"); w.mtext:SetTextColor(0.96, 0.94, 0.89)
    w.engr = fs(w.top, "head", 7 * u); w.engr:SetJustifyH("CENTER"); w.engr:SetTextColor(1, 0.91, 0.66)
    w.engr:SetPoint("TOPLEFT", w, "TOPLEFT", 16 * u, -335 * u); w.engr:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 240 * u, -350 * u)
  end
  w.body:Hide(); w.frameTex:Hide(); w.slot:Hide(); w.glow:Hide(); w.rune:Hide(); w.iconBack:Hide(); w.iconEdge:Hide()
  w.art:Hide(); w.spot:Hide(); w.emb:Hide(); w.rays:Hide(); w.nameB:Hide(); w.text:Hide()
  w.edge:Hide(); w.plate:Hide(); w.pill:Hide(); w.fade:Hide()
  if rawget(w, "scn") then hideScene(w.scn) end
  w.name:SetText(""); w.type:SetText(""); w.num:SetText(""); w.fin:SetText("")
  w.pclip:Show(); w.mframe:Show()
  w.prism:SetTexture(MEDIA .. (my.one and "PrismRing" or "Prism")); w.prism:Show()
  w.mart:SetTexture(MEDIA .. my.art); w.mart:Show()
  if my.itemIcon then w.micon:SetTexture(iconFor(card)); w.micon:Show() else w.micon:Hide() end
  -- the rules (what it does in the Arena); too small to read on the little grid cards
  local rules = RG.Battle and RG.Battle.MYTHIC and RG.Battle.MYTHIC[card.name] and RG.Battle.MYTHIC[card.name][2] or ""
  local engraved = my.one and a and a.ring and ("Opened by " .. tostring(a.ring.by) .. "  ·  " .. tostring(a.ring.date)) or nil
  if w.cw >= 120 then
    setfont(w.mtext, "body", math.max(8, 10.5 * u))
    w.mtext:ClearAllPoints()
    w.mtext:SetPoint("TOPLEFT", w, "TOPLEFT", 20 * u, -281 * u); w.mtext:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", 236 * u, -(my.one and 333 or 335) * u)
    w.mtext:SetText(rules); w.mtext:Show()
    setfont(w.engr, "head", math.max(6, 7 * u))
    w.engr:SetText(engraved or ""); w.engr:SetShown(engraved ~= nil)
  else w.mtext:Hide(); w.engr:Hide() end
  -- glow, light sweep, sparkles, the turning edge
  local fx = FX[5]
  w.fxset = fx
  tintTex(w.aura, my.glow or { 1, 0.9, 0.6 }, 1); w.aura:Show(); w.aura:SetAlpha(fx.aura)
  w.foil:Show()
  for _, sp in ipairs(w.sparks) do sp:Show(); tintTex(sp, { 1, 1, 1 }, 0.9) end
  setfont(w.count, "title", math.max(9, 13 * u), "OUTLINE")
  w.count:SetText(copies and copies > 1 and ("x" .. copies) or "")
  if a and a.showcase then for _, k in ipairs(a.showcase) do if k == (card.key or card.name) then w.pin:Show() end end end
  anim[w] = cardAnim
end

-- card: the card; finish: 1-4 or nil (nothing owned); copies: how many you own
local function paint(w, card, finish, copies)
  w.card, w.known, w.finish, w.copies = card, finish ~= nil, finish or 1, copies
  anim[w] = nil
  for _, fn in ipairs(RG.ArcadeCardHooks or {}) do pcall(fn, w, nil) end
  local mdl = rawget(w, "model"); if mdl then mdl:Hide() end
  w.pin:Hide(); w.foil:Hide(); w.aura:Hide(); w.rays:Hide()
  for _, sp in ipairs(w.sparks) do sp:Hide() end
  -- (a widget that showed a Mythic before goes back to the ordinary pieces)
  if rawget(w, "mart") then w.pclip:Hide(); w.mframe:Hide(); w.mtext:Hide(); w.engr:Hide(); w.text:Show() end
  -- the art window: a Full art print's picture runs to the card's edge
  local full = finish == 4 and card and not card.mythic
  do
    local ab, cu = full and U.full or U.art, w.u
    w.artClip:ClearAllPoints()
    w.artClip:SetPoint("TOPLEFT", w, "TOPLEFT", ab[1] * cu, -ab[2] * cu); w.artClip:SetPoint("BOTTOMRIGHT", w, "TOPLEFT", ab[3] * cu, -ab[4] * cu)
    w.aw, w.ah = (ab[3] - ab[1]) * cu, (ab[4] - ab[2]) * cu
    if rawget(w, "scn") then w.scn.aw, w.scn.ah = w.aw, w.ah end
    w.fade:SetShown(full and true or false)
  end
  -- what the card costs and its attack and health in the Arena (the gems are ArcadeBattle.lua's)
  local def = card and (card.def or (RG.Battle and RG.Battle.defs and RG.Battle.defs[card.key or card.name]))
  if card and not def and finish and RG.Battle and RG.Battle.derive and card.kind ~= 4 then
    local ok, d = pcall(RG.Battle.derive, card); def = ok and d or nil
  end
  if RG.ArcadeCardStats then RG.ArcadeCardStats(w, finish and def or nil) end
  if not card then w:Hide() return end
  w:Show()
  local u = w.u
  local a = WaypathDB and WaypathDB.arcade
  local t = TIER[card.tier][3]
  w.num:SetText(string.format("#%04d", card.id or 0))
  w.art:ClearAllPoints(); w.iconBack:ClearAllPoints(); w.iconEdge:ClearAllPoints()
  local function placeIcon(sz)
    w.art:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.art:SetSize(sz * u, sz * u)
    w.iconBack:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconBack:SetSize((sz + 7) * u, (sz + 7) * u)
    w.iconEdge:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.iconEdge:SetSize((sz + 3) * u, (sz + 3) * u)
  end
  w.art:SetTexture(iconFor(card)); w.art:SetTexCoord(0.07, 0.93, 0.07, 0.93)
  local scene = usesScene(card) and not hasArt(card)   -- drawn scenery only where the game has no art for the card
  if scene then
    if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
    setScene(w.scn, card, not finish)
  elseif rawget(w, "scn") then hideScene(w.scn) end
  if not finish then
    -- an empty slot in the binder: a silhouette and the collector number
    w.body:Hide(); w.frameTex:Hide(); w.edge:Hide(); w.plate:Hide(); w.pill:Hide(); w.slot:Show(); w.glow:Hide(); w.rune:Hide(); w.iconBack:Hide(); w.iconEdge:Hide(); w.spot:Hide(); w.emb:Hide()
    w.art:Show(); w.art:SetDesaturated(true); w.art:SetVertexColor(0, 0, 0, 0.6); placeIcon(74)
    if scene then w.art:Hide() end
    w.nameB:Hide(); w.name:SetText(""); w.type:SetText(""); w.text:SetText(""); w.count:SetText(""); w.fin:SetText("")
    w.num:SetTextColor(0.5, 0.5, 0.56)
    return
  end
  if card.mythic then RG.ArcadePaintMythic(w, card, copies, a); return end
  w.body:Show(); w.frameTex:SetShown(not full); w.slot:Hide(); w.glow:Show()
  w.edge:SetTexture(MEDIA .. "Edge" .. finish); w.edge:Show(); w.plate:Show(); w.rune:Show(); w.iconBack:Show(); w.iconEdge:Show(); w.art:Show()
  w.num:SetTextColor(0.66, 0.68, 0.74)
  local fx = FX[finish]
  w.fxset = fx
  local kc = KINDCOL[card.kind] or KINDCOL[1]
  w.glow:SetVertexColor(kc[1], kc[2], kc[3], 0.55)
  if card.kind ~= 4 and not scene then
    w.spot:ClearAllPoints(); w.spot:SetPoint("CENTER", w.artClip, "CENTER", 0, 3 * u); w.spot:SetSize(w.ah * 1.7, w.ah * 1.7)
    w.spot:SetVertexColor(t[1], t[2], t[3], 0.55 + 0.08 * (card.tier or 1)); w.spot:Show()
  end
  if card.kind == 1 then
    local sl = slotOf(card); local c0, r0 = sl % 4, math.floor(sl / 4)
    w.emb:SetTexCoord(c0 * 0.25, (c0 + 1) * 0.25, r0 * 0.25, r0 * 0.25 + 0.25)
    w.emb:ClearAllPoints(); w.emb:SetPoint("CENTER", w.artClip, "CENTER", 0, 2 * u); w.emb:SetSize(w.ah * 0.98, w.ah * 0.98)
    w.emb:SetVertexColor(t[1], t[2], t[3], 0.34); w.emb:Show()
  else w.emb:Hide(); if card.kind == 4 or scene then w.spot:Hide() end end
  tintTex(w.frameTex, U.mix(t, 0.55), 1)
  tintTex(w.plate, U.mix(t, 0.4), 1)
  tintTex(w.rune, t, fx.rune)
  tintTex(w.aura, t, 1)
  w.art:SetDesaturated(false); w.art:SetVertexColor(1, 1, 1, 1)
  -- no two cards share a picture: when the game cannot give a model (or a painting), the card gets its own drawn scenery
  local function ownScene()
    if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
    setScene(w.scn, card, false)
    w.iconBack:Hide(); w.iconEdge:Hide(); w.art:Hide(); w.spot:Hide()
  end
  if card.kind == 4 and dressModel(w, card, finish) then w.art:Hide(); w.iconBack:Hide(); w.iconEdge:Hide()
  elseif card.kind == 4 then ownScene()
  elseif card.kind == 2 and dressCreature(w, card) then
    w.art:Hide(); w.iconBack:Hide(); w.iconEdge:Hide()
    if sharedModel(card) then
      if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
      setScene(w.scn, card, false); w.spot:Hide()
    else
      -- every creature stands on a sky and ridge of its own (no silhouette: the model is the creature), so the models
      -- from the game's files and the drawn cards share one look
      if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
      setScene(w.scn, card, false); w.scn.mo:Hide(); w.scn.cr:Hide(); w.spot:Hide()
    end
    -- some creatures have no model this client can draw (the card would show an empty glow): once the game has had a
    -- moment to load it, a model that still reports no file gets the card's own drawn scenery behind it
    if C_Timer and C_Timer.After then
      local m = rawget(w, "model")
      C_Timer.After(1.2, function()
        if w.card ~= card or not m or not m:IsShown() then return end
        local fid = m.GetModelFileID and m:GetModelFileID()
        if fid and fid ~= 0 then return end
        if not rawget(w, "scn") then w.scn = newScene(w.artClip, w.aw, w.ah) end
        setScene(w.scn, card, false); w.spot:Hide(); w.iconBack:Hide(); w.iconEdge:Hide(); w.art:Hide()
      end)
    end
  elseif card.kind == 2 then ownScene()
  elseif card.kind == 3 and placeArt(w, card, full) then -- painting in its gold frame
  elseif card.kind == 3 and not scene then ownScene()
  elseif scene then
    w.iconBack:Hide(); w.iconEdge:Hide()
    w.art:Hide()
  else placeIcon(full and 120 or 94) end
  if fx.rays then tintTex(w.rays, { 1, 0.86, 0.5 }, fx.rays); w.rays:Show() end
  if fx.foil > 0 then w.foil:Show() end
  if fx.aura > 0 then w.aura:Show(); w.aura:SetAlpha(fx.aura) end
  if fx.sparks then for _, sp in ipairs(w.sparks) do sp:Show(); tintTex(sp, { 1, 0.95, 0.8 }, 0.8) end end
  -- text: the name on the plate, the type line in the rarity's colour, what the card does in the Arena, then its story
  local big = w.cw >= 190
  local tc = U.mix(t, 0.55)
  setfont(w.type, "head", math.max(7.5, 9 * u)); w.type:SetTextColor(tc[1], tc[2], tc[3])
  w.type:SetText(KIND[card.kind] .. "  ·  " .. TIER[card.tier][1])
  setfont(w.count, "title", math.max(9, 13 * u), "OUTLINE")
  setfont(w.num, "head", math.max(6.5, 8 * u))
  local hl = RG.ArcadeHilite
  local rules = def and def.text or ""
  if hl and rules ~= "" then rules = hl(rules) end
  local story = card.def and card.lore or (not card.def and card.text) or ""
  w.text:SetShown(true)
  if big then
    layoutText(w, true)
    fitText(w.name, card.name, 212 * u, 16 * u, 8.5, "title")
    setfont(w.text, "body", 11.5 * u)
    w.text:SetText(rules .. (rules ~= "" and story ~= "" and "\n" or "") .. (story ~= "" and ("|cff9a9fad" .. story .. "|r") or ""))
  else
    local short = rules:gsub("%s+", " ")
    layoutText(w, false, card.name, w.cw < 120 and "" or short)   -- (the grid shows the name and the numbers; the rest is on the inspect card)
  end
  -- how the print was made: on the label in the corner (the edge says it too)
  local label = w.cw >= 150
  w.pill:SetShown(label)
  setfont(w.fin, "title", math.max(6, 7 * u))
  w.fin:SetText(label and FINISH[finish][1]:upper() or "")
  w.num:SetShown(w.cw >= 100)
  w.count:SetText(copies and copies > 1 and ("x" .. copies) or "")
  if a and a.showcase then for _, k in ipairs(a.showcase) do if k == (card.key or card.name) then w.pin:Show() end end end
  if fx.foil > 0 or fx.aura > 0 or fx.spin then anim[w] = cardAnim end
  for _, fn in ipairs(RG.ArcadeCardHooks or {}) do pcall(fn, w, card, finish) end   -- (Field Guide stamps, raid frames)
end

-- ---------------------------------------------------------------------------
-- Window
-- ---------------------------------------------------------------------------
local frame, cells, reveal, detail
local COLS, ROWS, CELLW = 6, 3, 104
local GRIDX, GRIDY = 118, 150
local WINW, WINH = 790, 730
local view = { kind = 0, show = 1, sort = 1, page = 1, search = "", mode = "cards", set = nil, showcase = false }
local SHOWS = { "All", "Owned", "Missing", "Extras" }
local SORTS = { "Owned", "Collection", "Rarity", "Name", "Power" }
local FNAME = { "Common", "Rare", "Holo", "Full art" }

local function isPinned(a, c)
  for _, k in ipairs(a.showcase or {}) do if k == (c.key or c.name) then return true end end
  return false
end
local function hasExtra(a, c) local s = a.cards[c.key or c.name]; if not s then return false end; for f = 1, 4 do if (s[f] or 0) >= 2 then return true end end return false end

local function collectionList(a)
  local list, q = {}, (view.search or ""):lower()
  for _, c in ipairs(CARDS) do
    local n = owned(a, c.id)
    local ok = view.kind == 0 or c.kind == view.kind
    if ok and view.show == 2 and n == 0 then ok = false end
    if ok and view.show == 3 and n > 0 then ok = false end
    if ok and view.show == 4 and not hasExtra(a, c) then ok = false end
    if ok and q ~= "" and not (c.name:lower():find(q, 1, true) or (c.text or ""):lower():find(q, 1, true)) then ok = false end
    if ok and view.set and setOf(c) ~= view.set then ok = false end
    if ok and view.showcase and not isPinned(a, c) then ok = false end
    if ok then list[#list + 1] = c end
  end
  if view.sort == 1 then
    local have = {}
    for _, c in ipairs(list) do have[c] = owned(a, c.id) > 0 end
    table.sort(list, function(x, y) if have[x] ~= have[y] then return have[x] end return (x.id or 0) < (y.id or 0) end)
  elseif view.sort == 3 then table.sort(list, function(x, y) if x.tier ~= y.tier then return x.tier > y.tier end return x.name < y.name end)
  elseif view.sort == 4 then table.sort(list, function(x, y) return x.name < y.name end)
  elseif view.sort == 5 then table.sort(list, function(x, y) return power(x, bestFinish(a, x.id) or 1) > power(y, bestFinish(a, y.id) or 1) end) end
  return list
end

local function kit(...)   -- the first SOUNDKIT id this client has
  if not SOUNDKIT then return nil end
  for i = 1, select("#", ...) do local k = select(i, ...); if SOUNDKIT[k] then return SOUNDKIT[k] end end
end
-- our own sound effects (Media/Sounds, synthesised by tools/arcade/sounds.py); the Arena's Sound button silences them too
local SND = "Interface\\AddOns\\Waypath\\Media\\Sounds\\"
local function playFx(name)
  local a = store()
  if a and a.mute then return true end   -- muted counts as handled
  if not PlaySoundFile then return false end
  local ok, willPlay = pcall(PlaySoundFile, SND .. name .. ".ogg", "SFX")
  return ok and willPlay ~= false
end
RG.ArcadeFx = playFx
-- role: "flip" (a card turns), "hover" (a rare card is nearby), "crack" (the seal tears), "pick" (a chip of the seal), "best" (personal best), "deal", "reward", "toast"
local function playSound(finish, tier, role)
  local fx
  if role == "hover" or role == "pick" or role == "best" or role == "deal" or role == "reward" or role == "toast" then fx = role
  elseif role == "crack" then fx = "crack"
  elseif tier >= 6 then fx = "flip_legend"
  elseif finish and finish >= 4 then fx = "flip_full"
  elseif finish == 3 then fx = "flip_holo"
  elseif finish == 2 then fx = "flip_rare"
  else fx = "flip_common" end
  if playFx(fx) then return end
  if not (PlaySound and SOUNDKIT) then return end
  local id
  if role == "hover" then id = kit("IG_MAINMENU_OPTION_CHECKBOX_ON", "IG_CHARACTER_INFO_TAB")
  elseif role == "pick" then id = kit("IG_CHARACTER_INFO_TAB", "IG_MAINMENU_OPTION_CHECKBOX_ON")
  elseif role == "crack" then id = kit("IG_MAINMENU_OPEN", "IG_BACKPACK_OPEN", "IG_QUEST_LIST_OPEN")
  elseif role == "best" or role == "reward" or role == "toast" then id = kit("UI_LEGENDARY_LOOT_TOAST", "LEVEL_UP", "UI_EPICLOOT_TOAST")
  elseif tier >= 6 then id = kit("UI_LEGENDARY_LOOT_TOAST", "LEVEL_UP")
  elseif finish and finish >= 4 then id = kit("UI_EPICLOOT_TOAST", "UI_LEGENDARY_LOOT_TOAST", "IG_QUEST_LIST_COMPLETE")
  elseif finish == 3 then id = kit("UI_EPICLOOT_TOAST", "IG_QUEST_LIST_COMPLETE")
  elseif finish == 2 then id = kit("IG_QUEST_LIST_OPEN", "IG_ABILITY_PAGE_TURN")
  elseif role == "deal" then id = nil
  else id = kit("IG_ABILITY_PAGE_TURN", "IG_BACKPACK_OPEN") end
  if id then pcall(PlaySound, id) end
end

-- a dark panel with gold trim, used by the pop-ups
local function darkPanel(f, w, h)
  f:SetSize(w, h)
  f:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 2 })
  -- Fireside: a carved wooden frame, brass trim, a dark walnut inlay
  f:SetBackdropColor(0.165, 0.094, 0.043, 0.99); f:SetBackdropBorderColor(0.65, 0.48, 0.23, 1)
  local inlay = f:CreateTexture(nil, "BACKGROUND", nil, 0); inlay:SetColorTexture(0.29, 0.18, 0.086, 1); inlay:SetPoint("TOPLEFT", 8, -8); inlay:SetPoint("BOTTOMRIGHT", -8, 8)
  local night = f:CreateTexture(nil, "BACKGROUND", nil, 1); night:SetColorTexture(0.11, 0.07, 0.035, 1); night:SetPoint("TOPLEFT", 11, -11); night:SetPoint("BOTTOMRIGHT", -11, 11)
  local corners = {}
  for i = 1, 4 do
    local c = f:CreateTexture(nil, "OVERLAY"); c:SetTexture(MEDIA .. "Corner"); c:SetSize(46, 46)
    local right, bottom = (i == 2 or i == 4), (i == 3 or i == 4)
    c:SetPoint((bottom and "BOTTOM" or "TOP") .. (right and "RIGHT" or "LEFT"), right and -3 or 3, bottom and 3 or -3)
    c:SetTexCoord(right and 1 or 0, right and 0 or 1, bottom and 1 or 0, bottom and 0 or 1)
    corners[i] = c
  end
  return night
end

-- a face-down card: click it and the back turns over
local function makeCover(card)
  local c = CreateFrame("Button", nil, card)
  c:SetPoint("CENTER"); c:SetSize(card.cw, card.ch); c:SetFrameLevel(lv(card) + 10)
  c.cw, c.ch, c.phase = card.cw, card.ch, math.random()
  c.glow = c:CreateTexture(nil, "BACKGROUND", nil, -8); c.glow:SetTexture(MEDIA .. "Glow"); c.glow:SetBlendMode("ADD")
  c.glow:SetPoint("TOPLEFT", c, "TOPLEFT", -0.3 * card.cw, 0.22 * card.ch); c.glow:SetPoint("BOTTOMRIGHT", c, "BOTTOMRIGHT", 0.3 * card.cw, -0.22 * card.ch); c.glow:Hide()
  c.tex = c:CreateTexture(nil, "ARTWORK"); c.tex:SetTexture(MEDIA .. "Back"); c.tex:SetTexCoord(0, 1, 0, CARD_V); c.tex:SetAllPoints(c)
  c.shine = c:CreateTexture(nil, "OVERLAY"); c.shine:SetColorTexture(1, 1, 1, 1); c.shine:SetBlendMode("ADD"); c.shine:SetAlpha(0); c.shine:SetPoint("TOPLEFT", 3, -3); c.shine:SetPoint("BOTTOMRIGHT", -3, 3)
  -- hold the mouse on a card to peel its bottom edge up: you see the bottom of the card and a bar in its print's colour
  c.fold = c:CreateTexture(nil, "OVERLAY"); c.fold:SetColorTexture(0, 0, 0, 0.5); c.fold:SetPoint("BOTTOMLEFT", c, "BOTTOMLEFT", 0, 0); c.fold:SetPoint("BOTTOMRIGHT", c, "BOTTOMRIGHT", 0, 0); c.fold:SetHeight(7); c.fold:Hide()
  c.peek = c:CreateTexture(nil, "OVERLAY", nil, 2); c.peek:SetColorTexture(1, 1, 1, 1); c.peek:SetSize(46, 5); c.peek:SetPoint("BOTTOM", c, "BOTTOM", 0, 1); c.peek:Hide()
  c.rare, c.cued, c.peel, c.lift, c.holding = false, false, 0, 0, false
  local function layout(self)
    local ch = card.ch
    local h = ch * (1 - 0.24 * self.peel)
    self:SetHeight(h)
    self:ClearAllPoints(); self:SetPoint("CENTER", 0, (ch - h) / 2 + self.lift)
    self.tex:SetTexCoord(0, 1, 0, CARD_V * (1 - 0.24 * self.peel))
    if self.peel > 0.05 then self.fold:Show() else self.fold:Hide() end
    if self.peel > 0.5 then self.peek:Show() else self.peek:Hide() end
  end
  c.layout = layout
  local function peelTick(self, dt)
    if self.flipping == true then return end
    self.peel = math.min(1, self.peel + dt * 3.5)
    layout(self)
  end
  local function drop(self)
    self.holding, self.peel = false, 0
    if self.flipping ~= true then self:SetScript("OnUpdate", nil); layout(self) end
  end
  c:SetScript("OnEnter", function(self)
    self.shine:SetAlpha(self.rare and 0.18 or 0.1)
    if self.flipping == true then return end
    self.lift = 5; layout(self)
    if self.rare and not self.cued then self.cued = true; playSound(nil, nil, "hover") end   -- a card worth the wait is under your mouse
  end)
  c:SetScript("OnLeave", function(self)
    self.shine:SetAlpha(0); self.lift = 0
    drop(self)
    if self.flipping ~= true then layout(self) end
  end)
  c:SetScript("OnMouseDown", function(self)
    if self.flipping == true then return end
    local col = self.peekCol or { 0.691, 0.617, 0.469 }
    self.peek:SetColorTexture(col[1], col[2], col[3], 1)
    self.holding = true; self:SetScript("OnUpdate", peelTick)
  end)
  c:SetScript("OnMouseUp", function(self) drop(self) end)
  card.cover = c
  return c
end
local function coverAnim(c, t)
  -- the glow says how good the card inside is, by the better of its rarity and its print: blue (Renowned or a Rare
  -- print), purple (Epic or Holo), gold (Legendary or Full art), red for a Raider, every colour for a Mythic
  local pc = c.glowCol or c.peekCol or { 1, 1, 1 }
  if c.prismatic then
    local r, g, b = hsv((t * 0.35 + c.phase) % 1, 0.55, 1)
    c.glow:SetVertexColor(r, g, b, 0.75 + 0.2 * math.sin(t * 4))
    return
  end
  local k = 0.5 + 0.5 * math.sin(t * (c.rare and 3 or 2) + c.phase * 5)
  c.glow:SetVertexColor(pc[1], pc[2], pc[3], (c.rare and 0.45 or 0.28) + (c.rare and 0.3 or 0.15) * k)
end

local function oddsText(g)
  if not g.odds then return "" end
  return "   ·   about 1 in " .. groupDigits(g.odds) .. " cards"
end
-- the plaque under the pack: up to four labelled rows
local function setPlaque(rows)
  local pq = reveal.plaque
  local n = math.min(4, #rows)
  for i = 1, 4 do
    local r, row = pq.rows[i], rows[i]
    r.lab:SetShown(row and true or false); r.val:SetShown(row and true or false); r.line:SetShown(row and i > 1 and true or false)
    if row then r.lab:SetText(string.upper(row[1])); r.val:SetText(row[2]) end
  end
  pq:SetHeight(n * 24 + 10)
  pq:SetShown(n > 0)
end
local function summarize()
  local best, bi
  for i, g in ipairs(reveal.got) do
    local sc = g.finish * 10 + g.card.tier
    if not best or sc > best then best, bi = sc, i end
  end
  local g = reveal.got[bi]
  local meta = reveal.meta or {}
  local rows = {}
  if meta.many then
    local m = meta.many
    rows[#rows + 1] = { "Best pull", GOLDHEX .. g.card.name .. "|r  (" .. FNAME[g.finish] .. ")" .. oddsText(g) }
    rows[#rows + 1] = { m.count .. " packs", m.total .. " cards   ·   " .. m.new .. " new" .. (m.newPrint > 0 and (", " .. m.newPrint .. " new prints") or "") .. "   ·   duplicates worth " .. m.value .. " coins" }
  else
    local new, extra, worth = 0, 0, 0
    for _, x in ipairs(reveal.got) do
      if x.new then new = new + 1 else extra = extra + 1; worth = worth + (x.value or 0) end
    end
    rows[#rows + 1] = { "Best pull", GOLDHEX .. g.card.name .. "|r  (" .. FNAME[g.finish] .. ")" .. oddsText(g) }
    rows[#rows + 1] = { "This pack", new .. " new" .. (extra > 0 and ("   ·   " .. extra .. " already owned, worth " .. worth .. " coins") or "") }
  end
  if meta.sets then
    local bits = {}
    for i = 1, math.min(1, #meta.sets) do
      local x = meta.sets[i]
      bits[#bits + 1] = x.name .. " " .. x.have .. "/" .. x.total .. (x.gained > 0 and (" |cff7be08a(+" .. x.gained .. ")|r") or "")
    end
    reveal.setBits = bits
  else reveal.setBits = nil end
  local extra = {}
  if meta.daily and meta.streak then extra[#extra + 1] = "Pack streak: day " .. meta.streak .. (meta.streak % 7 == 0 and "  (reward pack earned)" or "") end
  if reveal.notes and #reveal.notes > 0 then extra[#extra + 1] = "|cff7be08a" .. table.concat(reveal.notes, "   ·   ") .. "|r" end
  -- one short third line for everything else (set progress, streak, bonuses), so the screen stays calm
  local more = {}
  for _, b in ipairs(reveal.setBits or {}) do more[#more + 1] = b end
  for _, b in ipairs(extra) do more[#more + 1] = b end
  if #more > 0 then rows[#rows + 1] = { "Progress", table.concat(more, "   ·   ") } end
  do   -- packs still waiting to be opened
    local a, left = store(), {}
    if a then
      for _, kk in ipairs(PACK_ORDER) do
        local n = tokenCount(a, kk)
        if n > 0 then left[#left + 1] = n .. " " .. PACKS[kk].name:lower() .. (n > 1 and "s" or "") end
      end
    end
    if #left > 0 and #rows < 4 then rows[#rows + 1] = { "Still to open", table.concat(left, "   ·   ") } end
  end
  setPlaque(rows)
end

local function burstAt(card, strength)
  reveal.burst:ClearAllPoints(); reveal.burst:SetPoint("CENTER", card, "CENTER", 0, 0)
  local sc0 = card.GetScale and card:GetScale(); if type(sc0) ~= "number" then sc0 = 1 end
  local s = card.cw * sc0 * (2.6 + strength * 0.5)
  reveal.burst:SetSize(s, s)
  local t = card.fxset and TIER[card.card.tier][3] or { 1, 0.85, 0.5 }
  tintTex(reveal.burst, { math.min(1, t[1] + 0.3), math.min(1, t[2] + 0.3), math.min(1, t[3] + 0.3) }, 1)
  reveal.burstLeft, reveal.burstMax = 1.1 + 0.3 * strength, 1.1 + 0.3 * strength
  reveal.burstSpin = 0
  reveal.burst:Show()
end

local function badgeFor(g)
  if g.new then return GOLDHEX .. "NEW|r" end
  if g.newPrint then local t = TIER[g.card.tier][3]; return string.format("|cff%02x%02x%02x", math.floor(t[1] * 255 + 0.5), math.floor(t[2] * 255 + 0.5), math.floor(t[3] * 255 + 0.5)) .. "NEW PRINT|r" end
  return "|cff9a96b0You have " .. (g.copies or 2) .. " · " .. (g.value or 0) .. "c|r"
end
local function flip(i)
  local card = reveal.cards[i]
  local c = card.cover
  if not c or c.flipping == true or not c:IsShown() or reveal.phase then return end
  c.flipping = true; anim[c] = nil
  c.peel, c.lift, c.holding = 0, 0, false
  c.fold:Hide(); c.peek:Hide(); c:SetHeight(card.ch); c.tex:SetTexCoord(0, 1, 0, CARD_V)
  c:ClearAllPoints(); c:SetPoint("CENTER", 0, 0)
  local g0 = reveal.got[i]
  local weight = g0.card.tier >= 6 and 3 or (g0.finish >= 3 and 2 or (g0.finish == 2 and 1 or 0))
  local span = weight >= 2 and 0.6 or (weight == 1 and 0.34 or 0.22)   -- the better the card, the longer the wait
  local t = 0
  c:SetScript("OnUpdate", function(self, dt)
    t = t + dt
    local k = 1 - t / span
    if k > 0.02 then
      self:SetWidth(math.max(1, card.cw * k))
      if weight >= 2 then self:ClearAllPoints(); self:SetPoint("CENTER", math.sin(t * 60) * 2.5 * (1 - k), 0) end   -- it trembles
    else
      self:SetScript("OnUpdate", nil); self:Hide(); self.flipping = false
      local g = reveal.got[i]
      reveal.flipped = reveal.flipped + 1
      card.new:SetText(badgeFor(g))
      -- a plain duplicate steps back, so the new and the notable cards are what you see
      if not g.new and not g.newPrint and g.finish < 3 and g.card.tier < 5 and #reveal.got > 5 then card:SetAlpha(0.6) else card:SetAlpha(1) end
      local big = weight
      playSound(g.finish, g.card.tier)
      if big > 0 then burstAt(card, big) end
      if big >= 2 then reveal.shakeT, reveal.shakeK = 0.35, big end
      if g.record then reveal.record = true; reveal.title:SetText("Your rarest pull yet!"); playSound(nil, nil, "best") end
      if g.card.tier == 7 then RG.ArcadeMythicMoment(g) end
      for _, fn in ipairs(RG.ArcadeRevealHooks or {}) do pcall(fn, card, g, reveal) end   -- (a raid boss roars)
      if reveal.flipped >= #reveal.got then
        reveal.all:Hide(); reveal.ok:SetText("Done")
        if not reveal.record then reveal.title:SetText("Pack opened") end
        reveal.share:Show(); summarize()
        if reveal.meta and reveal.meta.stagesWon and RG.ArcadeStageCelebrate then RG.ArcadeStageCelebrate(reveal.meta.stagesWon) end
      end
    end
  end)
end

local function afford(kind)
  local a = store()
  if not a then return false end
  kind = kind or "normal"
  if tokenCount(a, kind) > 0 then return true end
  return (a.coins or 0) >= packPrice(kind)
end

local RW, RCARD, RGAP = 790, 136, 10
local PKW, PKH = 160, 320   -- the booster pack on screen (its art is 256x512)
local RH = 730   -- the pack screen covers the whole collection window
-- the pack screen sits exactly over the collection window (or the middle of the screen if that is closed)
local function revealPoint(r, dx, dy)
  r:ClearAllPoints()
  if frame and frame.IsShown and frame:IsShown() then r:SetPoint("CENTER", frame, "CENTER", dx or 0, dy or 0)
  else r:SetPoint("CENTER", UIParent, "CENTER", dx or 0, dy or 0) end
end
-- where the cards go: one row for a pack, two rows of four for a jumbo, two rows of six (a little smaller) for a super jumbo
local function dealPositions(i, n)
  n = n or PACK_SIZE
  local per, sc, gap = n, 1, 10
  if n > 8 then per, sc, gap = 6, 0.86, 8 elseif n > 5 then per = 4 end
  local cw = RCARD * sc
  local chh = cw * 358 / 256
  local rows = math.ceil(n / per)
  local rowGap = 18
  local top = 335 - (rows * chh + (rows - 1) * rowGap) / 2
  local row, col = math.floor((i - 1) / per), (i - 1) % per
  local inRow = math.min(per, n - row * per)
  local rowW = inRow * cw + (inRow - 1) * gap
  -- one row of cards sits in a shallow arc, like a hand of cards (the ends a little lower)
  local arc = rows == 1 and 5 * (col - (inRow - 1) / 2) ^ 2 or 0
  return (RW - rowW) / 2 + col * (cw + gap), -(top + row * (chh + rowGap) + arc), sc, cw
end
local function placeCard(c, x, y, sc)
  c:SetScale(sc); c:ClearAllPoints(); c:SetPoint("TOPLEFT", reveal, "TOPLEFT", x / sc, y / sc)
end

local function startDeal()
  reveal.phase = "deal"; reveal.dealT = 0
  reveal.sealFade = 0.55; reveal.sealGlow:Hide()
  reveal.plaque:SetShown(false)
  if rawget(reveal, "setNextUp") then reveal.setNextUp(false) end
  reveal.title:SetText("Turn each card")
  local n = #(reveal.got or {})
  for i = 1, n do local x, y, sc = dealPositions(i, n); placeCard(reveal.cards[i], x, y, sc); reveal.cards[i]:Show(); reveal.cards[i]:SetAlpha(0) end
  setPlaque({ { "Tip", "A glowing back hides a better card   ·   hold a card to peek at its print, let go to turn it" } })
  reveal.spot:ClearAllPoints(); reveal.spot:SetPoint("CENTER", reveal, "CENTER", 0, 30); reveal.spot:SetSize(760, n > 5 and 520 or 380)
  playSound(nil, nil, "deal")
end

local function cursorXY()
  if not GetCursorPosition then return 0, 0 end
  local x, y = GetCursorPosition()
  local sc = UIParent and UIParent.GetEffectiveScale and UIParent:GetEffectiveScale() or 1
  if type(x) ~= "number" or type(y) ~= "number" or type(sc) ~= "number" or sc == 0 then return 0, 0 end
  return x / sc, y / sc
end
-- the seal gives way: shards fly, the table jolts, the cards are dealt
local function tearOpen()
  if reveal.phase ~= "seal" then return end
  playSound(nil, nil, "crack"); if playFx then playFx("tear") end
  local c = reveal.sealCol or { 1, 0.8, 0.5 }
  for _, sh in ipairs(reveal.shards) do
    local ang = math.random() * 6.283
    local sp = 140 + math.random() * 260
    sh.x, sh.y, sh.vx, sh.vy = (math.random() - 0.5) * 50, -10 + (math.random() - 0.5) * 50, math.cos(ang) * sp, math.sin(ang) * sp + 120
    sh.tex:SetColorTexture(math.min(1, c[1] + math.random() * 0.3), math.min(1, c[2] + math.random() * 0.3), math.min(1, c[3] + math.random() * 0.3), 1)
    sh.tex:SetSize(5 + math.random() * 8, 5 + math.random() * 8); sh.tex:SetAlpha(1); sh.tex:Show()
  end
  reveal.shardT = 0.8
  reveal.shakeT, reveal.shakeK = 0.3, 1.5
  reveal.holding, reveal.tear, reveal.picks = false, 0, 0
  startDeal()
end

-- which of our own pictures goes on a set's seal: sheet, cell (0-15, row by row)
local NPC_CELL = { beast = 1, dragonkin = 2, demon = 3, elemental = 4, giant = 5, undead = 6, humanoid = 7, mechanical = 9, creature = 10 }
local function strHash(str)
  local h = 0
  for i = 1, #str do h = (h * 31 + str:byte(i)) % 100003 end
  return h
end
local function emblemFor(setName)
  setName = setName or ""
  local zone = setName:match("^Places in (.+)$")
  if zone then return "Motifs", strHash(zone) % 16 end
  if setName == "All zones" then return "Motifs", 9 end
  local ty = setName:match("^(%a+) bosses$") or setName:match("^(%a+) rares$")
  if ty then
    local cells = CREATURE_CELLS[NPC_CELL[ty:lower()] or 10] or CREATURE_CELLS[10]
    return "Creatures", cells[1 + strHash(setName) % #cells]
  end
  if setName == "Other NPCs" then return "Creatures", 12 end
  if setName == "Legendary items" then return "Slots", 11 end
  local ilvl = setName:match("item level (%d+)")
  if ilvl then return "Slots", (math.floor(tonumber(ilvl) / 10) + 3) % 16 end
  return "Motifs", 5
end
RG.ArcadeEmblem = emblemFor

-- a card a friend showed off (sent through ArcadeDuel's add-on channel)
local toast
-- (made on its first use, or when Edit Mode / /wp move shows where it will appear)
function RG.ArcadeToastFrame()
  if toast then return toast end
  toast = CreateFrame("Button", "WaypathArcadeToast", UIParent, "BackdropTemplate")
  toast:SetFrameStrata("DIALOG"); toast:SetPoint("TOP", UIParent, "TOP", 0, -170)
  darkPanel(toast, 340, 200)
  toast.card = makeCard(toast, 112); toast.card:SetPoint("LEFT", 22, 0); toast.card.noTip = true
  toast.head = fs(toast, "head", 12); toast.head:SetPoint("TOPLEFT", toast.card, "TOPRIGHT", 14, -2); toast.head:SetWidth(170); toast.head:SetJustifyH("LEFT"); toast.head:SetTextColor(0.911, 0.813, 0.618)
  toast.name = fs(toast, "title", 14); toast.name:SetPoint("TOPLEFT", toast.head, "BOTTOMLEFT", 0, -8); toast.name:SetWidth(170); toast.name:SetJustifyH("LEFT")
  toast.kind = fs(toast, "body", 12); toast.kind:SetPoint("TOPLEFT", toast.name, "BOTTOMLEFT", 0, -8); toast.kind:SetWidth(170); toast.kind:SetJustifyH("LEFT"); toast.kind:SetTextColor(0.9, 0.86, 0.74)
  toast.hint = fs(toast, "body", 11); toast.hint:SetPoint("BOTTOMRIGHT", -14, 10); toast.hint:SetTextColor(0.709, 0.633, 0.481); toast.hint:SetText("click to close")
  toast.age = 0
  toast:SetScript("OnClick", function(self) self:Hide() end)
  toast:SetScript("OnUpdate", function(self, dt)
    self.age = self.age + dt
    if self.age > 9 then self:Hide() elseif self.age > 8 then self:SetAlpha(math.max(0, 9 - self.age)) end
  end)
  toast:Hide()
  if RG.RegisterMover then
    RG.RegisterMover(toast, "arcadeToast", "Friend's card pull", { "TOP", "TOP", 0, -170 }, function(f, was)
      if was then return end
      local c = CARDS[1]
      if c then paint(f.card, c, 1, 1); f.name:SetText(c.name) end
      f.head:SetText("A friend pulled"); f.kind:SetText("Where friends' best pulls show"); f.age = -1e9
    end)
  end
  return toast
end
if RG.RegisterMoverMaker then RG.RegisterMoverMaker(function() RG.ArcadeToastFrame() end) end
function RG.ArcadeShowPull(sender, card, finish)
  if not (card and finish and FNAME[finish]) then return end
  if InCombatLockdown and InCombatLockdown() then return end
  if RG.db and RG.db.arcadeToasts == false then return end
  local now = GetTime and GetTime() or 0
  RG.__pullAt = RG.__pullAt or {}
  if RG.__pullAt[sender or "?"] and now - RG.__pullAt[sender or "?"] < 20 then return end   -- one card per friend every 20 seconds
  RG.__pullAt[sender or "?"] = now
  RG.ArcadeToastFrame()
  paint(toast.card, card, finish, 1)
  local t = TIER[card.tier][3]
  toast.head:SetText((sender or "Someone") .. " pulled")
  toast.name:SetText(card.name); toast.name:SetTextColor(t[1], t[2], t[3])
  toast.kind:SetText(KIND[card.kind] .. "  ·  " .. FNAME[finish] .. "\n" .. TIER[card.tier][1] .. (cardOdds(card, finish) and ("\nabout 1 in " .. groupDigits(cardOdds(card, finish)) .. " cards") or ""))
  toast.age = 0; toast:SetAlpha(1); toast:Show()
  playSound(nil, nil, "toast")
end

-- the tear-off strip and its gold trim move together
local function stripSet(r, sc, dx, dy, rot, alpha)
  for _, t in ipairs({ r.strip, r.stripTrim }) do
    t:SetSize(PKW * sc, PKW / 2 * sc); t:ClearAllPoints(); t:SetPoint("TOP", r.seal, "TOP", dx, dy)
    if t.SetRotation then t:SetRotation(rot) end
    t:SetAlpha(alpha)
  end
end

-- A Mythic turns over: the table goes dark, rays in every colour turn behind it, and the card rises to the middle at
-- full size. Click anywhere to go on.
function RG.ArcadeMythicMoment(g)
  if not (reveal and g and g.card) then return end
  local m = rawget(reveal, "myth")
  if not m then
    m = CreateFrame("Button", nil, reveal); m:SetAllPoints(reveal); m:SetFrameLevel(lv(reveal) + 60)
    m.veil = m:CreateTexture(nil, "BACKGROUND"); m.veil:SetAllPoints(m); m.veil:SetColorTexture(0.01, 0.01, 0.03, 0.92)
    m.rays = m:CreateTexture(nil, "BORDER"); m.rays:SetTexture(MEDIA .. "Rays"); m.rays:SetBlendMode("ADD"); m.rays:SetSize(900, 900); m.rays:SetPoint("CENTER", 0, 0)
    m.rays2 = m:CreateTexture(nil, "BORDER"); m.rays2:SetTexture(MEDIA .. "Rays"); m.rays2:SetBlendMode("ADD"); m.rays2:SetSize(640, 640); m.rays2:SetPoint("CENTER", 0, 0)
    m.halo = m:CreateTexture(nil, "ARTWORK"); m.halo:SetTexture(MEDIA .. "Glow"); m.halo:SetBlendMode("ADD"); m.halo:SetSize(620, 620); m.halo:SetPoint("CENTER", 0, 0)
    m.title = fs(m, "title", 30); m.title:SetPoint("TOP", 0, -34); m.title:SetTextColor(1, 0.95, 0.77); m.title:SetText("M Y T H I C")
    m.hint = fs(m, "head", 12); m.hint:SetPoint("BOTTOM", 0, 30); m.hint:SetTextColor(0.84, 0.82, 0.92)
    m.card = makeCard(m, 300); m.card:SetPoint("CENTER", 0, -6); m.card:SetFrameLevel(lv(m) + 2); m.card.noTip = true; m.card.hover = false; m.card:EnableMouse(false)
    m:SetScript("OnClick", function(self) anim[self] = nil; self:Hide() end)
    reveal.myth = m
  end
  paint(m.card, g.card, g.finish, 1)
  local one = g.card.mythic and g.card.mythic.one
  m.hint:SetText((one and "The rarest card there is: one per account" or ("About 1 pack in " .. math.floor(1 / TIER[7].rate + 0.5))) .. "   ·   click anywhere to go on")
  m.t0 = nil
  m.card:SetScale(0.7); m.title:SetAlpha(0)
  m:Show()
  anim[m] = function(self, t)
    self.t0 = self.t0 or t
    local e = math.min(1, (t - self.t0) / 0.7)
    local k = 1 - (1 - e) ^ 3
    local r, gg, b = hsv((t * 0.07) % 1, 0.45, 1)
    self.rays:SetVertexColor(r, gg, b, 0.5 * k); self.rays2:SetVertexColor(b, r, gg, 0.4 * k)
    if self.rays.SetRotation then self.rays:SetRotation((t * 0.1) % 6.2832); self.rays2:SetRotation((-t * 0.16) % 6.2832) end
    self.halo:SetVertexColor(1, 0.94, 0.78, (0.5 + 0.1 * math.sin(t * 2)) * k)
    self.card:SetScale(0.7 + 0.3 * k); self.title:SetAlpha(k); self.hint:SetAlpha(k)
  end
end

