    sep:SetPoint("BOTTOMLEFT", 30, 66); sep:SetPoint("BOTTOMRIGHT", -30, 66)
    reveal.all = gbtn(reveal, "Turn all", 132, 30, function()
      -- the plain cards go first, quickly; the better the card the longer the beat before it, and the best one turns last
      local order = {}
      for i = 1, #(reveal.got or {}) do
        local cv = reveal.cards[i].cover
        if cv and cv:IsShown() and not cv.flipping then order[#order + 1] = i end
      end
      local function score(i) local g = reveal.got[i]; return g.finish * 10 + g.card.tier + (g.new and 0.5 or 0) end
      table.sort(order, function(x, y) local sx, sy = score(x), score(y); if sx ~= sy then return sx < sy end return x < y end)
      local t = 0.05
      for k, i in ipairs(order) do
        local g = reveal.got[i]
        local weight = g.card.tier == 6 and 3 or (g.finish >= 3 and 2 or (g.finish == 2 and 1 or 0))
        if k > 1 then t = t + ((k == #order) and 1.0 or (weight >= 2 and 0.8 or (weight == 1 and 0.45 or 0.27))) end
        local function go() if reveal:IsShown() then flip(i) end end
        if C_Timer and C_Timer.After then C_Timer.After(t, go) else go() end
      end
    end)
    reveal.all:SetPoint("BOTTOM", -160, 22)
    -- opens the next waiting pack: one like this if you have it, else whichever kind is waiting, else buys one like this
    reveal.again = gbtn(reveal, "Open next pack", 190, 30, function()
      if not (frame and frame.buyNow) then return end
      local a, k = store(), (reveal.meta and reveal.meta.many) and "normal" or reveal.kind
      if a and tokenCount(a, k) == 0 then
        for _, kk in ipairs(PACK_ORDER) do if tokenCount(a, kk) > 0 then k = kk break end end
      end
      frame.buyNow(k)
    end, true)
    -- the packs still waiting, beside the sealed one
    local nu = CreateFrame("Frame", nil, reveal); nu:SetSize(150, 190); nu:SetPoint("RIGHT", reveal, "RIGHT", -40, 40); nu:SetFrameLevel(lv(reveal) + 2)
    nu.head = fs(nu, "head", 11); nu.head:SetPoint("TOPLEFT", 0, 0); nu.head:SetTextColor(0.769, 0.687, 0.522); nu.head:SetText("UP NEXT")
    nu.rows = {}
    for i, kk in ipairs(PACK_ORDER) do
      local r = {}
      r.tex = nu:CreateTexture(nil, "ARTWORK"); r.tex:SetTexture(MEDIA .. "PackArt" .. i); r.tex:SetTexCoord(6 / 256, 250 / 256, 100 / 512, 468 / 512); r.tex:SetSize(27, 41)
      r.name = fs(nu, "body", 13); r.name:SetTextColor(0.93, 0.89, 0.78); r.name:SetText(PACKS[kk].name)
      r.n = fs(nu, "head", 11); r.n:SetTextColor(0.769, 0.687, 0.522)
      nu.rows[i] = r
    end
    reveal.nextUp = nu
    function reveal.setNextUp(show)
      local a, y = store(), -22
      for i, kk in ipairs(PACK_ORDER) do
        local r, n = nu.rows[i], a and tokenCount(a, kk) or 0
        local on = show and n > 0
        r.tex:SetShown(on); r.name:SetShown(on); r.n:SetShown(on)
        if on then
          r.tex:ClearAllPoints(); r.tex:SetPoint("TOPLEFT", nu, "TOPLEFT", 0, y)
          r.name:ClearAllPoints(); r.name:SetPoint("TOPLEFT", r.tex, "TOPRIGHT", 10, -4)
          r.n:ClearAllPoints(); r.n:SetPoint("TOPLEFT", r.name, "BOTTOMLEFT", 0, -3); r.n:SetText(n .. " waiting")
          y = y - 52
        end
      end
      nu:SetShown(show and y < -22)
    end
    reveal.again:SetPoint("BOTTOM", 0, 22)
    reveal.ok = gbtn(reveal, "Skip", 132, 30, function() reveal:Hide(); RG.ArcadeRefresh(true) end)
    reveal.ok:SetPoint("BOTTOM", 160, 22)
    tinsert(UISpecialFrames, "WaypathArcadePack")
    -- a dark veil over the collection window, so nothing of it peeks out around the pack
    local dim = CreateFrame("Frame", nil, UIParent)
    dim:SetFrameStrata("FULLSCREEN_DIALOG"); dim:SetFrameLevel(math.max(0, lv(reveal) - 1))
    local dt = dim:CreateTexture(nil, "BACKGROUND"); dt:SetAllPoints(dim); dt:SetColorTexture(0.03, 0.03, 0.06, 1)
    reveal.dim = dim
    reveal:HookScript("OnShow", function()
      dim:ClearAllPoints()
      if frame and frame:IsShown() then dim:SetAllPoints(frame) else dim:SetSize(1, 1); dim:SetPoint("CENTER") end
      dim:Show()
    end)
    reveal:HookScript("OnHide", function() dim:Hide() end)
    -- one update loop: the seal pulses, the cards are dealt, the burst fades
    reveal:EnableMouse(true)   -- the gaps between cards must not let the mouse reach the windows underneath
    reveal:SetScript("OnUpdate", function(self, dt)
      local t = GetTime and GetTime() or 0
      -- a card tooltip from a window underneath (or left behind by one) never belongs on the pack screen
      if GameTooltip and GameTooltip:IsShown() then
        local o = GameTooltip:GetOwner()
        if o and o.card and not (o.IsDescendantOf and o:IsDescendantOf(self)) then GameTooltip:Hide() end
      end
      -- hold the mouse over a turned card to read it at full size (polled, so it cannot miss an enter or leave)
      if self.insp and not self.phase then
        local hit
        for i = 1, #(self.got or {}) do
          local c = self.cards[i]
          if c and c:IsShown() and c.card and c.known and not (c.cover and c.cover:IsShown()) and c:IsMouseOver() then hit = c break end
        end
        local ins = self.insp
        if hit then
          if ins.src ~= hit or ins.card ~= hit.card then
            ins.src = hit
            paint(ins, hit.card, hit.finish, nil)
            ins:ClearAllPoints()
            local cx, rx = hit:GetCenter(), self:GetCenter()
            local left = type(cx) == "number" and type(rx) == "number" and cx < rx
            ins:SetPoint(left and "TOPRIGHT" or "TOPLEFT", self, left and "TOPRIGHT" or "TOPLEFT", left and -16 or 16, -96)
          end
          ins:Show()
        elseif ins:IsShown() then ins:Hide(); ins.src = nil end
      end
      if self.phase == "seal" then
        if self.holding then
          self.holdT = self.holdT + dt
          local x, y = cursorXY()
          local d = math.sqrt((x - self.hx) ^ 2 + (y - self.hy) ^ 2)
          if d > self.moved then self.moved = d end
          self.tear = math.max(self.tear, math.min(1, math.max(d / 80, (self.holdT - 0.15) / 1.1)))
        else
          self.tear = math.max(0, self.tear - dt * 1.4)
        end
        self.pickIdle = self.pickIdle + dt
        if self.pickIdle > 2 and self.picks > 0 then self.picks = 0 end
        if self.tear >= 1 then tearOpen(); return end
        local tt = math.max(self.tear, self.picks / 3 * 0.85)
        local k = (self.baseK or 1) * (1 + 0.015 * math.sin(t * 3) + 0.10 * tt)
        self.lastK = k
        self.seal:SetScale(k)
        self.seal:ClearAllPoints(); self.seal:SetPoint("CENTER", math.sin(t * 55) * 2 * tt / k, (20 + math.cos(t * 47) * 1.5 * tt + 4 * math.sin(t * 1.4)) / k)
        -- the strip lifts, tilts and pulls away as the tear goes on
        stripSet(self, 1, 14 * tt, 24 * tt, -0.35 * tt, 1)
        -- the sheen: a band that sweeps across, then rests
        local cyc = (t * 0.3) % 1
        local sw = math.min(1, cyc / 0.45)
        local u0 = 0.58 - 0.46 * sw
        self.sheen:SetTexCoord(u0, u0 + 0.35, 0, 1)
        self.sheen:SetAlpha(0.55 * math.sin(math.min(1, sw) * 3.1416) ^ 0.5)
        for i, d in ipairs(self.dashes) do d:SetAlpha(math.max(0, (0.35 + 0.35 * math.sin(t * 3 - i * 0.35)) * (1 - tt * 3))) end
        self.sealHint:SetAlpha(0.65 + 0.3 * math.sin(t * 2.2))
        self.glowTex:SetAlpha(0.26 + 0.06 * math.sin(t * 2) + 0.2 * tt)
        self.sealGlow:SetAlpha(0)
        local c = self.sealCol
        local r, g, b = c[1] + (1 - c[1]) * tt * 0.4, c[2] + (1 - c[2]) * tt * 0.4, c[3] + (1 - c[3]) * tt * 0.4
        if self.artPack then r, g, b = 1, 1, 1 end   -- (a wrapper with its own picture is not tinted)
        self.sealTex:SetVertexColor(r, g, b, 1); self.strip:SetVertexColor(r, g, b, 1); self.glowTex:SetVertexColor(c[1], c[2], c[3], 1); self.sheen:SetVertexColor(1, 1, 1, 1)
        self.spot:SetVertexColor(c[1], c[2], c[3], 0.34 + 0.05 * math.sin(t * 1.7) + 0.12 * tt)
        self.floor:SetVertexColor(c[1], c[2], c[3], 0.5)
      elseif self.phase == "deal" then
        self.dealT = self.dealT + dt
        do local c = self.sealCol; self.spot:SetVertexColor(c[1], c[2], c[3], 0.2) end
        local all = true
        local n = #(self.got or {})
        for i = 1, n do
          local k = math.max(0, math.min(1, (self.dealT - (i - 1) * 0.09) / 0.4))
          local e = 1 - (1 - k) ^ 3
          local x, y, sc, cw = dealPositions(i, n)
          local cx = (RW - cw) / 2
          local c = self.cards[i]
          -- each card rises out of the open wrapper and slides to its place
          c:ClearAllPoints(); c:SetPoint("TOPLEFT", self, "TOPLEFT", (cx + (x - cx) * e) / sc, (y - 130 * (1 - e)) / sc)
          c:SetAlpha(e)
          if k < 1 then all = false end
        end
        if all then self.phase = false end
      end
      if type(self.sealFade) == "number" and self.sealFade > 0 then
        -- the strip is thrown off and the wrapper drops away
        self.sealFade = self.sealFade - dt
        local k = 1 - math.max(0, self.sealFade) / 0.55
        stripSet(self, 1, 40 + 170 * k, 24 + 140 * k - 190 * k * k, -0.35 - 1.6 * k, 1 - k)
        self.seal:SetAlpha(math.max(0, 1 - k * 1.4))
        self.spot:SetVertexColor(self.sealCol[1], self.sealCol[2], self.sealCol[3], 0.2 + 0.14 * (1 - k))
        if self.sealFade <= 0 then self.sealFade = nil; self.seal:Hide(); self.seal:SetAlpha(1); self.seal:SetScale(1); stripSet(self, 1, 0, 0, 0, 1) end
      end
      if self.shakeT > 0 then
        self.shakeT = self.shakeT - dt
        local m = 3.5 * self.shakeK * math.max(0, self.shakeT) / 0.35
        revealPoint(self, (math.random() - 0.5) * 2 * m, (math.random() - 0.5) * 2 * m)
        if self.shakeT <= 0 then revealPoint(self, 0, 0) end
      end
      if self.shardT > 0 then
        self.shardT = self.shardT - dt
        for _, sh in ipairs(self.shards) do
          sh.vy = sh.vy - 900 * dt; sh.x = sh.x + sh.vx * dt; sh.y = sh.y + sh.vy * dt
          sh.tex:ClearAllPoints(); sh.tex:SetPoint("CENTER", self, "CENTER", sh.x, sh.y)
          sh.tex:SetAlpha(math.max(0, self.shardT / 0.8))
          if self.shardT <= 0 then sh.tex:Hide() end
        end
      end
      if self.burstLeft and self.burstLeft > 0 then
        self.burstLeft = self.burstLeft - dt
        local k = math.max(0, self.burstLeft / self.burstMax)
        self.burst:SetAlpha(k * k)
        self.burstSpin = (self.burstSpin or 0) + dt * 0.5
        if self.burst.SetRotation then self.burst:SetRotation(self.burstSpin) end
        if self.burstLeft <= 0 then self.burst:Hide() end
      end
    end)
  end
  reveal.got, reveal.flipped, reveal.notes, reveal.meta, reveal.record = got, 0, notes, meta, false
  meta = meta or {}
  -- what kind of pack this is: a pack, a jumbo, a super jumbo (a reward pack is a jumbo with extra promises), or several at once
  local kind = (meta.kind and PACKS[meta.kind]) and meta.kind or "normal"
  local def = PACKS[kind]
  reveal.kind = kind
  local col, title, info = def.col, def.name, {}
  if meta.gift then
    col, title = { 1, 0.85, 0.45 }, "Level 60 gift"
    info[#info + 1] = { "Your gift", GOLDHEX .. "Three cards rated 105 or higher|r" }
    info[#info + 1] = { "Also", "5 packs, 5 jumbo packs and 5 super jumbo packs are waiting for you" }
  elseif meta.bonus then
    col, title = { 0.85, 0.6, 1 }, "Reward Jumbo Pack"
    info[#info + 1] = { "Reward pack", "|cffd9a8ff" .. def.size .. " cards: two rares and a holo or better inside|r" }
  elseif meta.many then
    col, title = { 1, 0.85, 0.45 }, meta.many.count .. " packs"
    info[#info + 1] = { "Packs", GOLDHEX .. meta.many.count .. " packs at once|r   ·   the five best cards are shown" }
  elseif meta.dungeon then
    title = meta.dungeon .. " Pack"
    info[#info + 1] = { "Contents", GOLDHEX .. def.size .. " cards|r from " .. meta.dungeon .. " only   ·   " .. def.rares .. " rare or better" }
  else
    info[#info + 1] = { "Contents", GOLDHEX .. def.size .. " cards|r from the whole collection   ·   " .. def.rares .. " rare or better" }
    if meta.daily then title = "Daily " .. def.name; info[#info + 1] = { "Daily", "|cff7be08aDay " .. (meta.streak or 1) .. " in a row|r" } end
  end
  if not meta.many and not meta.gift then
    local pb = meta.pityBefore or 0
    if meta.bonus or pb >= PITY then info[#info + 1] = { "Guarantee", "|cffd9a8ffThis pack holds a holo or full art|r" }
    else info[#info + 1] = { "Guarantee", "A holo or full art within " .. (PITY - pb) .. " pack" .. (PITY - pb == 1 and "" or "s") .. " worth of opening" } end
    -- the odds of this pack, from the same numbers it rolls with
    local o = RG.ArcadePackOdds(kind)
    info[#info + 1] = { "Odds", "|cffffe58cMythic 1 in " .. o.mythic .. " packs|r   ·   holo or full art in " .. math.floor(o.holo * 100 + 0.5) .. "%   ·   full art in " .. math.floor(o.full * 100 + 0.5) .. "%" }
  end
  -- a plain pack, jumbo or super jumbo has its own wrapper (picture and colour); gifts, reward packs and several packs
  -- at once keep the tinted foil
  local artN = (not meta.gift and not meta.bonus and not meta.many and kind ~= "dungeon") and (kind == "normal" and 1 or (kind == "jumbo" and 2 or 3)) or nil
  reveal.artPack = artN
  if artN then col = ({ { 0.62, 0.52, 1 }, { 1, 0.62, 0.28 }, { 0.3, 0.92, 0.82 } })[artN] end
  reveal.sealCol = col
  reveal.sealTex:SetTexture(MEDIA .. (artN and ("PackArt" .. artN) or "PackBody")); reveal.strip:SetTexture(MEDIA .. (artN and ("PackArtTop" .. artN) or "PackTop"))
  reveal.trim:SetShown(not artN); reveal.packName:SetShown(not artN)
  if artN then reveal.sealTex:SetVertexColor(1, 1, 1, 1); reveal.strip:SetVertexColor(1, 1, 1, 1)
  else reveal.sealTex:SetVertexColor(col[1], col[2], col[3], 1); reveal.strip:SetVertexColor(col[1], col[2], col[3], 1) end
  if rawget(reveal, "myth") then reveal.myth:Hide() end
  reveal.baseK = meta.many and 1.04 or (kind == "super" and 1.08 or (kind == "jumbo" and 1.04 or 1))
  -- the wrapper: tinted by pack type, the rune in the medallion; several packs fan out
  reveal.emb:Hide(); reveal.sealCount:SetText(""); reveal.ribbon:Hide(); reveal.ribbonText:SetText("")
  for _, bt in ipairs(reveal.packBack) do bt:SetVertexColor(col[1] * 0.7, col[2] * 0.7, col[3] * 0.7, 1); bt:SetShown(meta.many and true or false) end
  reveal.packKind:SetText(meta.many and ("x" .. meta.many.count) or (meta.gift and "GIFT" or (def.size .. " CARDS")))
  do
    local label, size = "WAYPATH", 14
    if meta.dungeon then label, size = RG.ArcadePackLabel(meta.dungeon)
    elseif kind ~= "normal" then label = kind == "jumbo" and "JUMBO" or "SUPER JUMBO" end
    local font, _, flags = reveal.packName:GetFont()
    if font then reveal.packName:SetFont(font, size, flags) end
    reveal.packName:SetText(label)
  end
  if meta.many then reveal.sealCount:SetText("x" .. meta.many.count)
  else reveal.emb:SetTexture(MEDIA .. "Rune"); reveal.emb:SetTexCoord(0, 1, 0, 1); reveal.emb:SetVertexColor(math.min(1, col[1] + 0.3), math.min(1, col[2] + 0.3), math.min(1, col[3] + 0.3), 0.95); reveal.emb:Show() end
  if artN then reveal.emb:Hide() end   -- (the picture is on the wrapper)
  reveal.sealFade = nil; reveal.seal:SetAlpha(1)
  reveal.setNextUp(true)
  setPlaque(info)
  reveal.plaque.bar:SetColorTexture(math.min(1, col[1] + 0.1), math.min(1, col[2] + 0.1), math.min(1, col[3] + 0.1), 1)
  reveal.title:SetText(title)
  reveal.all:Show(); reveal.share:Hide(); reveal.ok:SetText("Skip")
  do local a = store(); reveal.snd:SetText(a and a.mute and "Sound: off" or "Sound: on") end
  reveal.burst:Hide(); reveal.burstLeft = 0
  reveal.tear, reveal.picks, reveal.holding, reveal.shardT, reveal.shakeT = 0, 0, false, 0, 0
  for _, sh in ipairs(reveal.shards) do sh.tex:Hide() end
  do local sc = frame and frame.GetScale and frame:GetScale(); reveal:SetScale(type(sc) == "number" and sc > 0 and sc or 1) end
  revealPoint(reveal, 0, 0)
  reveal:Show()
  reveal.phase = "seal"
  reveal.seal:SetScale(reveal.baseK or 1); reveal.seal:ClearAllPoints(); reveal.seal:SetPoint("CENTER", 0, 20 / (reveal.baseK or 1))
  reveal.seal:Show(); reveal.seal:SetSize(PKW, PKH); reveal.seal:SetAlpha(1)
  reveal.spot:ClearAllPoints(); reveal.spot:SetPoint("CENTER", reveal, "CENTER", 0, 24); reveal.spot:SetSize(640, 560)
  stripSet(reveal, 1, 0, 0, 0, 1); reveal.sealTex:SetAlpha(1)
  for i = 1, PACK_MAX do reveal.cards[i]:Hide() end
  for i, g in ipairs(got) do
    local w = reveal.cards[i]
    paint(w, g.card, g.finish, 1)
    w.new:SetText("")
    local c = w.cover
    c.flipping = false; c:SetScript("OnUpdate", nil); c:SetWidth(w.cw); c:Show()
    c.peel, c.lift, c.holding = 0, 0, false; c.fold:Hide(); c.peek:Hide(); c:SetHeight(w.ch); c.tex:SetTexCoord(0, 1, 0, CARD_V)
    c:ClearAllPoints(); c:SetPoint("CENTER", 0, 0); c.cued = false
    -- how good the card inside is: the better of its print (Rare 2, Holo 3, Full art 4) and its rarity (Renowned 2, Epic 3, Legendary 4)
    local glowLv = math.max(g.finish, (g.card.tier >= 3 and g.card.tier <= 5) and g.card.tier - 1 or 1)
    c.rare = (glowLv >= 3 or g.card.tier == 6) and true or false
    c.glowCol = g.card.tier == 6 and { 1, 0.2, 0.35 } or (glowLv == 4 and { 1, 0.7, 0.15 } or (glowLv == 3 and { 0.7, 0.35, 0.95 } or { 0.3, 0.55, 1 }))
    c.prismatic = g.card.tier == 7 or nil   -- a Mythic inside: the glow runs through every colour
    c.peekCol = g.card.tier == 6 and { 1, 0.2, 0.35 } or (g.finish == 4 and { 1, 0.75, 0.2 } or (g.finish == 3 and { 0.7, 0.35, 0.95 } or (g.finish == 2 and { 0.3, 0.55, 1 } or { 0.691, 0.617, 0.469 })))
    if RG.CardBackName then c.tex:SetTexture(MEDIA .. RG.CardBackName()) end
    if glowLv >= 2 or g.card.tier >= 6 then c.glow:Show(); anim[c] = coverAnim else anim[c] = nil; c.glow:Hide() end
    w:SetAlpha(0); w:Hide()   -- 3D models ignore alpha: the cards stay hidden until they are dealt
  end
  do   -- "Open next pack" while packs are waiting, else it buys another like this one
    local a, waiting = store(), 0
    if a then for _, kk in ipairs(PACK_ORDER) do waiting = waiting + tokenCount(a, kk) end end
    reveal.again:SetText(waiting > 0 and "Open next pack" or "Buy another pack")
    reveal.again:SetEnabled((waiting > 0 or afford(meta.many and "normal" or kind)) and true or false)
  end
end

-- A set stage finished by this pack: a banner in the medal's colour rises over the pack, rays turn behind it
function RG.ArcadeStageCelebrate(list)
  if not (reveal and reveal:IsShown() and list and list[1]) then return end
  local w = list[#list]   -- the highest one this pack reached
  local sg = RG.ARCADE_STAGES[w.stage]
  local c = sg[3]
  local b = rawget(reveal, "stageBanner")
  if not b then
    b = CreateFrame("Button", nil, reveal); b:SetSize(460, 120); b:SetFrameLevel(reveal:GetFrameLevel() + 40)
    b.rays = b:CreateTexture(nil, "BACKGROUND"); b.rays:SetTexture(MEDIA .. "Rays"); b.rays:SetBlendMode("ADD"); b.rays:SetSize(420, 420); b.rays:SetPoint("CENTER")
    b.glow = b:CreateTexture(nil, "BORDER"); b.glow:SetTexture(MEDIA .. "Soft"); b.glow:SetBlendMode("ADD"); b.glow:SetSize(520, 200); b.glow:SetPoint("CENTER")
    b.plate = b:CreateTexture(nil, "ARTWORK"); b.plate:SetColorTexture(0.06, 0.05, 0.04, 0.88); b.plate:SetSize(440, 92); b.plate:SetPoint("CENTER")
    b.edge1 = b:CreateTexture(nil, "ARTWORK", nil, 2); b.edge1:SetHeight(2); b.edge1:SetPoint("TOPLEFT", b.plate, "TOPLEFT"); b.edge1:SetPoint("TOPRIGHT", b.plate, "TOPRIGHT")
    b.edge2 = b:CreateTexture(nil, "ARTWORK", nil, 2); b.edge2:SetHeight(2); b.edge2:SetPoint("BOTTOMLEFT", b.plate, "BOTTOMLEFT"); b.edge2:SetPoint("BOTTOMRIGHT", b.plate, "BOTTOMRIGHT")
    b.head = fs(b, "head", 12); b.head:SetPoint("TOP", b.plate, "TOP", 0, -12)
    b.title = fs(b, "title", 22); b.title:SetPoint("CENTER", b.plate, "CENTER", 0, 0)
    b.sub = fs(b, "body", 12); b.sub:SetPoint("BOTTOM", b.plate, "BOTTOM", 0, 11); b.sub:SetTextColor(0.9, 0.86, 0.74)
    b:SetScript("OnClick", function(self) self:Hide() end)
    b:SetScript("OnUpdate", function(self, dt)
      self.age = self.age + dt
      if self.rays.SetRotation then self.rays:SetRotation(self.age * 0.4) end
      local rise = math.min(1, self.age / 0.35)
      self:ClearAllPoints(); self:SetPoint("CENTER", reveal, "CENTER", 0, 40 + 30 * rise)
      self:SetAlpha(self.age < 0.35 and rise or (self.age > 5 and math.max(0, 6 - self.age) or 1))
      if self.age > 6 then self:Hide() end
    end)
    reveal.stageBanner = b
  end
  b.rays:SetVertexColor(c[1], c[2], c[3], 0.55); b.glow:SetVertexColor(c[1], c[2], c[3], 0.4)
  b.edge1:SetColorTexture(c[1], c[2], c[3], 0.9); b.edge2:SetColorTexture(c[1], c[2], c[3], 0.9)
  b.head:SetText(w.name:upper()); b.head:SetTextColor(c[1], c[2], c[3])
  b.title:SetText(sg[1]:upper() .. " SET"); b.title:SetTextColor(c[1], c[2], c[3])
  b.sub:SetText(w.text .. (#list > 1 and ("   ·   and " .. (#list - 1) .. " more") or ""))
  b.age = 0; b:SetAlpha(0); b:Show()
  playSound(nil, nil, "reward")
end

-- the present for reaching level 60 (shown when you are out of combat, or the next time you open the cards)
function RG.ArcadeClaimGift()
  local a = store(); if not a or a.giftDone then return end
  if InCombatLockdown and InCombatLockdown() then a.giftPending = true return end
  local got = RG.ArcadeGiftCards(); if not got then return end
  a.giftDone, a.giftPending = true, nil
  RG.ArcadeGrant("Level 60 gift", 0, { normal = 5, jumbo = 5, super = 5 })
  playSound(nil, nil, "reward")
  showReveal(got, {}, { gift = true, kind = "super", size = 3, free = true, pityBefore = 0, sets = {}, streak = a.packStreak })
  RG.ArcadeRefresh(true)
end

