local function say(text)
  if frame and frame:IsShown() and frame.msg then
    frame.msg:SetText(text or "")
    -- (a note clears itself after a while, so it doesn't follow you to other tabs)
    RG.__sayToken = (RG.__sayToken or 0) + 1   -- (an RG field: this file has no room for another top-level local)
    local mine = RG.__sayToken
    if text and text ~= "" and C_Timer and C_Timer.After then
      C_Timer.After(8, function() if RG.__sayToken == mine and frame and frame.msg then frame.msg:SetText("") end end)
    end
  elseif RG.Print then RG.Print(text) end
end
RG.ArcadeMsg = say

local function refreshDetail()
  if not (detail and detail:IsShown() and detail.data) then return end
  local a = store()
  local c = detail.data
  local slot = a.cards[c.key or c.name] or {}
  local f = detail.finish
  local have = slot[f] or 0
  paint(detail.card, c, f, have > 0 and owned(a, c.id) or nil)   -- a print you do not have is shown as a preview
  local t = TIER[c.tier][3]
  detail.name:SetText(c.name); detail.name:SetTextColor(t[1], t[2], t[3])
  detail.kind:SetText(KIND[c.kind] .. "  ·  " .. TIER[c.tier][1])
  detail.flavor:SetText(c.text or "")
  -- what the card does in the Arena (the same rules both duel players use), next to its quick-duel power
  local arena = ""
  local B = RG.Battle
  if B and B.defs then
    local k = c.key or c.name
    local d = B.defs[k] or (B.derive and B.derive(c))
    if d then
      local body = d.type == "minion" and (d.atk .. "/" .. d.hp .. " minion") or (d.type == "weapon" and (d.atk .. "/" .. d.dur .. " weapon") or "spell")
      if d.hclass then body = (d.hclass:sub(1, 1) .. d.hclass:sub(2):lower()) .. " " .. body end
      local txt = B.describe and B.describe(d) or ""
      arena = "\nArena: |cffffffff" .. d.cost .. " mana " .. body .. "|r" .. (txt ~= "" and ("  ·  " .. txt) or "")
      if RG.ArcadeRefundOpen(a, k) then arena = arena .. "\n|cff7be08aChanged in the latest Arena card update: copies you owned then refund for full crafting value until " .. date("%b %d", a.refundUntil) .. "|r" end
    end
  end
  detail.info:SetText("Set: |cffffffff" .. setOf(c) .. "|r" .. arena .. "\nDuel power: |cffffffff" .. power(c, f) .. "|r" .. (a.duelCard == (c.key or c.name) and "   |cff7be08aYour duel card|r" or "")
    .. "\nOwned: |cffffffff" .. owned(a, c.id) .. "|r" .. (have == 0 and ("\n|cffe0b36bYou do not have this print yet|r") or ""))
  for k = 1, 4 do
    local n = slot[k] or 0
    local b = detail.prints[k]
    b:SetText(FNAME[k] .. " x" .. n)
    b:SetEnabled(true); b:SetActive(k == f)
  end
  local cost = RG.ArcadeCraftCost(c, f)
  local refund = RG.ArcadeRefundable(a, c.key or c.name, f) > 0
  detail.craft:SetWidth(refund and 160 or 324)
  detail.craft:SetText(cost and (refund and ("Craft  ·  " .. cost) or ("Craft " .. FNAME[f] .. "  ·  " .. cost .. " coins")) or "Cannot be crafted")
  detail.craft:SetEnabled(cost ~= nil and (a.coins or 0) >= cost)
  if refund then detail.refund:SetText("Refund  ·  " .. (cost or 0) .. " coins"); detail.refund:Show() else detail.refund:Hide() end
  detail.pin:SetEnabled(owned(a, c.id) > 0); detail.duel:SetEnabled(owned(a, c.id) > 0)
  detail.pin:SetText(isPinned(a, c) and "Remove from showcase" or "Add to showcase")
  detail.duel:SetText(a.duelCard == (c.key or c.name) and "Duel card (set)" or "Use for duels")
  detail.offer:SetEnabled(c.kind ~= 4 and (slot[f] or 0) >= 1)
end

local function openDetail(c)
  if reveal and reveal:IsShown() then return end   -- finish opening the pack first
  local a = store()
  if not (a and c) then return end
  if not detail then
    detail = CreateFrame("Frame", "WaypathArcadeCard", UIParent, "BackdropTemplate")
    detail:SetPoint("CENTER", 100, 0); detail:SetFrameStrata("FULLSCREEN_DIALOG")
    darkPanel(detail, 640, 470)
    tinsert(UISpecialFrames, "WaypathArcadeCard")
    detail.card = makeCard(detail, 230); detail.card:SetPoint("TOPLEFT", 30, -40); detail.card:SetFrameLevel(lv(detail) + 3); detail.card.noTip = true
    local X0 = 290
    detail.name = fs(detail, "title", 20); detail.name:SetPoint("TOPLEFT", X0, -36); detail.name:SetWidth(320); detail.name:SetJustifyH("LEFT"); detail.name:SetWordWrap(true)
    detail.kind = fs(detail, "head", 12); detail.kind:SetPoint("TOPLEFT", detail.name, "BOTTOMLEFT", 0, -4); detail.kind:SetTextColor(0.825, 0.737, 0.56)
    local rule = detail:CreateTexture(nil, "ARTWORK"); rule:SetTexture(MEDIA .. "Rule"); rule:SetSize(320, 14); rule:SetPoint("TOPLEFT", detail.kind, "BOTTOMLEFT", 0, -6)
    detail.flavor = fs(detail, "body", 14); detail.flavor:SetPoint("TOPLEFT", rule, "BOTTOMLEFT", 0, -6); detail.flavor:SetWidth(320); detail.flavor:SetJustifyH("LEFT"); detail.flavor:SetTextColor(0.86, 0.82, 0.7); detail.flavor:SetSpacing(3)
    detail.info = fs(detail, "body", 13); detail.info:SetPoint("TOPLEFT", detail.flavor, "BOTTOMLEFT", 0, -10); detail.info:SetWidth(320); detail.info:SetJustifyH("LEFT"); detail.info:SetTextColor(0.833, 0.743, 0.565); detail.info:SetSpacing(3)
    local close = gbtn(detail, "X", 26, 24, function() detail:Hide() end); close:SetPoint("TOPRIGHT", -14, -14)
    detail.prints = {}
    for k = 1, 4 do
      local b = gbtn(detail, "", 80, 24, function() detail.finish = k; refreshDetail() end)
      b:SetPoint("BOTTOMLEFT", X0 + (k - 1) * 82, 118)
      detail.prints[k] = b
    end
    detail.pin = gbtn(detail, "Showcase", 160, 26, function()
      local on = RG.ArcadePin(detail.data); say(on and (detail.data.name .. " added to your showcase.") or (detail.data.name .. " removed from your showcase.")); refreshDetail(); RG.ArcadeRefresh(true)
    end)
    detail.pin:SetPoint("BOTTOMLEFT", X0, 80)
    detail.duel = gbtn(detail, "Use for duels", 160, 26, function()
      local a2 = store(); a2.duelCard = detail.data.key or detail.data.name; say(detail.data.name .. " will fight your duels."); refreshDetail()
    end)
    detail.duel:SetPoint("BOTTOMLEFT", X0 + 164, 80)
    detail.link = gbtn(detail, "Link in chat", 160, 26, function()
      local c2 = detail.data
      local text = "[Waypath card: " .. c2.name .. " (" .. FNAME[detail.finish] .. ")]"
      if ChatEdit_InsertLink then pcall(ChatEdit_InsertLink, text) elseif DEFAULT_CHAT_FRAME and DEFAULT_CHAT_FRAME.editBox then DEFAULT_CHAT_FRAME.editBox:Insert(text) end
    end)
    detail.link:SetPoint("BOTTOMLEFT", X0, 44)
    detail.offer = gbtn(detail, "Offer to group", 160, 26, function()
      local ok, msg = RG.ArcadeOffer(detail.data, detail.finish); say(msg)
    end)
    detail.offer:SetPoint("BOTTOMLEFT", X0 + 164, 44)
    detail.craft = gbtn(detail, "Craft", 324, 28, function()
      local ok, msg = RG.ArcadeCraft(detail.data, detail.finish); say(msg)
      refreshDetail(); if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
    end, true)
    detail.craft:SetPoint("BOTTOMLEFT", X0, 152)
    -- after a card update: sell a changed card back for its full crafting value
    detail.refund = gbtn(detail, "Refund", 160, 28, function()
      local ok, msg = RG.ArcadeRefund(detail.data, detail.finish); say(msg)
      refreshDetail(); if RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
    end)
    detail.refund:SetPoint("BOTTOMLEFT", X0 + 164, 152); detail.refund:Hide()
  end
  detail.data, detail.finish = c, bestFinish(a, c.id) or 1
  detail:Show(); refreshDetail()
end

