local MODES = { { "cards", "Collection" }, { "album", "Album" }, { "sets", "Sets" }, { "shop", "Shop" }, { "today", "Today" }, { "trade", "Trade" }, { "stats", "Ledger" } }

local function cell_click(self, btn)
  local c = self.card
  if not c then return end
  local a = store()
  if owned(a, c.id) == 0 then openDetail(c) return end   -- a missing card opens so it can be crafted
  if btn == "RightButton" then
    local on = RG.ArcadePin(c); say(on and (c.name .. " added to your showcase.") or (c.name .. " removed from your showcase."))
    RG.ArcadeRefresh(true)
  else openDetail(c) end
end

-- Drag the bottom-right corner to make a card window bigger or smaller (it keeps its shape; the size is remembered
-- in your card save under `key`). Double-click the corner for the standard size.
local function scaleGrip(f, key, base)
  local g = CreateFrame("Button", nil, f)
  g:SetSize(18, 18); g:SetPoint("BOTTOMRIGHT", -6, 6); g:SetFrameLevel(lv(f) + 90)
  g:SetNormalTexture("Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Up"); g:SetHighlightTexture("Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Highlight")
  g:SetScript("OnMouseDown", function(self)
    self.sx = GetCursorPosition(); self.s0 = f:GetScale(); self.w0 = f:GetWidth() * f:GetEffectiveScale()
    self:SetScript("OnUpdate", function(gg)
      local cx = GetCursorPosition()
      local sc = math.max(0.45, math.min(1.6, gg.s0 * (gg.w0 + (cx - gg.sx)) / gg.w0))
      f:SetScale(sc)
    end)
  end)
  g:SetScript("OnMouseUp", function(self)
    self:SetScript("OnUpdate", nil)
    local a = store(); local b = (base and base()) or 1
    if a then a[key] = math.floor(f:GetScale() / b * 100 + 0.5) / 100 end
  end)
  g:SetScript("OnDoubleClick", function() local a = store(); if a then a[key] = nil end; f:SetScale((base and base()) or 1) end)
  g:SetScript("OnEnter", function(self) GameTooltip:SetOwner(self, "ANCHOR_TOPLEFT"); GameTooltip:SetText("Drag to resize"); GameTooltip:AddLine("Make it small and keep playing beside the game. Double-click for the standard size.", 1, 1, 1, true); GameTooltip:Show() end)
  g:SetScript("OnLeave", function() GameTooltip:Hide() end)
  return g
end

local function build()
  frame = CreateFrame("Frame", "WaypathArcade", UIParent, "BackdropTemplate")
  frame:SetPoint("CENTER"); frame:SetFrameStrata("DIALOG")
  frame:SetMovable(true); frame:EnableMouse(true); frame:RegisterForDrag("LeftButton")
  frame:SetScript("OnDragStart", frame.StartMoving); frame:SetScript("OnDragStop", frame.StopMovingOrSizing)
  frame.night = darkPanel(frame, WINW, WINH)
  frame.grip = scaleGrip(frame, "uiScale", function()
    local ph = UIParent and UIParent.GetHeight and UIParent:GetHeight()
    return (type(ph) == "number" and ph > 0 and ph < WINH + 30) and math.max(0.6, (ph - 30) / WINH) or 1
  end)
  frame:SetClampedToScreen(true)
  tinsert(UISpecialFrames, "WaypathArcade")
  -- a slowly turning circle behind the cards, and drifting motes
  frame.circle = frame:CreateTexture(nil, "BACKGROUND", nil, 3); frame.circle:SetTexture(MEDIA .. "Rune"); frame.circle:SetBlendMode("ADD")
  frame.circle:SetSize(640, 640); frame.circle:SetPoint("CENTER", frame, "CENTER", 0, -30); frame.circle:SetVertexColor(0.9, 0.72, 0.38, 0.09)
  frame.motes = {}
  for i = 1, 12 do
    local m = frame:CreateTexture(nil, "BACKGROUND", nil, 4); m:SetTexture("Interface\\Cooldown\\star4"); m:SetBlendMode("ADD"); m:SetSize(10 + (i % 3) * 5, 10 + (i % 3) * 5)
    m.px, m.py, m.sp = math.random(), math.random(), 0.01 + math.random() * 0.02
    frame.motes[i] = m
  end
  frame.open = 1
  frame:SetScript("OnShow", function(self) self.open = 0; self:SetAlpha(0) end)
  frame:SetScript("OnUpdate", function(self, dt)
    local t = GetTime and GetTime() or 0
    if self.open and self.open < 1 then self.open = math.min(1, self.open + dt / 0.35); self:SetAlpha(self.open) end
    if self.circle.SetRotation then self.circle:SetRotation((t * 0.025) % 6.2832) end
    for _, m in ipairs(self.motes) do
      m.py = m.py + m.sp * dt; if m.py > 1 then m.py = 0; m.px = math.random() end
      m:ClearAllPoints(); m:SetPoint("CENTER", self, "BOTTOMLEFT", (m.px + 0.015 * math.sin(t * 0.7 + m.px * 9)) * WINW, m.py * WINH)
      m:SetAlpha(0.5 * math.sin(m.py * 3.1416) * (0.6 + 0.4 * math.sin(t * 2 + m.px * 20)))
    end
  end)
  -- title plate
  local plate = frame:CreateTexture(nil, "ARTWORK"); plate:SetTexture(MEDIA .. "Plate"); plate:SetSize(380, 48); plate:SetPoint("TOP", 0, -12)
  frame.title = fs(frame, "title", 22); frame.title:SetPoint("CENTER", plate, "CENTER", 0, 0); frame.title:SetText("WAYPATH CARDS"); frame.title:SetTextColor(GOLDC[1], GOLDC[2], GOLDC[3])
  frame.tagline = fs(frame, "body", 14); frame.tagline:SetPoint("TOP", plate, "BOTTOM", 0, -4); frame.tagline:SetText("a collector's grimoire"); frame.tagline:SetTextColor(0.937, 0.837, 0.636)
  frame.coinIcon = frame:CreateTexture(nil, "ARTWORK"); frame.coinIcon:SetTexture("Interface\\Icons\\INV_Misc_Coin_01"); frame.coinIcon:SetSize(20, 20); frame.coinIcon:SetTexCoord(0.07, 0.93, 0.07, 0.93); frame.coinIcon:SetPoint("TOPLEFT", 30, -22)
  frame.coins = fs(frame, "head", 16); frame.coins:SetPoint("LEFT", frame.coinIcon, "RIGHT", 6, 0)
  frame.free = fs(frame, "head", 12); frame.free:SetPoint("TOPLEFT", frame.coinIcon, "BOTTOMLEFT", 0, -3); frame.free:SetTextColor(0.5, 0.88, 0.6)
  local close = gbtn(frame, "X", 28, 24, function() frame:Hide() end); close:SetPoint("TOPRIGHT", -18, -18)
  local rule = frame:CreateTexture(nil, "ARTWORK"); rule:SetTexture(MEDIA .. "Rule"); rule:SetSize(360, 14); rule:SetPoint("TOP", frame.tagline, "BOTTOM", 0, -4)
  frame.sub = fs(frame, "body", 13); frame.sub:SetPoint("TOP", rule, "BOTTOM", 0, -1); frame.sub:SetSpacing(1); frame.sub:SetTextColor(1, 0.95, 0.722); frame.sub:SetJustifyH("CENTER"); frame.sub:SetWidth(WINW - 120)

  -- tabs
  frame.modes = {}
  local tw = 98
  for i, m in ipairs(MODES) do
    local t = gtab(frame, m[2]:upper(), tw, function() view.mode = m[1]; view.set = (m[1] == "cards") and view.set or nil; RG.ArcadeRefresh(true) end)
    t:SetPoint("TOP", frame, "TOP", (i - (#MODES + 1) / 2) * (tw + 6), -128)
    frame.modes[m[1]] = t
  end
  -- filters
  frame.filters = {}
  local labels = { [0] = "All", "Items", "NPCs", "Places", "Raiders" }
  for k = 0, 4 do
    frame.filters[k] = gbtn(frame, labels[k], 60, 24, function() view.kind = k; view.page = 1; view.showcase = false; view.mode = "cards"; RG.ArcadeRefresh(true) end)
    frame.filters[k]:SetPoint("TOPLEFT", 34 + k * 62, -160)
  end
  frame.showcase = gbtn(frame, "Showcase", 80, 24, function() view.showcase = not view.showcase; view.kind = 0; view.page = 1; view.mode = "cards"; RG.ArcadeRefresh(true) end)
  frame.showcase:SetPoint("TOPLEFT", 34 + 5 * 62, -160)
  frame.sortBtn = gbtn(frame, "Sort: Collection", 124, 24, function() view.sort = view.sort % #SORTS + 1; view.page = 1; RG.ArcadeRefresh(true) end)
  frame.sortBtn:SetPoint("TOPRIGHT", -34, -160)
  frame.showBtn = gbtn(frame, "Show: All", 100, 24, function() view.show = view.show % #SHOWS + 1; view.page = 1; RG.ArcadeRefresh(true) end)
  frame.showBtn:SetPoint("RIGHT", frame.sortBtn, "LEFT", -6, 0)
  frame.searchBox = CreateFrame("EditBox", nil, frame, "BackdropTemplate")
  frame.searchBox:SetSize(92, 24); frame.searchBox:SetPoint("RIGHT", frame.showBtn, "LEFT", -6, 0)
  frame.searchBox:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); frame.searchBox:SetBackdropColor(0.03, 0.02, 0.07, 0.95); frame.searchBox:SetBackdropBorderColor(0.45, 0.38, 0.25, 0.9)
  setfont(frame.searchBox, "body", 14); frame.searchBox:SetTextColor(0.95, 0.9, 0.78); frame.searchBox:SetTextInsets(8, 6, 0, 0)
  frame.searchBox:SetAutoFocus(false); frame.searchBox:SetMaxLetters(30)
  frame.searchBox:SetScript("OnTextChanged", function(self) local t = self:GetText() or ""; if t ~= view.search then view.search = t; view.page = 1; RG.ArcadeRefresh(true) end end)
  frame.searchBox:SetScript("OnEscapePressed", function(self) self:ClearFocus() end)
  frame.searchHint = fs(frame.searchBox, "body", 14); frame.searchHint:SetPoint("LEFT", 8, 0); frame.searchHint:SetText("Search"); frame.searchHint:SetTextColor(0.84, 0.75, 0.57)
  -- the Album's top row: the set (< name >) and, for a dungeon, its pack
  local function albumStep(d)
    local all = getSets()
    local cur
    for _, st in ipairs(all) do if st.name == view.album then cur = st end end
    local sec = cur and RG.ArcadeSetSection and RG.ArcadeSetSection(cur)
    local sets = {}
    for _, st in ipairs(all) do if not sec or RG.ArcadeSetSection(st) == sec then sets[#sets + 1] = st end end
    local at = 1
    for i, st in ipairs(sets) do if st.name == view.album then at = i end end
    view.album = sets[(at - 1 + d) % #sets + 1].name; view.albumPage = 1
    RG.ArcadeRefresh(true)
  end
  frame.albPrev = gbtn(frame, "<", 30, 24, function() albumStep(-1) end); frame.albPrev:SetPoint("TOPLEFT", 34, -160)
  frame.albTitle = fs(frame, "head", 14); frame.albTitle:SetPoint("LEFT", frame.albPrev, "RIGHT", 10, 0); frame.albTitle:SetWidth(430); frame.albTitle:SetJustifyH("LEFT")
  frame.albTitle:SetTextColor(1, 0.933, 0.709); if frame.albTitle.SetWordWrap then frame.albTitle:SetWordWrap(false) end
  frame.albNext = gbtn(frame, ">", 30, 24, function() albumStep(1) end); frame.albNext:SetPoint("LEFT", frame.albPrev, "RIGHT", 350, 0)
  frame.albOpen = gbtn(frame, "Open pack", 210, 24, function()
    local dn = view.album
    if RG.ArcadeFieldClick and RG.ArcadeFieldClick(dn) then return end   -- (a Field Guide page: show the next one on the map)
    if not (dn and RG.ArcadeDunPools and RG.ArcadeDunPools[dn]) then return end
    if frame.buyNow then frame.buyNow("dungeon", dn) end
  end)
  frame.albOpen:SetPoint("TOPRIGHT", -34, -160)
  -- the Trade tab: your party, or friends' and guildmates' albums
  frame.tradeSwitch = gbtn(frame, "Friends' albums", 190, 24, function()
    view.tradeSub = view.tradeSub == "friends" and nil or "friends"
    if view.tradeSub == "friends" and RG.ArcadeSocialAsk then RG.ArcadeSocialAsk() end
    RG.ArcadeRefresh(true)
  end)
  frame.tradeSwitch:SetPoint("TOPRIGHT", -34, -160)
  frame.albOpen:HookScript("OnEnter", function(self)
    local dn = view.album
    if RG.ArcadeFieldClick and RG.ArcadeFieldClick(dn) then return end   -- (a Field Guide page: show the next one on the map)
    if not (dn and RG.ArcadeDunPools and RG.ArcadeDunPools[dn]) then return end
    local have, cleared = RG.ArcadeDungeonPacks(dn)
    GameTooltip:SetOwner(self, "ANCHOR_BOTTOM")
    GameTooltip:AddLine(dn .. " pack")
    GameTooltip:AddLine("5 cards from " .. dn .. " only: the place, its bosses, their drops and its elites. " .. ((RG.ArcadePackOdds and ("Mythic 1 in " .. RG.ArcadePackOdds("dungeon").mythic .. " packs.")) or ""), 1, 1, 1, true)
    GameTooltip:AddLine("Clearing it (three of its bosses) gives two the first time and one more each time after (twice a day). " ..
      (cleared and ("Since you've cleared it, you can also buy them for " .. PACKS.dungeon.price .. " coins.") or "Once you've cleared it, you can also buy them with coins."), 0.8, 0.8, 0.8, true)
    GameTooltip:Show()
  end)
  frame.albOpen:HookScript("OnLeave", function() GameTooltip:Hide() end)

  -- the binder
  cells = {}
  local gx0 = (WINW - ((COLS - 1) * GRIDX + CELLW)) / 2
  for i = 1, COLS * ROWS do
    local c = makeCard(frame, CELLW)
    c:SetFrameLevel(lv(frame) + 3)
    c.homeX, c.homeY = gx0 + ((i - 1) % COLS) * GRIDX, -196 - math.floor((i - 1) / COLS) * GRIDY
    c:SetPoint("TOPLEFT", frame, "TOPLEFT", c.homeX, c.homeY)
    -- under your mouse a card lifts a little off the page, with a soft glow beneath it
    c.lift = c:CreateTexture(nil, "BACKGROUND", nil, -7); c.lift:SetTexture(MEDIA .. "Soft"); c.lift:SetBlendMode("ADD")
    c.lift:SetPoint("TOPLEFT", -14, 10); c.lift:SetPoint("BOTTOMRIGHT", 14, -18); c.lift:SetVertexColor(1, 0.85, 0.5, 0.35); c.lift:Hide()
    c:HookScript("OnEnter", function(self)
      self:ClearAllPoints(); self:SetPoint("TOPLEFT", frame, "TOPLEFT", self.homeX, self.homeY + 5)
      self:SetFrameLevel(lv(frame) + 6); self.lift:Show()
    end)
    c:HookScript("OnLeave", function(self)
      self:ClearAllPoints(); self:SetPoint("TOPLEFT", frame, "TOPLEFT", self.homeX, self.homeY)
      self:SetFrameLevel(lv(frame) + 3); self.lift:Hide()
    end)
    c.onCard = cell_click
    c.noTip = true     -- the card is shown at full size beside the window instead of a text tooltip
    -- the Album: a card you don't have yet says where it comes from
    c:HookScript("OnEnter", function(self)
      if view.mode ~= "album" or not self.card or self.known then return end
      local cd = self.card
      GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
      GameTooltip:AddLine(cd.name, 1, 0.93, 0.74)
      GameTooltip:AddLine("Not in your collection yet", 0.8, 0.8, 0.8)
      local hooked
      for _, fn in ipairs(RG.ArcadeTipHooks or {}) do if not hooked then local ok, r = pcall(fn, cd, view.album); hooked = ok and r end end
      if hooked then -- (a Field Guide or raid card: where it comes from)
      elseif cd.dun then GameTooltip:AddLine("From " .. cd.dun .. " packs: clear it to earn them", 0.55, 0.8, 1, true)
      elseif cd.tier == 7 then GameTooltip:AddLine("A Mythic: any pack but a dungeon's can hold one (dungeon packs hold their own)", 1, 0.9, 0.55, true)
      else GameTooltip:AddLine("From any pack" .. ((RG.ARCADE_DUNGEON_OF and RG.ARCADE_DUNGEON_OF[cd.name]) and (" or a " .. RG.ARCADE_DUNGEON_OF[cd.name] .. " pack") or ""), 0.55, 0.8, 1, true) end
      GameTooltip:AddLine("Click to see it (and craft it from extras)", 0.6, 0.6, 0.6)
      GameTooltip:Show()
    end)
    c:HookScript("OnLeave", function() if view.mode == "album" then GameTooltip:Hide() end end)
    c:HookScript("OnEnter", function(self)
      if not self.card or not self.known or not frame.insp then return end
      local ins = frame.insp
      paint(ins, self.card, self.finish, self.copies)
      ins:ClearAllPoints()
      local right = frame:GetRight() or 0
      local sw = UIParent and UIParent:GetWidth() or 1920
      if right + 250 < sw then ins:SetPoint("TOPLEFT", frame, "TOPRIGHT", 8, -150) else ins:SetPoint("TOPRIGHT", frame, "TOPLEFT", -8, -150) end
      ins:Show()
    end)
    c:HookScript("OnLeave", function() if frame.insp then frame.insp:Hide() end end)
    cells[i] = c
  end
  frame.cells = cells
  frame.insp = makeCard(frame, 230); frame.insp:SetFrameLevel(lv(frame) + 40); frame.insp.noTip = true; frame.insp.hover = false; frame.insp:EnableMouse(false); frame.insp:Hide()
  frame:HookScript("OnHide", function() frame.insp:Hide() end)
  -- the text screens (Sets, Today, Trade, Ledger)
  frame.panel = fs(frame, "body", 14); frame.panel:SetPoint("TOPLEFT", 40, -200); frame.panel:SetWidth(WINW - 80); frame.panel:SetJustifyH("LEFT"); frame.panel:SetJustifyV("TOP"); frame.panel:SetSpacing(6)
  frame.panel:SetTextColor(0.9, 0.86, 0.74)
  frame.rows = {}
  for i = 1, 14 do
    local b = CreateFrame("Button", nil, frame, "BackdropTemplate")
    b:SetSize(WINW - 80, 26); b:SetPoint("TOPLEFT", 40, -200 - (i - 1) * 30)
    b:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); b:SetBackdropColor(0.097, 0.087, 0.066, 0.9); b:SetBackdropBorderColor(0.4, 0.33, 0.2, 0.8)
    b.left = fs(b, "body", 14); b.left:SetPoint("LEFT", 10, 0); b.left:SetJustifyH("LEFT")
    b.right = fs(b, "head", 12); b.right:SetPoint("RIGHT", -10, 0); b.right:SetJustifyH("RIGHT"); b.right:SetTextColor(GOLDC[1], GOLDC[2], GOLDC[3])
    b.fillBg = b:CreateTexture(nil, "ARTWORK"); b.fillBg:SetColorTexture(1, 1, 1, 0.07); b.fillBg:SetHeight(3); b.fillBg:SetPoint("BOTTOMLEFT", 1, 1); b.fillBg:SetPoint("BOTTOMRIGHT", -1, 1)
    b.fill = b:CreateTexture(nil, "OVERLAY"); b.fill:SetColorTexture(GOLDC[1], GOLDC[2], GOLDC[3], 0.9); b.fill:SetHeight(3); b.fill:SetPoint("BOTTOMLEFT", 1, 1); b.fill:SetWidth(1)
    b:SetScript("OnEnter", function(self) self:SetBackdropColor(0.164, 0.147, 0.111, 0.95); self:SetBackdropBorderColor(GOLDC[1], GOLDC[2], GOLDC[3], 1) end)
    b:SetScript("OnLeave", function(self) self:SetBackdropColor(0.097, 0.087, 0.066, 0.9); self:SetBackdropBorderColor(0.4, 0.33, 0.2, 0.8) end)
    b:SetScript("OnClick", function(self) if self.act then self.act() end end)
    frame.rows[i] = b
  end

  -- footer
  frame.msg = fs(frame, "body", 14); frame.msg:SetPoint("BOTTOMLEFT", 40, 56); frame.msg:SetWidth(480); frame.msg:SetJustifyH("LEFT"); frame.msg:SetTextColor(0.9, 0.84, 0.62)
  frame.prev = gbtn(frame, "<", 36, 24, function() if view.mode == "album" then view.albumPage = math.max(1, (view.albumPage or 1) - 1) elseif view.mode == "sets" then view.setPage = math.max(0, (view.setPage or 0) - 1) elseif view.mode == "trade" then view.tradePage = math.max(0, (view.tradePage or 0) - 1) elseif view.mode == "shop" then view.shopPage = math.max(0, (view.shopPage or 0) - 1) else view.page = view.page - 1 end; RG.ArcadeRefresh(true) end)
  frame.prev:SetPoint("BOTTOM", 230, 58)
  frame.next = gbtn(frame, ">", 36, 24, function() if view.mode == "album" then view.albumPage = (view.albumPage or 1) + 1 elseif view.mode == "sets" then view.setPage = (view.setPage or 0) + 1 elseif view.mode == "trade" then view.tradePage = (view.tradePage or 0) + 1 elseif view.mode == "shop" then view.shopPage = (view.shopPage or 0) + 1 else view.page = view.page + 1 end; RG.ArcadeRefresh(true) end)
  frame.next:SetPoint("BOTTOM", 330, 58)
  frame.pageText = fs(frame, "head", 14); frame.pageText:SetPoint("BOTTOM", 280, 62); frame.pageText:SetTextColor(1, 0.933, 0.709)
  frame.buyNow = function(many, dn)
    local got, free, notes, meta
    if many == true then got, free, notes, meta = RG.ArcadeOpenMany() else got, free, notes, meta = RG.ArcadeOpenPack(type(many) == "string" and many or nil, dn) end
    if not got then say(free or "") return end
    if meta and meta.bonus then playSound(nil, nil, "reward") end
    showReveal(got, notes, meta); RG.ArcadeRefresh(true)
  end
  -- footer: Arena and Duel on the left, the three packs in the middle, Sell extras and Open all on the right
  frame.packBtns = {}
  local PX = { -126, -6, 114 }
  for i, kind in ipairs(PACK_ORDER) do
    local b = gbtn(frame, PACKS[kind].name, 114, 40, function() frame.buyNow(kind) end, false)
    b:SetPoint("BOTTOM", PX[i], 16)
    b.label:ClearAllPoints(); b.label:SetPoint("TOP", 0, -7)
    b.sub = fs(b, "body", 11); b.sub:SetPoint("BOTTOM", 0, 7); b.sub:SetTextColor(0.769, 0.687, 0.522)
    -- the odds, on hover
    b:HookScript("OnEnter", function(self)
      local o = RG.ArcadePackOdds(kind)
      GameTooltip:SetOwner(self, "ANCHOR_TOP")
      GameTooltip:AddLine(PACKS[kind].name .. " odds")
      GameTooltip:AddDoubleLine("Mythic", "1 in " .. o.mythic .. " packs", 1, 0.9, 0.55, 1, 1, 1)
      GameTooltip:AddDoubleLine("Holo or full art", string.format("%d%% of packs", math.floor(o.holo * 100 + 0.5)), 0.7, 0.35, 0.95, 1, 1, 1)
      GameTooltip:AddDoubleLine("Full art", string.format("%d%% of packs", math.floor(o.full * 100 + 0.5)), 1, 0.6, 0.1, 1, 1, 1)
      GameTooltip:AddLine(o.size .. " cards; the last " .. (o.rares > 1 and (o.rares .. " are") or "one is") .. " rare or better.", 0.8, 0.8, 0.8, true)
      GameTooltip:AddLine("After " .. o.pity .. " packs without a holo, the next one has one.", 0.8, 0.8, 0.8, true)
      GameTooltip:Show()
    end)
    b:HookScript("OnLeave", function() GameTooltip:Hide() end)
    frame.packBtns[kind] = b
  end
  frame.buy = frame.packBtns.normal
  -- the normal pack is what people come here to do: it is the big gold button, the rest stay quiet
  do
    local b = frame.packBtns.normal
    b:SetSize(130, 46); b:ClearAllPoints(); b:SetPoint("BOTTOM", PX[1] - 5, 13)
    b.Paint = function(self, hover)
      local on = self.enabled
      self:SetBackdropColor(on and (hover and 0.42 or 0.32) or 0.12, on and (hover and 0.29 or 0.21) or 0.1, on and 0.06 or 0.14, 0.98)
      self:SetBackdropBorderColor(on and 1 or 0.3, on and 0.84 or 0.27, on and 0.4 or 0.22, 1)
      self.label:SetTextColor(on and 1 or 0.45, on and 0.95 or 0.43, on and 0.75 or 0.5)
    end
    b.glow = b:CreateTexture(nil, "BACKGROUND"); b.glow:SetTexture(MEDIA .. "Soft"); b.glow:SetBlendMode("ADD")
    b.glow:SetPoint("TOPLEFT", -22, 16); b.glow:SetPoint("BOTTOMRIGHT", 22, -16); b.glow:SetVertexColor(1, 0.8, 0.35, 0.3)
    b:SetScript("OnUpdate", function(self)
      local t = GetTime and GetTime() or 0
      self.glow:SetAlpha(self.enabled and (0.35 + 0.25 * math.sin(t * 2)) or 0)
    end)
    b:Paint(false)
  end
  frame.buyAll = gbtn(frame, "All", 64, 28, function() frame.buyNow(true) end)
  frame.buyAll:SetPoint("BOTTOM", 329, 22); frame.buyAll:Hide()
  frame.duel = gbtn(frame, "Duel", 64, 28, function()
    local win, mine, foe, mf, ff, prize, goal = RG.ArcadeDuel()
    if win == nil then say(mine or "") return end
    say((win and ("Won! +" .. prize .. " coins.") or "Lost.") .. " " .. mine.name .. " (" .. FNAME[mf] .. ") vs " .. foe.name .. " (" .. FNAME[ff] .. ")" .. (goal and ("  ·  " .. goal) or ""))
    RG.ArcadeRefresh(true)
  end)
  frame.duel:SetPoint("BOTTOM", -231, 22)
  frame.sell = gbtn(frame, "Sell extras", 102, 28, function()
    local n, coins, g, rn, rc = RG.ArcadeSellExtras()
    local split = (rn or 0) > 0 and (" (" .. rn .. " refund" .. (rn > 1 and "s" or "") .. " for " .. rc .. ", " .. (n - rn) .. " at the normal price for " .. (coins - rc) .. ")") or ""
    say(n > 0 and ("Sold " .. n .. " extra cards for " .. coins .. " coins" .. split .. ". One of each print is kept." .. (g and ("  ·  " .. g) or "")) or "No extras to sell: you keep one of each print.")
    RG.ArcadeRefresh(true)
  end)
  frame.sell:SetPoint("BOTTOM", 240, 22)
  frame.arena = gbtn(frame, "Arena", 70, 28, function() if RG.ShowBattle then frame:Hide(); RG.ShowBattle() end end)
  frame.arena:SetPoint("BOTTOM", -308, 22)
  -- fit small screens
  local ph = UIParent and UIParent.GetHeight and UIParent:GetHeight()
  if type(ph) == "number" and ph > 0 and ph < WINH + 30 then frame:SetScale(math.max(0.6, (ph - 30) / WINH)) end
end

local function categoryLine(a)
  local have, tot = { 0, 0, 0, 0 }, { 0, 0, 0, 0 }
  for _, c in ipairs(CARDS) do tot[c.kind] = tot[c.kind] + 1; if owned(a, c.id) > 0 then have[c.kind] = have[c.kind] + 1 end end
  return string.format("Items %d/%d  ·  NPCs %d/%d  ·  Places %d/%d  ·  Raiders %d/%d", have[1], tot[1], have[2], tot[2], have[3], tot[3], have[4], tot[4])
end

-- page widgets for the Today, Trade, Ledger and Sets screens: stat tiles, section titles, bars, aligned rows
local PG = { tiles = {}, heads = {}, bars = {}, kvs = {}, boxes = {} }
local PGX, PGW = 40, WINW - 80
local DIM = { 0.769, 0.687, 0.522 }
local function pgReset() for _, list in pairs(PG) do for _, w in ipairs(list) do w:Hide() end end end
local function pgPlace(w, x, y, wd, ht) w:ClearAllPoints(); w:SetPoint("TOPLEFT", frame, "TOPLEFT", x, -y); w:SetSize(wd, ht); w:Show() end
local function pgTile(i, x, y, wd, ht, value, label, sub, col)
  local t = PG.tiles[i]
  if not t then
    t = CreateFrame("Frame", nil, frame, "BackdropTemplate"); t:SetFrameLevel(lv(frame) + 2)
    t:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); t:SetBackdropColor(0.088, 0.078, 0.06, 0.95); t:SetBackdropBorderColor(0.5, 0.41, 0.24, 0.75)
    t.accent = t:CreateTexture(nil, "ARTWORK"); t.accent:SetColorTexture(1, 1, 1, 1); t.accent:SetPoint("TOPLEFT", 1, -1); t.accent:SetPoint("TOPRIGHT", -1, -1); t.accent:SetHeight(2)
    t.lab = fs(t, "head", 10.5); t.lab:SetPoint("TOPLEFT", 14, -12); t.lab:SetTextColor(DIM[1], DIM[2], DIM[3])
    t.val = fs(t, "title", 26); t.val:SetPoint("TOPLEFT", 14, -26); t.val:SetJustifyH("LEFT")
    t.sub = fs(t, "body", 12); t.sub:SetPoint("BOTTOMLEFT", 14, 9); t.sub:SetJustifyH("LEFT"); t.sub:SetTextColor(0.769, 0.687, 0.522)
    if t.sub.SetWordWrap then t.sub:SetWordWrap(false) end
    PG.tiles[i] = t
  end
  col = col or GOLDC
  pgPlace(t, x, y, wd, ht)
  t.accent:SetColorTexture(col[1], col[2], col[3], 0.9)
  t.lab:SetText(string.upper(label)); t.val:SetText(value); t.val:SetTextColor(col[1], col[2], col[3])
  t.sub:SetWidth(wd - 28); t.sub:SetText(sub or "")
  return t
end
local function pgHead(i, y, text, right)
  local h = PG.heads[i]
  if not h then
    h = CreateFrame("Frame", nil, frame); h:SetFrameLevel(lv(frame) + 2)
    h.t = fs(h, "head", 12.5); h.t:SetPoint("TOPLEFT", 0, 0); h.t:SetTextColor(GOLDC[1], GOLDC[2], GOLDC[3])
    h.r = fs(h, "body", 12); h.r:SetPoint("TOPRIGHT", 0, -1); h.r:SetJustifyH("RIGHT"); h.r:SetTextColor(0.769, 0.687, 0.522)
    h.line = h:CreateTexture(nil, "ARTWORK"); h.line:SetColorTexture(0.72, 0.58, 0.3, 0.4); h.line:SetHeight(1); h.line:SetPoint("BOTTOMLEFT", 0, 0); h.line:SetPoint("BOTTOMRIGHT", 0, 0)
    PG.heads[i] = h
  end
  pgPlace(h, PGX, y, PGW, 20)
  h.t:SetText(string.upper(text)); h.r:SetText(right or "")
end
local function pgBar(i, y, label, right, frac, col)
  local b = PG.bars[i]
  if not b then
    b = CreateFrame("Frame", nil, frame); b:SetFrameLevel(lv(frame) + 2)
    b.l = fs(b, "body", 13); b.l:SetPoint("TOPLEFT", 0, 0); b.l:SetJustifyH("LEFT")
    b.r = fs(b, "head", 12); b.r:SetPoint("TOPRIGHT", 0, 0); b.r:SetJustifyH("RIGHT")
    b.bg = b:CreateTexture(nil, "ARTWORK"); b.bg:SetColorTexture(1, 1, 1, 0.09); b.bg:SetHeight(6); b.bg:SetPoint("BOTTOMLEFT", 0, 2); b.bg:SetPoint("BOTTOMRIGHT", 0, 2)
    b.fill = b:CreateTexture(nil, "OVERLAY"); b.fill:SetHeight(6); b.fill:SetPoint("BOTTOMLEFT", 0, 2)
    PG.bars[i] = b
  end
  pgPlace(b, PGX, y, PGW, 36)
  col = col or GOLDC
  frac = math.max(0, math.min(1, frac or 0))
  b.l:SetText(label); b.r:SetText(right or ""); b.r:SetTextColor(col[1], col[2], col[3])
  b.fill:SetColorTexture(col[1], col[2], col[3], 0.95); b.fill:SetWidth(math.max(1, PGW * frac)); b.fill:SetShown(frac > 0)
end
local function pgKV(i, x, y, wd, label, value)
  local r = PG.kvs[i]
  if not r then
    r = CreateFrame("Frame", nil, frame); r:SetFrameLevel(lv(frame) + 2)
    r.l = fs(r, "body", 13); r.l:SetPoint("LEFT", 2, 0); r.l:SetTextColor(0.922, 0.823, 0.626)
    r.v = fs(r, "head", 13); r.v:SetPoint("RIGHT", -2, 0); r.v:SetJustifyH("RIGHT"); r.v:SetTextColor(1, 0.97, 0.88)
    r.line = r:CreateTexture(nil, "ARTWORK"); r.line:SetColorTexture(1, 1, 1, 0.08); r.line:SetHeight(1); r.line:SetPoint("BOTTOMLEFT", 0, 0); r.line:SetPoint("BOTTOMRIGHT", 0, 0)
    PG.kvs[i] = r
  end
  pgPlace(r, x, y, wd, 26)
  r.l:SetText(label); r.v:SetText(value)
end
local function pgBox(i, y, ht, title, text, col)
  local b = PG.boxes[i]
  if not b then
    b = CreateFrame("Frame", nil, frame, "BackdropTemplate"); b:SetFrameLevel(lv(frame) + 2)
    b:SetBackdrop({ bgFile = WHITE, edgeFile = WHITE, edgeSize = 1 }); b:SetBackdropColor(0.06, 0.053, 0.041, 0.94); b:SetBackdropBorderColor(0.5, 0.41, 0.24, 0.7)
    b.bar = b:CreateTexture(nil, "ARTWORK"); b.bar:SetPoint("TOPLEFT", 1, -1); b.bar:SetPoint("BOTTOMLEFT", 1, 1); b.bar:SetWidth(4)
    b.title = fs(b, "head", 14); b.title:SetPoint("TOPLEFT", 20, -12); b.title:SetJustifyH("LEFT")
    b.text = fs(b, "body", 13); b.text:SetJustifyH("LEFT"); b.text:SetJustifyV("TOP"); b.text:SetSpacing(4); b.text:SetTextColor(0.982, 0.877, 0.666)
    PG.boxes[i] = b
  end
  pgPlace(b, PGX, y, PGW, ht)
  col = col or GOLDC
  b.bar:SetColorTexture(col[1], col[2], col[3], 1)
  b.title:SetText(title or ""); b.title:SetTextColor(col[1], col[2], col[3])
  b.text:ClearAllPoints(); b.text:SetPoint("TOPLEFT", 20, (title and title ~= "") and -36 or -12); b.text:SetWidth(PGW - 40); b.text:SetText(text or "")
  return b
end

local function showRows(n) for i, b in ipairs(frame.rows) do b:SetShown(i <= n) end end

function RG.ArcadeRefresh(keepMsg)
  if not (frame and frame:IsShown()) then return end
  local a, own, total, prints = RG.ArcadeStats()
  dailyCheck()
  frame.coins:SetText(GOLDHEX .. (a.coins or 0) .. "|r")
  frame.free:SetText((a.free or 0) > 0 and ((a.free) .. " free pack" .. (a.free > 1 and "s" or "")) or "")
  frame.sub:SetText(GOLDHEX .. own .. "|r of " .. total .. " cards   ·   " .. GOLDHEX .. prints .. "|r prints   ·   " .. GOLDHEX .. (a.wins or 0) .. "|r duel wins\n|cffa89bc9" .. categoryLine(a) .. "|r")
  if keepMsg ~= true then frame.msg:SetText("") end
  local cards = view.mode == "cards"
  local album = view.mode == "album"
  for _, cell in ipairs(cells) do
    if not (cards or album) then cell:Hide() end
    if rawget(cell, "albName") then cell.albName:Hide(); cell.albKind:Hide(); cell.albTag:Hide() end   -- (the Album's labels for missing cards)
    cell:SetAlpha(1)   -- (the Album draws missing cards faint)
  end
  for _, w in ipairs({ frame.albPrev, frame.albNext, frame.albTitle, frame.albOpen }) do w:SetShown(album) end
  frame.tradeSwitch:SetShown(view.mode == "trade")
  if view.mode == "trade" then frame.tradeSwitch:SetText(view.tradeSub == "friends" and "Trade with your party" or "Friends' albums") end
  frame.panel:SetText("")
  pgReset()
  frame.searchBox:SetShown(cards); frame.searchHint:SetShown(cards and (view.search or "") == "")
  frame.sortBtn:SetShown(cards); frame.showBtn:SetShown(cards)
  frame.sortBtn:SetText("Sort: " .. SORTS[view.sort]); frame.showBtn:SetText("Show: " .. SHOWS[view.show])
  for k, b in pairs(frame.filters) do b:SetShown(cards); b:SetActive(cards and not view.showcase and k == view.kind) end
  frame.showcase:SetShown(cards); frame.showcase:SetActive(cards and view.showcase)
  for k, t in pairs(frame.modes) do t:SetActive(k == view.mode) end
  -- the Today tab says when there is something waiting: a free pack to open, or goals still to do
  do
    local g, n = todaysGoals(a), 0
    for _ in pairs(g.done or {}) do n = n + 1 end
    local t = frame.modes.today
    if t and t.label then t.label:SetText((a.free or 0) > 0 and "TODAY  |cff7be08a•|r" or (n < #g.pick and ("TODAY  " .. n .. "/" .. #g.pick) or "TODAY")) end
  end
  frame.prev:SetShown(cards or album); frame.next:SetShown(cards or album); frame.pageText:SetShown(cards or album)
  showRows(0)
  for _, fn in ipairs(RG.ArcadeViewHooks or {}) do
    local ok, err = pcall(fn, view, { frame = frame, a = a, PGW = PGW, PGX = PGX, say = say, pgHead = pgHead, pgBox = pgBox, PACKS = PACKS, PACK_ORDER = PACK_ORDER,
      tokens = function(kind) return tokenCount(a, kind) end, price = packPrice })
    if not ok then if RG.RecordError then pcall(RG.RecordError, err) elseif RG.Debug then RG.Debug(err) end end
  end

  if album then
    -- one set at a time, like a binder page: the cards you have in their best print, empty slots for the rest
    claimSets(a)   -- (a stage finished by a trade or craft pays here too)
    local sets = getSets()
    local st
    for _, x in ipairs(sets) do if x.name == view.album then st = x end end
    if not st then st = sets[1]; view.album = st and st.name end
    if st then
      local n = #st.cards
      local pages = math.max(1, math.ceil(n / #cells))
      view.albumPage = math.max(1, math.min(view.albumPage or 1, pages))
      for i, cell in ipairs(cells) do
        local c = st.cards[(view.albumPage - 1) * #cells + i]
        local missing = c and owned(a, c.id) == 0
        -- (a WoW Forever original nobody in your guild has found yet: only its outline, ArcadeFirstEdition.lua)
        local hidden = missing and RG.ArcadeUndiscovered and RG.ArcadeUndiscovered(c)
        -- a card you don't have: the card itself, faint, so you can see what you're looking for
        if hidden then paint(cell, c, nil); rawset(cell, "known", false); cell:SetAlpha(0.85)
        elseif missing then paint(cell, c, 1, 0); rawset(cell, "known", false); cell:SetAlpha(0.33)
        else paint(cell, c, c and bestFinish(a, c.id), c and owned(a, c.id)) end
        if missing then
          if not rawget(cell, "albName") then
            cell.albName = fs(cell, "head", 12); cell.albName:SetPoint("CENTER", cell, "CENTER", 0, -8)
            cell.albName:SetWidth(cell:GetWidth() - 14); cell.albName:SetJustifyH("CENTER")
            if cell.albName.SetWordWrap then cell.albName:SetWordWrap(true) end
            -- (on its own frame above the card, so the card's faintness doesn't fade it)
            cell.albTag = CreateFrame("Frame", nil, frame); cell.albTag:SetAllPoints(cell); cell.albTag:SetFrameLevel(lv(frame) + 8)
            cell.albKind = fs(cell.albTag, "head", 11); cell.albKind:SetPoint("CENTER", cell.albTag, "CENTER", 0, -4); cell.albKind:SetJustifyH("CENTER")
            cell.albKind:SetShadowColor(0, 0, 0, 1); cell.albKind:SetShadowOffset(1, -1)
          end
          local tc = TIER[c.tier][3]
          cell.albName:SetText(""); cell.albName:SetTextColor(tc[1] * 0.75, tc[2] * 0.75, tc[3] * 0.75)   -- (the faint card shows its name)
          local kind = c.kind == 1 and "Item" or (c.kind == 3 and "Place" or (c.kind == 2 and ((c.text or ""):find("[Bb]oss") and "Boss" or ((c.text or ""):find("^Dungeon elite") and "Elite" or "Creature")) or ""))
          cell.albKind:SetText("MISSING\n" .. kind:upper()); cell.albKind:SetTextColor(1, 0.93, 0.74)
          if st.field and RG.ArcadeFieldLabel then local t, col = RG.ArcadeFieldLabel(c); cell.albKind:SetText(t); cell.albKind:SetTextColor(col[1], col[2], col[3]) end
          if hidden then cell.albKind:SetText("? ? ?\nUNDISCOVERED"); cell.albKind:SetTextColor(0.75, 0.7, 0.95) end
          cell.albTag:Show(); cell.albKind:Show()
        end
      end
      frame.pageText:SetText(view.albumPage .. " / " .. pages)
      frame.prev:SetEnabled(view.albumPage > 1); frame.next:SetEnabled(view.albumPage < pages)
      local clearedHere = st.dungeon and not st.soon and select(2, RG.ArcadeDungeonPacks(st.name))
      frame.albTitle:SetText((RG.ArcadeSetTag and RG.ArcadeSetTag(st) or "") .. st.name .. ((st.dungeon and st.lo) and ("|cffa89bc9  ·  " .. (st.lo == st.hi and ("level " .. st.lo) or ("levels " .. st.lo .. "-" .. st.hi)) .. "|r") or "") .. (clearedHere and "  |cff7be08acleared|r" or ""))
      frame.albNext:ClearAllPoints()
      frame.albNext:SetPoint("LEFT", frame.albTitle, "LEFT", math.min(frame.albTitle:GetStringWidth() or 300, 430) + 10, 0)
      -- the stages (under the title, where the collection's totals usually are)
      a.setStage = a.setStage or {}
      local paid = a.setStage[st.name] or ((a.setsDone or {})[st.name] and 1 or 0)
      local parts = {}
      for k, sg in ipairs(RG.ARCADE_STAGES) do
        local have = setProgress(a, st, k)
        local hex = string.format("|cff%02x%02x%02x", math.floor(sg[3][1] * 255), math.floor(sg[3][2] * 255), math.floor(sg[3][3] * 255))
        parts[#parts + 1] = hex .. sg[1] .. "|r " .. (paid >= k and "|cff7be08adone|r" or (have .. "/" .. n))
      end
      local nextStage = RG.ARCADE_STAGES[paid + 1]
      if st.field and RG.ArcadeFieldAlbum then
        RG.ArcadeFieldAlbum(st, frame, parts, nextStage and (nextStage[1] .. ": " .. nextStage[2] .. " pays " .. RG.ArcadeStageText(st, paid + 1)) or nil)
      elseif st.soon then
        frame.albTitle:SetText(st.name .. "  |cffa89bc9·  coming soon|r")
        frame.sub:SetText("|cffa89bc9This dungeon's cards arrive once WoW Forever's game data has its bosses and loot.\nWaypath+ adds them by itself in an update: nothing to do but wait.|r")
      else
      frame.sub:SetText(n .. " cards     " .. table.concat(parts, "     ") .. "\n|cffa89bc9" .. (nextStage and (nextStage[1] .. ": " .. nextStage[2] .. " pays " .. RG.ArcadeStageText(st, paid + 1)) or "Every stage finished: a gold set") .. "|r")
      end
      -- a dungeon's pack
      if st.dungeon and RG.ArcadeDunPools and RG.ArcadeDunPools[st.name] then
        local have, cleared = RG.ArcadeDungeonPacks(st.name)
        if have > 0 then frame.albOpen:SetText("Open " .. st.name:gsub("^The ", "") .. " pack (" .. have .. ")"); frame.albOpen:SetEnabled(true)
        elseif cleared then frame.albOpen:SetText("Buy a pack: " .. PACKS.dungeon.price .. " coins"); frame.albOpen:SetEnabled((a.coins or 0) >= PACKS.dungeon.price)
        else frame.albOpen:SetText(st.raid and "Defeat one of its bosses to earn its packs" or "Clear it to earn its packs"); frame.albOpen:SetEnabled(false) end
        frame.albOpen:Show()
      elseif not st.field then frame.albOpen:Hide() end
      for _, fn in ipairs(RG.ArcadeAlbumHooks or {}) do pcall(fn, st, frame) end   -- (a raid page: its size, opening day and photos)
    end
  end

  if cards then
    local list = collectionList(a)
    local pages = math.max(1, math.ceil(#list / #cells))
    view.page = math.max(1, math.min(view.page, pages))
    for i, cell in ipairs(cells) do
      local c = list[(view.page - 1) * #cells + i]
      paint(cell, c, c and bestFinish(a, c.id), c and owned(a, c.id))
    end
    frame.pageText:SetText(view.page .. " / " .. pages .. (view.set and ("  ·  " .. view.set) or ""))
    frame.prev:SetEnabled(view.page > 1); frame.next:SetEnabled(view.page < pages)
    if #list == 0 then frame.panel:ClearAllPoints(); frame.panel:SetPoint("TOPLEFT", 40, -260); frame.panel:SetText(view.showcase and "|cff9a96b0Your showcase is empty. Open a card you own and choose Showcase to pin it here.|r" or "|cff9a96b0Nothing matches. Change the search or the filters.|r") end
  elseif view.mode == "sets" then
    local sets = getSets()
    if view.setSection and view.setSection ~= "all" and RG.ArcadeSetSection then
      local only = {}
      for _, x in ipairs(sets) do if RG.ArcadeSetSection(x) == view.setSection then only[#only + 1] = x end end
      sets = only
    end
    local per = 14
    local pages = math.max(1, math.ceil(#sets / per))
    local pg = math.max(0, math.min(view.setPage or 0, pages - 1)); view.setPage = pg
    local first = pg * per
    pgHead(1, 196, (RG.ArcadeSectionName and RG.ArcadeSectionName(view.setSection)) or "Sets", "Bronze, silver and gold rewards   ·   click one to open it in the Album   ·   " .. #sets .. " sets")
    showRows(math.max(0, math.min(per, #sets - first)))
    for i = 1, per do
      local s = sets[first + i]
      local b = frame.rows[i]
      b:ClearAllPoints(); b:SetPoint("TOPLEFT", 40, -228 - (i - 1) * 28)   -- (the section chips sit above the heading)
      if s then
        -- the stage you're working on: its progress, and the medal of the last one finished
        a.setStage = a.setStage or {}
        local paid = a.setStage[s.name] or ((a.setsDone or {})[s.name] and 1 or 0)
        local stage = math.min(3, paid + 1)
        local have = setProgress(a, s, stage)
        local sg = RG.ARCADE_STAGES[stage]
        local medal = paid > 0 and RG.ARCADE_STAGES[paid] or nil
        local function hex(c) return string.format("|cff%02x%02x%02x", math.floor(c[1] * 255), math.floor(c[2] * 255), math.floor(c[3] * 255)) end
        local tag = ((not view.setSection or view.setSection == "all") and RG.ArcadeSetTag) and RG.ArcadeSetTag(s) or ""   -- (one section shown: no need to tag each row)
        b.left:SetText(tag .. (paid >= 3 and "|cff7be08a" or "|cfff4ecd8") .. s.name:gsub("^Field Guide: ", "") .. "|r" .. (medal and ("   " .. hex(medal[3]) .. medal[1] .. "|r") or ""))
        b.right:SetText(s.soon and "|cffa89bc9coming soon|r" or paid >= 3 and "|cff7be08aall three stages|r" or (hex(sg[3]) .. sg[1] .. "|r " .. have .. "/" .. #s.cards .. "   |cffa89bc9" .. RG.ArcadeStageText(s, stage) .. "|r"))
        b.fill:Show(); b.fillBg:Show()
        local fc = paid >= 3 and { 0.48, 0.88, 0.54 } or sg[3]
        b.fill:SetColorTexture(fc[1], fc[2], fc[3], 0.95); b.fill:SetWidth(math.max(1, (PGW - 2) * (paid >= 3 and 1 or have / math.max(1, #s.cards))))
        b.act = function() view.album = s.name; view.albumPage = 1; view.mode = "album"; RG.ArcadeRefresh(true) end
      end
    end
    frame.prev:Show(); frame.next:Show(); frame.pageText:Show()
    frame.pageText:SetText((pg + 1) .. " / " .. pages)
    frame.prev:SetEnabled(pg > 0); frame.next:SetEnabled(pg + 1 < pages)
  elseif view.mode == "today" then
    local g = todaysGoals(a)
    local tw = (PGW - 2 * 16) / 3
