        if s2 then for f = 1, 4 do if (s2[f] or 0) >= 1 then list[#list + 1] = { c = c, f = f, n = s2[f] } end end end
      end
    end
    table.sort(list, function(x, y)
      local ex, ey = x.n >= 2, y.n >= 2
      if ex ~= ey then return ex end
