function RG.ShowArcade()
  if WaypathFrame and WaypathFrame.IsShown and WaypathFrame:IsShown() then WaypathFrame:Hide() end   -- never stack on the main window
  if not frame then build() end
  local a = store(); if a then a.seen = true end
  -- window size: the screen-fit scale, times your own setting (/wp cardscale 1.2)
  do
    local ph = UIParent and UIParent.GetHeight and UIParent:GetHeight()
    local fit = (type(ph) == "number" and ph > 0 and ph < WINH + 30) and math.max(0.6, (ph - 30) / WINH) or 1
    local mine = a and tonumber(a.uiScale) or 1
    frame:SetScale(fit * mine)
  end
  frame:Show(); RG.ArcadeRefresh()
  if a and a.giftPending and not a.giftDone and RG.ArcadeClaimGift then RG.ArcadeClaimGift() end
end

-- /wp cardcheck: goes through every card in the game and lists the ones whose picture cannot be shown (a creature the game has
-- no model for, an item it has no icon for). Takes about a minute; the result is a box to copy and paste.
local checking
local function cardCheck()
  if checking then RG.Print("The card check is already running.") return end
  local ok, m = pcall(CreateFrame, "DressUpModel", nil, UIParent)
  if not ok or not m then RG.Print("This game cannot show models, so there is nothing to check.") return end
  m:SetSize(64, 64); m:SetPoint("TOPLEFT", UIParent, "TOPLEFT", -200, 200); m:Show()
  checking = true
  local list, bad, i, n, pending = {}, {}, 0, 0, 0
  for _, c in ipairs(CARDS) do if c.kind == 1 or c.kind == 2 or c.kind == 3 then list[#list + 1] = c end end
  RG.Print("Checking " .. #list .. " cards... about a minute.")
  local step
  local function verdict(c)
    n = n + 1
    if c.kind == 2 then
      local id = RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
      local cid = RG.ARCADE_DUNGEON_CREATURE and RG.ARCADE_DUNGEON_CREATURE[c.name]
      local nd = WaypathDB and WaypathDB.arcade and WaypathDB.arcade.npcDisp
      if not id and cid then
        if not (nd and nd[cid]) then pending = pending + 1 end   -- (a WoW Forever creature: its model arrives once the game has seen it)
      elseif not id then bad[#bad + 1] = "NPC with no model (drawn scenery): " .. c.name
      else
        local fid = m.GetModelFileID and m:GetModelFileID()
        if not fid or fid == 0 then bad[#bad + 1] = "NPC model will not load: " .. c.name .. " (display " .. id .. ")" end
      end
    elseif c.kind == 1 then
      local ic = (RG.ARCADE_ITEM_ICON and RG.ARCADE_ITEM_ICON[c.ref]) or (C_Item and C_Item.GetItemIconByID and C_Item.GetItemIconByID(c.ref)) or (GetItemIcon and GetItemIcon(c.ref))
      if not ic or ic == 134400 then bad[#bad + 1] = "Item with no icon: " .. c.name .. " (" .. tostring(c.ref) .. ")" end
    elseif c.kind == 3 then
      if not ((RG.ARCADE_PLACE and RG.ARCADE_PLACE[c.name]) or (RG.ARCADE_PLACE_FILE and RG.ARCADE_PLACE_FILE[c.name])) then bad[#bad + 1] = "Place with no painting (drawn scenery): " .. c.name end
    end
  end
  local function finish()
    checking = false; m:Hide()
    local out = { "Waypath+ card check: " .. n .. " cards looked at, " .. #bad .. " problem(s)", "" }
    if pending > 0 then out[#out + 1] = pending .. " WoW Forever creature(s) show their model once you've seen them in game (until then, drawn scenery)."; out[#out + 1] = "" end
    for _, l in ipairs(bad) do out[#out + 1] = l end
    if #bad == 0 then out[#out + 1] = "Every picture loads." end
    RG.ShowErrors(table.concat(out, "\n"), "Waypath+ card check  ·  Ctrl+A, Ctrl+C to copy")
  end
  step = function()
    local prev = list[i]
    if prev then verdict(prev) end
    i = i + 1
    local c = list[i]
    if not c then finish() return end
    if c.kind == 2 then
      local id = RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
      if id and m.SetDisplayInfo then pcall(m.SetDisplayInfo, m, id) end
      if C_Timer then C_Timer.After(0.12, step) else step() end
    else
      step()
    end
  end
  step()
end

-- The same check runs by itself in the background: shortly after login, out of combat, and again whenever the card list
-- changes, each creature model is tried once and the ones this client cannot draw are remembered, so those cards go straight to
-- their own drawn scenery instead of showing an empty glow.
local scanning
local function scanModels()
  if scanning or not (CreateFrame and C_Timer and C_Timer.After) then return end
  local a = WaypathDB and WaypathDB.arcade
  if not a then return end
  local sig = #CARDS .. ":" .. tostring(RG.VERSION)
  if a.artScan == sig then return end
  local ok, m = pcall(CreateFrame, "DressUpModel", nil, UIParent)
  if not ok or not m or not m.SetDisplayInfo or not m.GetModelFileID then return end
  scanning = true
  m:SetSize(32, 32); m:SetPoint("TOPLEFT", UIParent, "TOPLEFT", -200, 200); m:Show()
  local list, i, prev, retried = {}, 0, nil, false
  for _, c in ipairs(CARDS) do
    local id = c.kind == 2 and RG.ARCADE_NPC and RG.ARCADE_NPC[c.name]
    if id then list[#list + 1] = id end
  end
  a.badModel = {}
  local function step()
    if InCombatLockdown and InCombatLockdown() then C_Timer.After(10, step) return end
    if prev then
      local fid = m:GetModelFileID()
      if (not fid or fid == 0) and not retried then retried = true; C_Timer.After(0.5, step) return end   -- slow to load: one more look
      if not fid or fid == 0 then a.badModel[prev] = true end
      retried = false
    end
    i = i + 1
    prev = list[i]
    if not prev then
      scanning = false; m:Hide(); a.artScan = sig
      local n = 0; for _ in pairs(a.badModel) do n = n + 1 end
      a.badCount = n
      return
    end
    pcall(m.SetDisplayInfo, m, prev)
    C_Timer.After(0.25, step)
  end
  step()
end
RG.ArcadeScanModels = scanModels
-- Creatures with no display id in the data (WoW Forever's own bosses: ArcadeDungeons.lua RG.ARCADE_DUNGEON_CREATURE):
-- shortly after login the game is asked for each one's model by its creature id, in a hidden model frame, and the
-- display id it reports is remembered (WaypathDB.arcade.npcDisp), so from then on the card shows its 3D model like
-- every other creature card. One the game draws but won't name is drawn by its creature id (-1); one it couldn't
-- load yet is asked again next session.
function RG.ArcadeResolveCreatures()
  local a = WaypathDB and WaypathDB.arcade
  local list = RG.ARCADE_DUNGEON_CREATURE
  if not a or not list or not (CreateFrame and C_Timer and C_Timer.After) or RG.ArcadeResolving then return end
  RG.ARCADE_NPC = RG.ARCADE_NPC or {}
  a.npcDisp = a.npcDisp or {}
  for name, cid in pairs(list) do
    local d = a.npcDisp[cid]
    if d and d > 0 and not RG.ARCADE_NPC[name] then RG.ARCADE_NPC[name] = d end
  end
  local todo = {}
  for name, cid in pairs(list) do if not RG.ARCADE_NPC[name] and not a.npcDisp[cid] then todo[#todo + 1] = { name, cid } end end
  table.sort(todo, function(x, y) return x[2] < y[2] end)
  if #todo == 0 then return end
  local ok, m = pcall(CreateFrame, "DressUpModel", nil, UIParent)
  if not ok or not m or not m.SetCreature then return end
  RG.ArcadeResolving = true
  m:SetSize(32, 32); m:SetPoint("TOPLEFT", UIParent, "TOPLEFT", -200, 200); m:Show()
  local i, tries, learned = 0, 0, 0
  local function step()
    if InCombatLockdown and InCombatLockdown() then C_Timer.After(10, step) return end
    local cur = todo[i]
    if cur then
      local okD, disp = false, nil
      if m.GetDisplayInfo then okD, disp = pcall(m.GetDisplayInfo, m) end
      local okF, fid = false, nil
      if m.GetModelFileID then okF, fid = pcall(m.GetModelFileID, m) end
      disp = (okD and type(disp) == "number" and disp > 0) and disp or nil
      fid = (okF and type(fid) == "number" and fid > 0) and fid or nil
      -- not loaded yet (the game is still asking the server about it): look again, three times at most
      if not disp and not fid and tries < 3 then tries = tries + 1; pcall(m.SetCreature, m, cur[2]); C_Timer.After(1, step) return end
      if disp then a.npcDisp[cur[2]] = disp; RG.ARCADE_NPC[cur[1]] = disp; learned = learned + 1
      elseif fid then a.npcDisp[cur[2]] = -1; learned = learned + 1 end
    end
    tries = 0; i = i + 1
    cur = todo[i]
    if not cur then
      RG.ArcadeResolving = nil; m:Hide()
      if learned > 0 and RG.ArcadeRefresh then RG.ArcadeRefresh(true) end
      return
    end
    pcall(m.SetCreature, m, cur[2])
    C_Timer.After(0.5, step)
  end
  step()
end
do
  local f = CreateFrame("Frame")
  f:RegisterEvent("PLAYER_ENTERING_WORLD")
  f:SetScript("OnEvent", function(self) self:UnregisterAllEvents(); C_Timer.After(20, function() pcall(RG.ArcadeResolveCreatures) end); C_Timer.After(45, function() pcall(scanModels) end) end)
end

local base = SlashCmdList.WAYPATH
SlashCmdList.WAYPATH = function(msg)
  local cmd = (msg or ""):match("^%s*(%S+)")
  cmd = cmd and cmd:lower()
  if cmd == "cardscale" then
    local a = store()
    local v = tonumber((msg or ""):match("^%s*%S+%s+(%S+)"))
    if a and v and v >= 0.6 and v <= 1.6 then a.uiScale = v; RG.Print("Card window size set to x" .. v .. ".") if frame and frame:IsShown() then RG.ShowArcade() end
    else RG.Print("/wp cardscale 1.2 makes the card window 20% bigger (0.6 to 1.6; 1 is normal). Now: x" .. tostring(a and a.uiScale or 1)) end
    return
  end
  if cmd == "cardscan" then local a = WaypathDB and WaypathDB.arcade; if a then a.artScan = nil end; RG.Print("Checking every creature picture in the background (about " .. math.ceil(#CARDS * 0.3 / 60) .. " minutes)."); scanModels() return end
  if cmd == "arcade" or cmd == "cards" then RG.ShowArcade() return end
  if cmd == "cardcheck" then cardCheck() return end
  if cmd == "cardcam" then
    local v = tonumber((msg or ""):match("^%s*%S+%s+(%S+)"))
    if v and v >= 0.3 and v <= 4 then RG.db.cardCam = v; RG.Print("Card cameras pulled back by x" .. v .. ". Reopen the card window to see it.") 
    elseif (msg or ""):lower():find("reset") then RG.db.cardCam = nil; RG.Print("Card cameras back to normal.")
    else RG.Print("/wp cardcam 1.3 pulls the creature cameras back 30% (bigger number = smaller creature; 1 is the default, /wp cardcam reset clears it). Now: x" .. tostring(RG.db.cardCam or 1)) end
    if RG.ArcadeRefresh then pcall(RG.ArcadeRefresh, true) end
    return
  end
  return base(msg)
end
